const FYFLATE_CURRENT_WINDOW_LABEL =
  (() => {
    try {
      return WebviewWindow.getCurrent()
        .label;
    } catch {
      return "";
    }
  })();

const FYFLATE_WINDOW_PARAMETERS =
  new URLSearchParams(
    window.location.search
  );

const FYFLATE_WINDOW_MODE =
  FYFLATE_WINDOW_PARAMETERS.get(
    "fyflateWindow"
  ) ||
  (FYFLATE_CURRENT_WINDOW_LABEL ===
  "settings-popout"
    ? "settings"
    : FYFLATE_CURRENT_WINDOW_LABEL.startsWith(
          "user-card-popout-"
        )
      ? "user-card"
      : null);

const FYFLATE_RELIABILITY_SESSION =
  FYFLATE_WINDOW_MODE
    ? null
    : beginReliabilitySession();

const FYFLATE_FLOATING_CARD_ID =
  FYFLATE_WINDOW_PARAMETERS.get(
    "cardId"
  ) ||
  (FYFLATE_CURRENT_WINDOW_LABEL.startsWith(
    "user-card-popout-"
  )
    ? FYFLATE_CURRENT_WINDOW_LABEL.slice(
        "user-card-popout-".length
      )
    : "");

function floatingUserCardStorageKey(
  cardId: string
) {
  return cardId
    ? `${FLOATING_USER_CARD_KEY}.${cardId}`
    : FLOATING_USER_CARD_KEY;
}

