type FloatingUserCardPayload = {
  version: 1;
  userCard: UserCardState;
  messages: TwitchChatMessage[];
};

function readFloatingUserCardPayload():
  FloatingUserCardPayload | null {
  if (
    FYFLATE_WINDOW_MODE !==
    "user-card"
  ) {
    return null;
  }

  try {
    const saved =
      localStorage.getItem(
        floatingUserCardStorageKey(
          FYFLATE_FLOATING_CARD_ID
        )
      );

    if (!saved) {
      return null;
    }

    const parsed =
      JSON.parse(saved) as
        | FloatingUserCardPayload
        | UserCardState;

    if (
      "userCard" in parsed &&
      parsed.userCard
    ) {
      return {
        version: 1,
        userCard:
          parsed.userCard,
        messages:
          Array.isArray(
            parsed.messages
          )
            ? parsed.messages
            : [],
      };
    }

    return {
      version: 1,
      userCard:
        parsed as UserCardState,
      messages: [],
    };
  } catch {
    return null;
  }
}

