function inboxTagPresentation(
  tag: InboxTag,
  language: ResolvedAppLanguage
) {
  const norwegian =
    language === "no";

  switch (tag) {
    case "private-message":
      return {
        label: norwegian ? "Privat" : "Private",
        color: "#f29bd4",
      };
    case "reply":
      return {
        label: norwegian ? "Svar" : "Reply",
        color: "#8fbdff",
      };
    case "mention":
      return {
        label: norwegian ? "Omtale" : "Mention",
        color: "#ffd166",
      };
    case "highlight":
      return {
        label: norwegian ? "Markert" : "Highlight",
        color: "#d2adff",
      };
    case "event":
      return {
        label: norwegian ? "Hendelse" : "Event",
        color: "#77df89",
      };
  }
}

