function formatStorageBytes(bytes: number) {
  const safe = Math.max(0, Number(bytes) || 0);
  if (safe < 1024) return `${safe} B`;
  if (safe < 1024 * 1024) return `${(safe / 1024).toFixed(1)} KB`;
  return `${(safe / (1024 * 1024)).toFixed(1)} MB`;
}

function youtubeQuotaPacificDayKey(
  now: Date =
    new Date()
) {
  const parts =
    new Intl.DateTimeFormat(
      "en-US",
      {
        timeZone:
          "America/Los_Angeles",
        year:
          "numeric",
        month:
          "2-digit",
        day:
          "2-digit",
      }
    ).formatToParts(
      now
    );

  const value =
    Object.fromEntries(
      parts.map(
        (
          part
        ) => [
          part.type,
          part.value,
        ]
      )
    );

  return `${value.year}-${value.month}-${value.day}`;
}

function emptyYouTubeQuotaTracker():
  YouTubeQuotaTracker {
  return {
    dayKey:
      youtubeQuotaPacificDayKey(),
    usedUnits:
      0,
    requestCount:
      0,
    errorCount:
      0,
    rateLimitCount:
      0,
    endpointCalls:
      {},
    cacheHits:
      0,
    cacheMisses:
      0,
    deduplicatedRequests:
      0,
    exhausted:
      false,
    lastAction:
      "",
    lastError:
      "",
    updatedAt:
      Date.now(),
  };
}

function readYouTubeQuotaTracker():
  YouTubeQuotaTracker {
  try {
    const raw =
      localStorage.getItem(
        YOUTUBE_QUOTA_TRACKER_KEY
      );

    if (!raw) {
      return emptyYouTubeQuotaTracker();
    }

    const parsed =
      JSON.parse(
        raw
      ) as Partial<YouTubeQuotaTracker>;

    const today =
      youtubeQuotaPacificDayKey();

    if (
      parsed.dayKey !==
      today
    ) {
      return emptyYouTubeQuotaTracker();
    }

    return {
      dayKey:
        today,
      usedUnits:
        Math.max(
          0,
          Number(
            parsed.usedUnits ||
            0
          )
        ),
      requestCount:
        Math.max(0, Number(parsed.requestCount || 0)),
      errorCount:
        Math.max(0, Number(parsed.errorCount || 0)),
      rateLimitCount:
        Math.max(0, Number(parsed.rateLimitCount || 0)),
      endpointCalls:
        parsed.endpointCalls && typeof parsed.endpointCalls === "object"
          ? parsed.endpointCalls
          : {},
      cacheHits:
        Math.max(0, Number(parsed.cacheHits || 0)),
      cacheMisses:
        Math.max(0, Number(parsed.cacheMisses || 0)),
      deduplicatedRequests:
        Math.max(0, Number(parsed.deduplicatedRequests || 0)),
      exhausted:
        parsed.exhausted ===
        true,
      lastAction:
        typeof parsed.lastAction ===
        "string"
          ? parsed.lastAction
          : "",
      lastError:
        typeof parsed.lastError === "string"
          ? parsed.lastError
          : "",
      updatedAt:
        Number(
          parsed.updatedAt ||
          Date.now()
        ),
    };
  } catch {
    return emptyYouTubeQuotaTracker();
  }
}

