function normalizeExternalUrl(
  value: string
) {
  if (
    value.startsWith(
      "//"
    )
  ) {
    return `https:${value}`;
  }

  return value;
}

function sevenTvPlatformForChatPlatform(
  platform: ChatPlatform | undefined
): SevenTvPlatform {
  if (
    platform ===
    "kick"
  ) {
    return "KICK";
  }

  if (
    platform ===
    "youtube"
  ) {
    return "GOOGLE";
  }

  return "TWITCH";
}

function sevenTvCosmeticsKey(
  platform: ChatPlatform | undefined,
  platformId: string
) {
  return `${sevenTvPlatformForChatPlatform(
    platform
  )}:${platformId}`;
}

function bestSevenTvImage(
  images: SevenTvImage[] | null | undefined
) {
  if (
    !Array.isArray(
      images
    ) ||
    images.length ===
      0
  ) {
    return null;
  }

  return [...images].sort(
    (a, b) =>
      b.scale -
        a.scale ||
      b.width -
        a.width
  )[0];
}

function sevenTvColorToCss(
  color: SevenTvColor | undefined,
  opacity = 1
) {
  if (
    !color
  ) {
    return "rgba(255,255,255,0)";
  }

  const alpha =
    Math.max(
      0,
      Math.min(
        255,
        Number(
          color.a
        )
      )
    ) /
    255;

  return `rgba(${color.r}, ${color.g}, ${color.b}, ${Math.max(
    0,
    Math.min(
      1,
      alpha *
        opacity
    )
  )})`;
}

function sevenTvPaintStyle(
  paint: SevenTvPaint | null | undefined
): CSSProperties {
  if (
    !paint?.data
      ?.layers
      ?.length
  ) {
    return {};
  }

  const backgrounds:
    string[] = [];
  const positions:
    string[] = [];
  const sizes:
    string[] = [];
  const repeats:
    string[] = [];

  for (
    const layer
    of paint.data.layers
  ) {
    const ty =
      layer.ty;
    const opacity =
      Number.isFinite(
        layer.opacity
      )
        ? Math.max(
            0,
            Math.min(
              1,
              layer.opacity
            )
          )
        : 1;

    if (
      ty.__typename ===
      "PaintLayerTypeSingleColor"
    ) {
      const color =
        sevenTvColorToCss(
          ty.color,
          opacity
        );

      backgrounds.push(
        `linear-gradient(${color}, ${color})`
      );
      positions.push(
        "center"
      );
      sizes.push(
        "100% 100%"
      );
      repeats.push(
        "no-repeat"
      );
      continue;
    }

    if (
      ty.__typename ===
        "PaintLayerTypeLinearGradient" ||
      ty.__typename ===
        "PaintLayerTypeRadialGradient"
    ) {
      const stops =
        (ty.stops || [])
          .map(
            (stop) =>
              `${sevenTvColorToCss(
                stop.color,
                opacity
              )} ${stop.at * 100}%`
          )
          .join(
            ", "
          );

      if (
        !stops
      ) {
        continue;
      }

      const repeating =
        ty.repeating
          ? "repeating-"
          : "";

      if (
        ty.__typename ===
        "PaintLayerTypeLinearGradient"
      ) {
        backgrounds.push(
          `${repeating}linear-gradient(${ty.angle || 0}deg, ${stops})`
        );
      } else {
        backgrounds.push(
          `${repeating}radial-gradient(${(
            ty.shape ||
            "CIRCLE"
          ).toLowerCase()}, ${stops})`
        );
      }

      positions.push(
        "center"
      );
      sizes.push(
        "100% 100%"
      );
      repeats.push(
        "no-repeat"
      );
      continue;
    }

    if (
      ty.__typename ===
      "PaintLayerTypeImage"
    ) {
      const image =
        bestSevenTvImage(
          ty.images
        );

      if (
        !image?.url
      ) {
        continue;
      }

      backgrounds.push(
        `url(${JSON.stringify(
          normalizeExternalUrl(
            image.url
          )
        )})`
      );
      positions.push(
        "center"
      );
      sizes.push(
        "auto 100%"
      );
      repeats.push(
        "repeat"
      );
    }
  }

  if (
    backgrounds.length ===
    0
  ) {
    return {};
  }

  const shadows =
    (paint.data.shadows || [])
      .map(
        (shadow) =>
          `drop-shadow(${shadow.offsetX}px ${shadow.offsetY}px ${shadow.blur}px ${sevenTvColorToCss(
            shadow.color
          )})`
      )
      .join(
        " "
      );

  return {
    display:
      "inline-block",
    color:
      "transparent",
    WebkitTextFillColor:
      "transparent",
    backgroundImage:
      backgrounds.join(
        ", "
      ),
    backgroundPosition:
      positions.join(
        ", "
      ),
    backgroundSize:
      sizes.join(
        ", "
      ),
    backgroundRepeat:
      repeats.join(
        ", "
      ),
    backgroundClip:
      "text",
    WebkitBackgroundClip:
      "text",
    filter:
      shadows ||
      undefined,
  };
}

function sevenTvPayloadToEmotes(
  payload: any
): ThirdPartyEmoteMap {
  const set =
    payload?.emote_set ||
    payload;

  const entries =
    Array.isArray(
      set?.emotes
    )
      ? set.emotes
      : [];

  const map:
    ThirdPartyEmoteMap =
    {};

  for (
    const entry
    of entries
  ) {
    const data =
      entry?.data ||
      entry?.emote ||
      entry;

    const id =
      String(
        data?.id ||
        entry?.id ||
        ""
      );

    const name =
      String(
        entry?.name ||
        data?.name ||
        ""
      );

    if (
      !id ||
      !name
    ) {
      continue;
    }

    const host =
      data?.host ||
      entry?.host ||
      {};

    const hostUrl =
      normalizeExternalUrl(
        String(
          host?.url ||
          `https://cdn.7tv.app/emote/${id}`
        )
      );

    const files =
      Array.isArray(
        host?.files
      )
        ? host.files
        : [];

    const preferredNames = [
      "2x.webp",
      "3x.webp",
      "1x.webp",
      "2x.avif",
      "3x.avif",
      "1x.avif",
      "2x.gif",
      "1x.gif",
    ];

    let fileName =
      "";

    for (
      const preferred
      of preferredNames
    ) {
      const found =
        files.find(
          (
            file: any
          ) =>
            file?.name ===
            preferred
        );

      if (
        found?.name
      ) {
        fileName =
          found.name;

        break;
      }
    }

    if (
      !fileName &&
      files[0]?.name
    ) {
      fileName =
        String(
          files[0].name
        );
    }

    map[
      name
    ] = {
      provider:
        "7tv",

      id,
      name,

      imageUrl:
        fileName
          ? `${hostUrl}/${fileName}`
          : `https://cdn.7tv.app/emote/${id}/2x.webp`,

      animated:
        Boolean(
          data?.animated ??
          entry?.animated
        ),
    };
  }

  return map;
}

function bttvPayloadToEmotes(
  payload: any
): ThirdPartyEmoteMap {
  const entries =
    Array.isArray(
      payload
    )
      ? payload
      : [
          ...(Array.isArray(
            payload?.channelEmotes
          )
            ? payload.channelEmotes
            : []),

          ...(Array.isArray(
            payload?.sharedEmotes
          )
            ? payload.sharedEmotes
            : []),
        ];

  const map:
    ThirdPartyEmoteMap =
    {};

  for (
    const entry
    of entries
  ) {
    const id =
      String(
        entry?.id ||
        ""
      );

    const name =
      String(
        entry?.code ||
        ""
      );

    if (
      !id ||
      !name ||
      entry?.modifier ===
        true
    ) {
      continue;
    }

    map[
      name
    ] = {
      provider:
        "bttv",

      id,
      name,

      imageUrl:
        `https://cdn.betterttv.net/emote/${id}/2x`,

      animated:
        Boolean(
          entry?.animated ||
          entry?.imageType ===
            "gif"
        ),
    };
  }

  return map;
}

