function readStringArray(
  key: string
): string[] {
  try {
    const raw =
      localStorage.getItem(
        key
      );

    const parsed =
      raw
        ? JSON.parse(
            raw
          )
        : [];

    return Array.isArray(
      parsed
    )
      ? parsed.filter(
          (
            value
          ): value is string =>
            typeof value ===
            "string"
        )
      : [];
  } catch {
    return [];
  }
}

