function readMentionInboxItems():
  MentionInboxItem[] {
  try {
    const raw =
      localStorage.getItem(
        MENTION_INBOX_ITEMS_KEY
      );

    const parsed = raw
      ? JSON.parse(raw)
      : [];

    if (!Array.isArray(parsed)) {
      return [];
    }

    const items = parsed
      .filter(
        (item): item is MentionInboxItem => {
          if (
            !item ||
            typeof item !== "object"
          ) {
            return false;
          }

          const candidate =
            item as Partial<MentionInboxItem>;
          const message =
            candidate.message as
              | Partial<TwitchChatMessage>
              | undefined;

          return Boolean(
            typeof candidate.id === "string" &&
            typeof candidate.channelId === "string" &&
            typeof candidate.channelLogin === "string" &&
            typeof candidate.channelDisplayName === "string" &&
            (candidate.platform === "twitch" ||
              candidate.platform === "youtube" ||
              candidate.platform === "kick") &&
            typeof candidate.capturedAt === "number" &&
            message &&
            typeof message.id === "string" &&
            typeof message.text === "string" &&
            typeof message.username === "string" &&
            Array.isArray(message.fragments)
          );
        }
      )
      .map((item) => {
        const hasStoredTags =
          Array.isArray(item.tags);
        let tags = normalizeInboxTags(
          item.tags,
          hasStoredTags
            ? undefined
            : item.reason || "mention"
        );

        // Older versions accidentally added the legacy "mention" fallback to
        // every saved event. Those entries did not store a separate mention
        // source, so remove only that false legacy label and keep the event.
        if (
          tags.includes("event") &&
          tags.includes("mention") &&
          typeof item.message.mentionText !== "string"
        ) {
          tags = tags.filter(
            (tag) => tag !== "mention"
          );
        }

        return {
          ...item,
          tags,
        };
      })
      .slice(
        -MENTION_INBOX_MAX_ITEMS
      );

    if (
      JSON.stringify(items) !==
      JSON.stringify(parsed)
    ) {
      localStorage.setItem(
        MENTION_INBOX_ITEMS_KEY,
        JSON.stringify(items)
      );
    }

    return items;
  } catch {
    return [];
  }
}

