function readSystemAppLanguage(): ResolvedAppLanguage {
  const language =
    typeof navigator ===
    "undefined"
      ? "en"
      : navigator.language.toLowerCase();

  return language === "no" ||
    language.startsWith("no-") ||
    language === "nb" ||
    language.startsWith("nb-") ||
    language === "nn" ||
    language.startsWith("nn-")
    ? "no"
    : "en";
}

