function openAppearanceAssetDatabase() {
  return new Promise<IDBDatabase>(
    (
      resolve,
      reject
    ) => {
      const request =
        indexedDB.open(
          APPEARANCE_ASSET_DB_NAME,
          1
        );

      request.onupgradeneeded =
        () => {
          if (
            !request.result.objectStoreNames.contains(
              APPEARANCE_ASSET_STORE_NAME
            )
          ) {
            request.result.createObjectStore(
              APPEARANCE_ASSET_STORE_NAME
            );
          }
        };

      request.onsuccess =
        () =>
          resolve(
            request.result
          );
      request.onerror =
        () =>
          reject(
            request.error ||
              new Error(
                "Kunne ikke åpne bildelagringen."
              )
          );
    }
  );
}

async function readStoredBackgroundImage() {
  const database =
    await openAppearanceAssetDatabase();

  try {
    return await new Promise<Blob | null>(
      (
        resolve,
        reject
      ) => {
        const transaction =
          database.transaction(
            APPEARANCE_ASSET_STORE_NAME,
            "readonly"
          );
        const request =
          transaction
            .objectStore(
              APPEARANCE_ASSET_STORE_NAME
            )
            .get(
              BACKGROUND_IMAGE_ASSET_KEY
            );

        request.onsuccess =
          () =>
            resolve(
              request.result instanceof
                Blob
                ? request.result
                : null
            );
        request.onerror =
          () =>
            reject(
              request.error
            );
      }
    );
  } finally {
    database.close();
  }
}

async function saveStoredBackgroundImage(
  blob: Blob
) {
  const database =
    await openAppearanceAssetDatabase();

  try {
    await new Promise<void>(
      (
        resolve,
        reject
      ) => {
        const transaction =
          database.transaction(
            APPEARANCE_ASSET_STORE_NAME,
            "readwrite"
          );

        transaction
          .objectStore(
            APPEARANCE_ASSET_STORE_NAME
          )
          .put(
            blob,
            BACKGROUND_IMAGE_ASSET_KEY
          );
        transaction.oncomplete =
          () =>
            resolve();
        transaction.onerror =
          () =>
            reject(
              transaction.error
            );
      }
    );
  } finally {
    database.close();
  }
}

async function deleteStoredBackgroundImage() {
  const database =
    await openAppearanceAssetDatabase();

  try {
    await new Promise<void>(
      (
        resolve,
        reject
      ) => {
        const transaction =
          database.transaction(
            APPEARANCE_ASSET_STORE_NAME,
            "readwrite"
          );

        transaction
          .objectStore(
            APPEARANCE_ASSET_STORE_NAME
          )
          .delete(
            BACKGROUND_IMAGE_ASSET_KEY
          );
        transaction.oncomplete =
          () =>
            resolve();
        transaction.onerror =
          () =>
            reject(
              transaction.error
            );
      }
    );
  } finally {
    database.close();
  }
}

