function bytesToBase64Url(
  bytes: Uint8Array
) {
  let binary =
    "";

  for (
    const byte
    of bytes
  ) {
    binary +=
      String.fromCharCode(
        byte
      );
  }

  return btoa(
    binary
  )
    .replace(
      /\+/g,
      "-"
    )
    .replace(
      /\//g,
      "_"
    )
    .replace(
      /=+$/g,
      ""
    );
}

function randomBase64Url(
  byteLength: number
) {
  const bytes =
    new Uint8Array(
      byteLength
    );

  crypto.getRandomValues(
    bytes
  );

  return bytesToBase64Url(
    bytes
  );
}

async function sha256Base64Url(
  value: string
) {
  const encoded =
    new TextEncoder()
      .encode(
        value
      );

  const digest =
    await crypto.subtle.digest(
      "SHA-256",
      encoded
    );

  return bytesToBase64Url(
    new Uint8Array(
      digest
    )
  );
}

