function isLightColor(
  hex: string
) {
  const match =
    /^#([0-9a-f]{6})$/i.exec(
      hex
    );

  if (
    !match
  ) {
    return false;
  }

  const value =
    match[1];

  const r =
    parseInt(
      value.slice(
        0,
        2
      ),
      16
    );

  const g =
    parseInt(
      value.slice(
        2,
        4
      ),
      16
    );

  const b =
    parseInt(
      value.slice(
        4,
        6
      ),
      16
    );

  return (
    r * 0.299 +
    g * 0.587 +
    b * 0.114
  ) > 186;
}

function clamp(
  value: number,
  min: number,
  max: number
) {
  return Math.min(
    max,
    Math.max(
      min,
      value
    )
  );
}

function hexToRgb(
  hex: string
) {
  const match =
    /^#([0-9a-f]{6})$/i.exec(
      hex
    );

  if (!match) {
    return {
      r: 16,
      g: 17,
      b: 21,
    };
  }

  const value =
    match[1];

  return {
    r: parseInt(
      value.slice(
        0,
        2
      ),
      16
    ),

    g: parseInt(
      value.slice(
        2,
        4
      ),
      16
    ),

    b: parseInt(
      value.slice(
        4,
        6
      ),
      16
    ),
  };
}

function componentToHex(
  value: number
) {
  return Math.round(
    clamp(
      value,
      0,
      255
    )
  )
    .toString(16)
    .padStart(
      2,
      "0"
    );
}

function rgbToHex(
  r: number,
  g: number,
  b: number
) {
  return (
    "#" +
    componentToHex(r) +
    componentToHex(g) +
    componentToHex(b)
  ).toUpperCase();
}

function rgbToHsv(
  r: number,
  g: number,
  b: number
) {
  const red = r / 255;
  const green = g / 255;
  const blue = b / 255;

  const max =
    Math.max(
      red,
      green,
      blue
    );

  const min =
    Math.min(
      red,
      green,
      blue
    );

  const delta =
    max - min;

  let hue = 0;

  if (delta !== 0) {
    if (max === red) {
      hue =
        60 *
        (((green - blue) / delta) % 6);
    } else if (max === green) {
      hue =
        60 *
        ((blue - red) / delta + 2);
    } else {
      hue =
        60 *
        ((red - green) / delta + 4);
    }
  }

  if (hue < 0) {
    hue += 360;
  }

  return {
    h: hue,
    s: max === 0
      ? 0
      : delta / max,
    v: max,
  };
}

function hsvToRgb(
  h: number,
  s: number,
  v: number
) {
  const hue =
    ((h % 360) + 360) % 360;

  const saturation =
    clamp(
      s,
      0,
      1
    );

  const value =
    clamp(
      v,
      0,
      1
    );

  const chroma =
    value * saturation;

  const x =
    chroma *
    (1 -
      Math.abs(
        ((hue / 60) % 2) - 1
      ));

  const m =
    value - chroma;

  let red = 0;
  let green = 0;
  let blue = 0;

  if (hue < 60) {
    red = chroma;
    green = x;
  } else if (hue < 120) {
    red = x;
    green = chroma;
  } else if (hue < 180) {
    green = chroma;
    blue = x;
  } else if (hue < 240) {
    green = x;
    blue = chroma;
  } else if (hue < 300) {
    red = x;
    blue = chroma;
  } else {
    red = chroma;
    blue = x;
  }

  return {
    r: (red + m) * 255,
    g: (green + m) * 255,
    b: (blue + m) * 255,
  };
}

function hsvToHex(
  h: number,
  s: number,
  v: number
) {
  const rgb =
    hsvToRgb(
      h,
      s,
      v
    );

  return rgbToHex(
    rgb.r,
    rgb.g,
    rgb.b
  );
}

function mixHexColors(
  first: string,
  second: string,
  amount: number
) {
  const a =
    hexToRgb(
      first
    );
  const b =
    hexToRgb(
      second
    );
  const weight =
    Math.max(
      0,
      Math.min(
        1,
        amount
      )
    );

  return rgbToHex(
    a.r +
      (b.r - a.r) *
        weight,
    a.g +
      (b.g - a.g) *
        weight,
    a.b +
      (b.b - a.b) *
        weight
  );
}

function hexColorWithAlpha(
  color: string,
  alpha: number
) {
  const rgb =
    hexToRgb(
      color
    );

  return `rgba(${Math.round(
    rgb.r
  )}, ${Math.round(
    rgb.g
  )}, ${Math.round(
    rgb.b
  )}, ${Math.max(
    0,
    Math.min(
      1,
      alpha
    )
  )})`;
}

function readableTextColor(
  background: string
) {
  return isLightColor(
    background
  )
    ? "#15171B"
    : "#F7F7F8";
}

function ColorPicker({
  color,
  onChange,
  borderColor,
  panelColor,
  textColor,
  mutedColor,
  helperText,
}: ColorPickerProps) {
  const saturationRef =
    useRef<HTMLDivElement | null>(
      null
    );

  const hueRef =
    useRef<HTMLDivElement | null>(
      null
    );

  const rgb =
    hexToRgb(
      color
    );

  const hsv =
    rgbToHsv(
      rgb.r,
      rgb.g,
      rgb.b
    );

  const [
    rememberedHue,
    setRememberedHue,
  ] = useState(
    hsv.h
  );

  const activeHue =
    hsv.s > 0.0001 &&
    hsv.v > 0.0001
      ? hsv.h
      : rememberedHue;

  useEffect(
    () => {
      if (
        hsv.s > 0.0001 &&
        hsv.v > 0.0001
      ) {
        setRememberedHue(
          hsv.h
        );
      }
    },
    [
      color,
    ]
  );

  const hueColor =
    hsvToHex(
      activeHue,
      1,
      1
    );

  function updateSaturation(
    clientX: number,
    clientY: number
  ) {
    const element =
      saturationRef.current;

    if (!element) {
      return;
    }

    const rect =
      element.getBoundingClientRect();

    const saturation =
      clamp(
        (clientX - rect.left) / rect.width,
        0,
        1
      );

    const value =
      clamp(
        1 -
          (clientY - rect.top) / rect.height,
        0,
        1
      );

    onChange(
      hsvToHex(
        activeHue,
        saturation,
        value
      )
    );
  }

  function updateHue(
    clientX: number
  ) {
    const element =
      hueRef.current;

    if (!element) {
      return;
    }

    const rect =
      element.getBoundingClientRect();

    const nextHue =
      clamp(
        (clientX - rect.left) / rect.width,
        0,
        0.999999
      ) * 360;

    setRememberedHue(
      nextHue
    );

    onChange(
      hsvToHex(
        nextHue,
        hsv.s,
        hsv.v
      )
    );
  }

  return (
    <div
      style={{
        padding: 10,
        background: panelColor,
        border: `1px solid ${borderColor}`,
        borderRadius: 8,
      }}
    >
      <div
        ref={
          saturationRef
        }
        onPointerDown={(
          event
        ) => {
          event.currentTarget.setPointerCapture(
            event.pointerId
          );

          updateSaturation(
            event.clientX,
            event.clientY
          );
        }}
        onPointerMove={(
          event
        ) => {
          if (
            event.currentTarget.hasPointerCapture(
              event.pointerId
            )
          ) {
            updateSaturation(
              event.clientX,
              event.clientY
            );
          }
        }}
        style={{
          position: "relative",
          height: 150,
          borderRadius: 7,
          overflow: "hidden",
          cursor: "crosshair",
          touchAction: "none",
          background:
            `linear-gradient(to top, #000 0%, transparent 100%), linear-gradient(to right, #fff 0%, ${hueColor} 100%)`,
          boxShadow:
            "inset 0 0 0 1px rgba(0,0,0,.24)",
        }}
      >
        <span
          style={{
            position: "absolute",
            left: `${hsv.s * 100}%`,
            top: `${(1 - hsv.v) * 100}%`,
            width: 13,
            height: 13,
            borderRadius: "50%",
            border: "2px solid white",
            boxShadow:
              "0 0 0 1px rgba(0,0,0,.7), 0 2px 7px rgba(0,0,0,.45)",
            transform:
              "translate(-50%, -50%)",
            pointerEvents:
              "none",
          }}
        />
      </div>

      <div
        ref={
          hueRef
        }
        onPointerDown={(
          event
        ) => {
          event.currentTarget.setPointerCapture(
            event.pointerId
          );

          updateHue(
            event.clientX
          );
        }}
        onPointerMove={(
          event
        ) => {
          if (
            event.currentTarget.hasPointerCapture(
              event.pointerId
            )
          ) {
            updateHue(
              event.clientX
            );
          }
        }}
        style={{
          position: "relative",
          height: 13,
          marginTop: 9,
          borderRadius: 999,
          cursor: "ew-resize",
          touchAction: "none",
          background:
            "linear-gradient(to right, #ff0000 0%, #ffff00 16.66%, #00ff00 33.33%, #00ffff 50%, #0000ff 66.66%, #ff00ff 83.33%, #ff0000 100%)",
          boxShadow:
            "inset 0 0 0 1px rgba(0,0,0,.22)",
        }}
      >
        <span
          style={{
            position: "absolute",
            left: `${(activeHue / 360) * 100}%`,
            top: "50%",
            width: 12,
            height: 12,
            borderRadius: "50%",
            border: "2px solid white",
            background: hueColor,
            boxShadow:
              "0 0 0 1px rgba(0,0,0,.55), 0 1px 5px rgba(0,0,0,.42)",
            transform:
              "translate(-50%, -50%)",
            pointerEvents:
              "none",
          }}
        />
      </div>

      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          marginTop: 10,
          color: mutedColor,
          fontSize: 11,
        }}
      >
        <span
          style={{
            width: 14,
            height: 14,
            borderRadius: "50%",
            background: color,
            border: `1px solid ${borderColor}`,
            flexShrink: 0,
          }}
        />

        <span>
          {helperText}
        </span>

        <strong
          style={{
            marginLeft: "auto",
            color: textColor,
            fontFamily: "monospace",
            fontSize: 11,
          }}
        >
          {color.toUpperCase()}
        </strong>
      </div>
    </div>
  );
}

