const KICK_SCREEN_BADGE_VIP =
  "data:image/png;base64,";

const KICK_SCREEN_BADGE_FOUNDER =
  "data:image/png;base64,";

const KICK_SCREEN_BADGE_OG =
  "data:image/png;base64,";

const KICK_SCREEN_BADGE_MODERATOR =
  "data:image/png;base64,";

function normalizedKickBadgeType(
  badge: ResolvedBadge
) {
  return (
    badge.setId ||
    badge.title ||
    ""
  )
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
}

function exactKickRoleBadgeImage(
  badge: ResolvedBadge
) {
  const rawType =
    normalizedKickBadgeType(
      badge
    );

  // Disse fire er matchet direkte mot KICK-badgene i referansebildet:
  // VIP = oransje krone, Founder = gul "1", OG = cyan OG, Moderator = cyan hammer.
  if (
    rawType === "vip" ||
    rawType.includes(
      "vip_badge"
    )
  ) {
    return KICK_SCREEN_BADGE_VIP;
  }

  if (
    rawType.includes(
      "founder"
    )
  ) {
    return KICK_SCREEN_BADGE_FOUNDER;
  }

  if (
    rawType === "og" ||
    rawType.includes(
      "original_gangster"
    )
  ) {
    return KICK_SCREEN_BADGE_OG;
  }

  if (
    rawType === "mod" ||
    rawType.includes(
      "moderator"
    )
  ) {
    return KICK_SCREEN_BADGE_MODERATOR;
  }

  return "";
}

function kickBadgeDisplayOrder(
  badge: ResolvedBadge
) {
  const rawType =
    normalizedKickBadgeType(
      badge
    );

  // Matcher rekkefølgen KICK viser i referansebildet:
  // VIP -> Founder -> Subscriber -> OG -> Moderator -> øvrige.
  if (
    rawType === "vip" ||
    rawType.includes(
      "vip_badge"
    )
  ) {
    return 10;
  }

  if (
    rawType.includes(
      "founder"
    )
  ) {
    return 20;
  }

  if (
    rawType.includes(
      "subscriber"
    )
  ) {
    return 25;
  }

  if (
    rawType === "og" ||
    rawType.includes(
      "original_gangster"
    )
  ) {
    return 30;
  }

  if (
    rawType === "mod" ||
    rawType.includes(
      "moderator"
    )
  ) {
    return 40;
  }

  if (
    rawType.includes(
      "verified"
    )
  ) {
    return 50;
  }

  if (
    rawType.includes(
      "staff"
    ) ||
    rawType.includes(
      "admin"
    )
  ) {
    return 60;
  }

  return 100;
}

function KickNativeBadgeIcon({
  badge,
  size = 17,
}: {
  badge: ResolvedBadge;
  size?: number;
}) {
  const exactImage =
    exactKickRoleBadgeImage(
      badge
    );

  if (exactImage) {
    return (
      <img
        src={exactImage}
        alt={
          badge.title ||
          badge.setId ||
          "KICK badge"
        }
        title={
          badge.title ||
          badge.setId ||
          "KICK badge"
        }
        draggable={false}
        style={{
          width:
            size,
          height:
            size,
          objectFit:
            "contain",
          display:
            "block",
          flexShrink:
            0,
        }}
      />
    );
  }

  // Kanalspesifikke badge-bilder (f.eks. subscriber) bruker badge.imageUrl
  // og blir rendret før denne funksjonen. Hvis KICK ikke gir oss et ekte
  // bilde for en annen badge-type, lager vi ikke lenger et falskt ikon.
  const fallback =
    (
      badge.info ||
      badge.title ||
      badge.setId ||
      ""
    ).trim();

  if (!fallback) {
    return null;
  }

  const compact =
    fallback
      .replace(
        /subscriber/gi,
        "SUB"
      )
      .replace(
        /verified/gi,
        "VER"
      )
      .replace(
        /global\s*/gi,
        ""
      )
      .trim();

  return (
    <span
      title={
        badge.title ||
        fallback
      }
      style={{
        minWidth:
          size,
        height:
          size,
        boxSizing:
          "border-box",
        padding:
          "0 3px",
        display:
          "inline-flex",
        alignItems:
          "center",
        justifyContent:
          "center",
        flexShrink:
          0,
        borderRadius:
          3,
        border:
          "1px solid rgba(255,255,255,.18)",
        background:
          "rgba(255,255,255,.06)",
        color:
          "#c8cbd0",
        fontSize:
          Math.max(
            7,
            Math.round(
              size * 0.43
            )
          ),
        fontWeight:
          850,
        lineHeight:
          1,
        whiteSpace:
          "nowrap",
      }}
    >
      {
        compact.length >
        5
          ? compact.slice(
              0,
              5
            )
          : compact
      }
    </span>
  );
}

function NativeBadgeFallback({
  badge,
  platform,
  size = 17,
}: {
  badge: ResolvedBadge;
  platform: ChatPlatform;
  size?: number;
}) {
  const type =
    (
      badge.setId ||
      badge.title ||
      "badge"
    )
      .toLowerCase()
      .replace(/[\s-]+/g, "_");
  const label =
    type.includes("broadcaster") ||
    type.includes("owner")
      ? platform === "youtube"
        ? "EIER"
        : "STR"
      : type.includes("moderator") ||
          type === "mod"
        ? "MOD"
        : type.includes("vip")
          ? "VIP"
          : type.includes("founder")
            ? "FND"
            : type.includes("subscriber") ||
                type.includes("sponsor") ||
                type.includes("member")
              ? platform === "youtube"
                ? "MED"
                : "SUB"
              : type.includes("staff") ||
                  type.includes("admin")
                ? "STAFF"
                : (
                    badge.info ||
                    badge.title ||
                    badge.setId ||
                    "BADGE"
                  )
                    .replace(/[^a-z0-9]/gi, "")
                    .slice(0, 5)
                    .toUpperCase();
  const background =
    type.includes("moderator") ||
    type === "mod"
      ? "#1f8f4e"
      : type.includes("vip")
        ? "#b33fb4"
        : type.includes("broadcaster") ||
            type.includes("owner")
          ? "#e43b44"
          : type.includes("founder")
            ? "#b88913"
            : platform === "youtube"
              ? "#b51f36"
              : "#6541a5";

  return (
    <span
      title={
        badge.title ||
        badge.setId
      }
      style={{
        minWidth: size,
        height: size,
        boxSizing: "border-box",
        padding: "0 3px",
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        borderRadius: 3,
        border: "1px solid rgba(255,255,255,.22)",
        background,
        color: "#fff",
        fontSize: Math.max(
          7,
          Math.round(size * 0.4)
        ),
        fontWeight: 900,
        lineHeight: 1,
        whiteSpace: "nowrap",
      }}
    >
      {label || "B"}
    </span>
  );
}


function clockTime(
  timestampMs =
    Date.now()
) {
  return new Date(
    timestampMs
  ).toLocaleTimeString(
    "nb-NO",
    {
      hour:
        "2-digit",

      minute:
        "2-digit",

      hour12:
        false,
    }
  );
}

function dateOnly(
  value: string,
  language: ResolvedAppLanguage
) {
  if (
    !value
  ) {
    return language === "no" ? "Ukjent" : "Unknown";
  }

  const date =
    new Date(
      value
    );

  if (
    Number.isNaN(
      date.getTime()
    )
  ) {
    return language === "no" ? "Ukjent" : "Unknown";
  }

  return date.toLocaleDateString(
    language === "no" ? "nb-NO" : "en-US",
    {
      year:
        "numeric",

      month:
        "2-digit",

      day:
        "2-digit",
    }
  );
}

function escapeRegExp(
  value: string
) {
  return value.replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}

function shortenText(
  value: string,
  maxLength = 90
) {
  const clean =
    value
      .replace(
        /\s+/g,
        " "
      )
      .trim();

  return clean.length <=
    maxLength
    ? clean
    : clean.slice(
        0,
        maxLength - 1
      ) + "…";
}

function timeoutLabel(
  seconds: number
) {
  if (
    seconds <
    60
  ) {
    return `${seconds}s`;
  }

  if (
    seconds <
    3600
  ) {
    return `${seconds / 60}m`;
  }

  if (
    seconds <
    86400
  ) {
    return `${seconds / 3600}h`;
  }

  return `${seconds / 86400}d`;
}

function rolesFromMessage(
  message:
    TwitchChatMessage,

  broadcasterId:
    string
):
  UserRoles {
  const sets =
    new Set(
      message.badges.map(
        (
          badge
        ) =>
          badge.setId
      )
    );

  return {
    broadcaster:
      message.userId ===
        broadcasterId ||
      sets.has(
        "broadcaster"
      ),

    moderator:
      sets.has(
        "moderator"
      ),

    vip:
      sets.has(
        "vip"
      ),

    subscriber:
      sets.has(
        "subscriber"
      ) ||
      sets.has(
        "founder"
      ),
  };
}

function findAuthoritativeMessageMatch(
  messages: TwitchChatMessage[],
  incoming: TwitchChatMessage
) {
  const exactIndex =
    messages.findIndex(
      (message) =>
        message.id === incoming.id
    );

  if (exactIndex >= 0) {
    return exactIndex;
  }

  const incomingPlatform =
    incoming.platform || "twitch";
  const incomingLogin =
    incoming.userLogin.toLowerCase();
  const incomingName =
    incoming.username.toLowerCase();

  return messages.findIndex(
    (message) => {
      if (!message.optimistic) {
        return false;
      }

      const samePlatform =
        (message.platform || "twitch") ===
        incomingPlatform;
      const sameUser =
        Boolean(
          message.userId &&
          incoming.userId &&
          message.userId === incoming.userId
        ) ||
        Boolean(
          message.userLogin &&
          incomingLogin &&
          message.userLogin.toLowerCase() ===
            incomingLogin
        ) ||
        Boolean(
          message.username &&
          incomingName &&
          message.username.toLowerCase() ===
            incomingName
        );

      return (
        samePlatform &&
        sameUser &&
        message.text === incoming.text &&
        Math.abs(
          message.timestampMs -
          incoming.timestampMs
        ) <= 30_000
      );
    }
  );
}

function mergeAuthoritativeMessage(
  existing: TwitchChatMessage,
  incoming: TwitchChatMessage
): TwitchChatMessage {
  if (existing.optimistic) {
    return incoming;
  }

  // Kick chat can arrive through the realtime viewer connection before the
  // official webhook. The realtime payload is fast, but it may omit identity
  // badges. Keep the single existing message and enrich it when the webhook
  // delivers the complete sender identity a moment later.
  const badges =
    incoming.badges.length > existing.badges.length
      ? incoming.badges
      : existing.badges;
  const avatarUrl =
    incoming.avatarUrl || existing.avatarUrl;
  const color =
    incoming.color &&
    (existing.color === "#53fc18" || !existing.color)
      ? incoming.color
      : existing.color;
  const reply =
    incoming.reply || existing.reply;

  if (
    badges === existing.badges &&
    avatarUrl === existing.avatarUrl &&
    color === existing.color &&
    reply === existing.reply
  ) {
    return existing;
  }

  return {
    ...existing,
    badges,
    avatarUrl,
    color,
    reply,
  };
}

async function friendlyTwitchError(
  response:
    Response,

  action: string,
  language: ResolvedAppLanguage
) {
  const tr = (norwegian: string, english: string) =>
    language === "no" ? norwegian : english;
  const raw =
    await response.text();

  let message =
    raw;

  try {
    const parsed =
      JSON.parse(
        raw
      ) as {
        message?: string;
        error?: string;
      };

    message =
      parsed.message ||
      parsed.error ||
      raw;
  } catch {
    // vanlig tekst
  }

  const lower =
    message.toLowerCase();

  if (
    response.status ===
      400 &&
    (
      lower.includes(
        "may not be banned"
      ) ||
      lower.includes(
        "may not be put in a timeout"
      )
    )
  ) {
    return tr(
      "Twitch tillater ikke denne handlingen på brukeren. Brukeren kan være strømmer, moderator eller på annen måte beskyttet.",
      "Twitch does not allow this action on the user. The user may be the broadcaster, a moderator or otherwise protected."
    );
  }

  if (
    response.status ===
    401
  ) {
    return tr("Twitch-tilgangen mangler en nødvendig rettighet, eller innloggingen må fornyes.", "Twitch access is missing a required permission, or the sign-in must be renewed.");
  }

  if (
    response.status ===
    403
  ) {
    return tr("Twitch sier at du ikke har moderatorrettighet til denne handlingen.", "Twitch says you do not have moderator permission for this action.");
  }

  if (
    response.status ===
    409
  ) {
    return tr("En annen modereringshandling pågår. Prøv igjen om et øyeblikk.", "Another moderation action is in progress. Try again in a moment.");
  }

  if (
    response.status ===
    429
  ) {
    return tr("For mange handlinger akkurat nå. Vent litt og prøv igjen.", "Too many actions right now. Wait a moment and try again.");
  }

  return tr(`Handlingen mislyktes (HTTP ${response.status}).`, `${action} failed (HTTP ${response.status}).`);
}

async function friendlyYouTubeModerationError(
  response: Response,
  action: string,
  language: ResolvedAppLanguage
) {
  const tr = (norwegian: string, english: string) =>
    language === "no" ? norwegian : english;
  const raw =
    await response.text();

  let message =
    raw;

  try {
    const parsed =
      JSON.parse(
        raw
      ) as {
        error?: {
          message?: string;
          errors?: Array<{
            reason?: string;
            message?: string;
          }>;
        };
      };

    message =
      parsed.error
        ?.errors?.[0]
        ?.message ||
      parsed.error
        ?.message ||
      raw;
  } catch {
    // vanlig tekst
  }

  if (
    response.status ===
    401
  ) {
    return tr("YouTube-innloggingen må fornyes. Logg ut og inn på YouTube igjen fra Kontoer.", "YouTube sign-in must be renewed. Sign out and back in to YouTube from Accounts.");
  }

  if (
    response.status ===
    403
  ) {
    return tr("YouTube avviste modereringshandlingen. Du må være moderator eller eier i denne livechatten.", "YouTube rejected the moderation action. You must be a moderator or owner in this live chat.");
  }

  if (
    response.status ===
    404
  ) {
    return tr("YouTube fant ikke livechatten, brukeren eller meldingen lenger.", "YouTube could no longer find the live chat, user or message.");
  }

  return tr(`Handlingen mislyktes på YouTube (HTTP ${response.status}).`, `${action} failed on YouTube (HTTP ${response.status}).`);
}

async function friendlyKickModerationError(
  response: Response,
  action: string,
  language: ResolvedAppLanguage
) {
  const tr = (norwegian: string, english: string) =>
    language === "no" ? norwegian : english;
  const raw =
    await response.text();

  let message =
    raw;

  try {
    const parsed =
      JSON.parse(
        raw
      ) as {
        message?: string;
        error?: string;
      };

    message =
      parsed.message ||
      parsed.error ||
      raw;
  } catch {
    // vanlig tekst
  }

  if (
    response.status ===
    401
  ) {
    return tr(
      "Kick-innloggingen må fornyes, eller tokenet mangler modereringstilgang. Logg ut og inn på Kick igjen fra Kontoer.",
      "Kick sign-in must be renewed, or the token is missing the moderation scope. Sign out and back in to Kick from Accounts."
    );
  }

  if (
    response.status ===
    403
  ) {
    return tr(
      "Kick avviste modereringshandlingen. Du må være moderator eller eier i kanalen, og FyFlade må være godkjent med moderation:ban. Hvis du nettopp slo på tilgangen, logger du ut og inn på Kick igjen.",
      "Kick rejected the moderation action. You must be a moderator or owner in the channel, and FyFlade must be authorized with moderation:ban. If you just enabled the scope, sign out and back in to Kick."
    );
  }

  if (
    response.status ===
    429
  ) {
    return tr("For mange Kick-handlinger akkurat nå. Vent litt og prøv igjen.", "Too many Kick actions right now. Wait a moment and try again.");
  }

  return tr(`Handlingen mislyktes på Kick (HTTP ${response.status}).`, `${action} failed on Kick (HTTP ${response.status}).`);
}

