  function chatPlatformFromShortcut(
    value: string
  ): ChatPlatform | null {
    const shortcut =
      value.trim().toLowerCase();

    if (shortcut === "/k") {
      return "kick";
    }
    if (shortcut === "/t") {
      return "twitch";
    }
    if (shortcut === "/y") {
      return "youtube";
    }
    return null;
  }

