  useEffect(
    () => {
      const next =
        localIgnoresRef.current.filter(
          (entry) => {
            if (!entry.untilStreamEnds) {
              return true;
            }

            const channel = channelTabs.find(
              (tab) =>
                tab.broadcasterId ===
                entry.channelId
            );

            if (!channel) {
              return true;
            }

            if (channel.status === "joining") {
              return true;
            }

            return Boolean(
              channel.isLive ||
              channel.kickIsLive ||
              channel.youtubeIsLive
            );
          }
        );

      if (
        next.length !==
        localIgnoresRef.current.length
      ) {
        saveLocalIgnores(next);
      }
    },
    [channelTabs]
  );

