  useEffect(
    () => {
      if (
        FYFLATE_WINDOW_MODE ||
        !networkOnline
      ) {
        return;
      }

      const retryTwitch =
        hasSavedTwitchSession &&
        !twitchConnected &&
        !connectingTwitch &&
        !connectionErrorNeedsSignIn(
          twitchError
        );
      const retryKick =
        hasSavedKickSession &&
        !kickConnected &&
        !connectingKick &&
        !connectionErrorNeedsSignIn(
          kickLoginError
        );
      const retryYouTube =
        hasSavedYouTubeSession &&
        !youtubeConnected &&
        !connectingYoutube &&
        !connectionErrorNeedsSignIn(
          youtubeLoginError
        );

      if (
        !retryTwitch &&
        !retryKick &&
        !retryYouTube
      ) {
        if (
          (
            twitchConnected ||
            !hasSavedTwitchSession
          ) &&
          (
            kickConnected ||
            !hasSavedKickSession
          ) &&
          (
            youtubeConnected ||
            !hasSavedYouTubeSession
          )
        ) {
          accountRecoveryAttemptRef.current =
            0;
        }
        return;
      }

      const delay = Math.min(
        30_000,
        2_000 *
          2 **
            Math.min(
              accountRecoveryAttemptRef.current,
              4
            )
      );

      const timer = window.setTimeout(
        () => {
          if (
            reliabilityRecoveryInProgressRef.current
          ) {
            return;
          }

          accountRecoveryAttemptRef.current +=
            1;
          reliabilityRecoveryInProgressRef.current =
            true;

          const recoveries: Promise<unknown>[] =
            [];

          if (retryTwitch) {
            recoveries.push(
              restoreTwitchLogin()
            );
          }
          if (retryKick) {
            recoveries.push(
              restoreKickLogin()
            );
          }
          if (retryYouTube) {
            recoveries.push(
              restoreYouTubeLogin()
            );
          }

          void Promise.allSettled(
            recoveries
          ).finally(() => {
            reliabilityRecoveryInProgressRef.current =
              false;
          });
        },
        delay
      );

      return () =>
        window.clearTimeout(
          timer
        );
    },
    [
      networkOnline,
      hasSavedTwitchSession,
      twitchConnected,
      connectingTwitch,
      twitchError,
      hasSavedKickSession,
      kickConnected,
      connectingKick,
      kickLoginError,
      hasSavedYouTubeSession,
      youtubeConnected,
      connectingYoutube,
      youtubeLoginError,
    ]
  );

