  useEffect(
    () => {
      let disposed =
        false;

      let unlistenMessages:
        | (() => void)
        | null =
        null;

      let unlistenErrors:
        | (() => void)
        | null =
        null;

      let unlistenYouTubeStatus: (() => void) | null = null;

      let unlistenQuota:
        | (() => void)
        | null =
        null;

      let unlistenKickViewer:
        | (() => void)
        | null =
        null;

      void listen<
        string[]
      >(
        "youtube-livechat-stream",
        (
          event
        ) => {
          void processYouTubeStreamPayload(
            event.payload
          );
        }
      ).then(
        (
          unlisten
        ) => {
          if (
            disposed
          ) {
            unlisten();
          } else {
            unlistenMessages =
              unlisten;
          }
        }
      );

      void listen<
        string[]
      >(
        "kick-viewer-frame",
        (
          event
        ) => {
          const [
            slug = "",
            rawFrame = "",
          ] = event.payload || [];

          void processKickViewerFrame(
            slug,
            rawFrame
          );
        }
      ).then(
        (
          unlisten
        ) => {
          if (
            disposed
          ) {
            unlisten();
          } else {
            unlistenKickViewer =
              unlisten;
          }
        }
      );

      void listen<
        string[]
      >(
        "youtube-livechat-stream-error",
        (
          event
        ) => {
          void processYouTubeStreamError(
            event.payload
          );
        }
      ).then(
        (
          unlisten
        ) => {
          if (
            disposed
          ) {
            unlisten();
          } else {
            unlistenErrors =
              unlisten;
          }
        }
      );

      void listen<
        string[]
      >(
        "youtube-quota-consumed",
        (
          event
        ) => {
          const units =
            Number(
              event.payload?.[0] ||
              "1"
            );

          const action =
            event.payload?.[1] ||
            "YouTube streamList";

          recordYouTubeQuotaUnits(
            Number.isFinite(
              units
            )
              ? units
              : 1,
            action
          );
        }
      ).then(
        (
          unlisten
        ) => {
          if (
            disposed
          ) {
            unlisten();
          } else {
            unlistenQuota =
              unlisten;
          }
        }
      );

      void listen<string[]>(
        "youtube-livechat-stream-status",
        (event) => {
          if (disposed) return;
          const [tabId = "", generationRaw = "", state = ""] = event.payload || [];
          const generation = Number(generationRaw);
          if (
            !tabId ||
            !Number.isFinite(generation) ||
            (state !== "connecting" && state !== "connected" && state !== "reconnecting")
          ) {
            return;
          }
          updateYouTubeStreamHealth(
            tabId,
            generation,
            state === "connected" ? null : state
          );
        }
      ).then((unlisten) => {
        if (disposed) unlisten();
        else unlistenYouTubeStatus = unlisten;
      });

      return () => {
        disposed =
          true;

        unlistenMessages?.();
        unlistenErrors?.();
        unlistenYouTubeStatus?.();
        unlistenQuota?.();
        unlistenKickViewer?.();
      };
    },
    []
  );

