  useEffect(
    () => {
      let disposed =
        false;
      let socket:
        WebSocket | null =
        null;
      let reconnectTimer:
        number | null =
        null;
      let reconnectAttempt =
        0;

      if (!networkOnline) {
        setKickDirectChatStatus(
          "error"
        );
        setKickDirectChatError(
          ui(
            "Venter på internett før Kick-chatten kobles til igjen.",
            "Waiting for internet before reconnecting Kick chat."
          )
        );
        return;
      }

      const slugs =
        Array.from(
          new Set(
            channelTabs
              .map(
                (tab) =>
                  (
                    tab.kickChannelSlug ||
                    (tab.platform === "kick"
                      ? tab.login
                      : "")
                  )
                    .toLowerCase()
                    .trim()
              )
              .filter(Boolean)
          )
        );

      // Make sure the retired hidden viewer window is not left running.
      void invoke<number>(
        "sync_kick_viewer_channels",
        { channels: [] }
      ).catch(
        () => undefined
      );

      if (
        slugs.length === 0
      ) {
        setKickDirectChatStatus(
          "idle"
        );
        setKickDirectChatError(
          ""
        );
        return;
      }

      const scheduleReconnect =
        () => {
          if (disposed) {
            return;
          }

          setKickDirectChatStatus(
            "error"
          );

          reconnectAttempt +=
            1;

          const delay =
            Math.min(
              30_000,
              1_000 *
                2 **
                  Math.min(
                    reconnectAttempt -
                      1,
                    5
                  )
            );

          if (
            reconnectTimer !==
            null
          ) {
            window.clearTimeout(
              reconnectTimer
            );
          }

          reconnectTimer =
            window.setTimeout(
              () => {
                reconnectTimer =
                  null;
                void connect();
              },
              delay
            );
        };

      const loadChannel =
        async (
          slug: string
        ) => {
          try {
            const response =
              await fetch(
                `https://kick.com/api/v2/channels/${encodeURIComponent(
                  slug
                )}`,
                {
                  headers: {
                    Accept:
                      "application/json",
                  },
                }
              );

            if (!response.ok) {
              return null;
            }

            const data =
              (await response.json()) as KickWebsiteChannelResponse;
            const channelId =
              String(
                data.id ||
                  ""
              );
            const chatroomId =
              String(
                data.chatroom
                  ?.id ||
                  ""
              );

            if (
              !channelId ||
              !chatroomId
            ) {
              return null;
            }

            return {
              slug,
              channelId,
              pusherChannel:
                `chatrooms.${chatroomId}.v2`,
            };
          } catch (
            error
          ) {
            console.warn(
              `Kick channel ${slug}:`,
              error
            );
            return null;
          }
        };

      const loadPusherConnection =
        async (
          channelId: string
        ) => {
          try {
            const clientId =
              typeof crypto.randomUUID ===
              "function"
                ? crypto.randomUUID()
                : `${Date.now()}-${Math.random()}`;
            const response =
              await fetch(
                `https://web.kick.com/api/v1/realtime/channels/${encodeURIComponent(
                  channelId
                )}/chat/connection`,
                {
                  method:
                    "POST",
                  headers: {
                    Accept:
                      "application/json",
                    "Content-Type":
                      "application/json",
                    "x-app-platform":
                      "web",
                    Origin:
                      "https://kick.com",
                    Referer:
                      "https://kick.com/",
                  },
                  body:
                    JSON.stringify({
                      client: {
                        id:
                          clientId,
                        type:
                          "web",
                      },
                      capabilities: {
                        accepted_providers: [
                          {
                            provider:
                              "pusher",
                          },
                        ],
                      },
                    }),
                }
              );

            if (!response.ok) {
              throw new Error(
                `HTTP ${response.status}`
              );
            }

            const data =
              (await response.json()) as KickRealtimeDescriptorResponse;
            const pusher =
              data.data?.connections?.find(
                (connection) =>
                  connection.provider ===
                  "pusher"
              );
            const appKey =
              pusher?.credentials
                ?.app_key ||
              "";
            const cluster =
              pusher?.credentials
                ?.cluster ||
              "";

            if (
              !appKey ||
              !cluster
            ) {
              throw new Error(
                "Kick returned no realtime connection"
              );
            }

            return {
              appKey,
              cluster,
            };
          } catch (
            error
          ) {
            console.warn(
              "Kick realtime descriptor:",
              error
            );

            return {
              appKey:
                KICK_PUSHER_FALLBACK_APP_KEY,
              cluster:
                KICK_PUSHER_FALLBACK_CLUSTER,
            };
          }
        };

      const connect =
        async () => {
          if (disposed) {
            return;
          }

          setKickDirectChatStatus(
            "connecting"
          );
          setKickDirectChatError(
            ""
          );

          const channels =
            (
              await Promise.all(
                slugs.map(
                  loadChannel
                )
              )
            ).filter(
              (
                channel
              ): channel is NonNullable<
                typeof channel
              > =>
                Boolean(
                  channel
                )
            );

          if (disposed) {
            return;
          }

          if (
            channels.length === 0
          ) {
            setKickDirectChatError(
              ui(
                "Fant ingen Kick-chatrom for kanalene.",
                "No Kick chat rooms were found for the channels."
              )
            );
            scheduleReconnect();
            return;
          }

          const connection =
            await loadPusherConnection(
              channels[0]
                .channelId
            );

          if (disposed) {
            return;
          }

          const slugByChannel =
            new Map(
              channels.map(
                (channel) => [
                  channel.pusherChannel,
                  channel.slug,
                ]
              )
            );
          const nextSocket =
            new WebSocket(
              `wss://ws-${connection.cluster}.pusher.com/app/${encodeURIComponent(
                connection.appKey
              )}?protocol=7&client=js&version=8.5.0&flash=false`
            );

          socket =
            nextSocket;

          const subscribe =
            () => {
              for (
                const pusherChannel of slugByChannel.keys()
              ) {
                nextSocket.send(
                  JSON.stringify({
                    event:
                      "pusher:subscribe",
                    data: {
                      auth:
                        "",
                      channel:
                        pusherChannel,
                    },
                  })
                );
              }
            };

          nextSocket.onopen =
            () => {
              if (disposed) {
                nextSocket.close();
              }
            };

          nextSocket.onmessage =
            (event) => {
              try {
                const rawFrame =
                  String(
                    event.data ||
                      ""
                  );
                const frame =
                  JSON.parse(
                    rawFrame
                  ) as KickViewerSocketFrame;

                if (
                  frame.event ===
                  "pusher:ping"
                ) {
                  nextSocket.send(
                    JSON.stringify({
                      event:
                        "pusher:pong",
                      data: {},
                    })
                  );
                  return;
                }

                if (
                  frame.event ===
                  "pusher:connection_established"
                ) {
                  reconnectAttempt =
                    0;
                  subscribe();
                  setKickDirectChatStatus(
                    "ready"
                  );
                  return;
                }

                const slug =
                  slugByChannel.get(
                    frame.channel ||
                      ""
                  );

                if (
                  slug &&
                  /ChatMessageEvent|chat\.message\.sent/i.test(
                    frame.event ||
                      ""
                  )
                ) {
                  void processKickViewerFrame(
                    slug,
                    rawFrame
                  );
                }
              } catch (
                error
              ) {
                console.warn(
                  "Kick direct chat frame:",
                  error
                );
              }
            };

          nextSocket.onerror =
            () => {
              if (!disposed) {
                setKickDirectChatError(
                  ui(
                    "Sanntidsforbindelsen til Kick feilet. Prøver igjen automatisk.",
                    "The realtime Kick connection failed. Retrying automatically."
                  )
                );
              }
            };

          nextSocket.onclose =
            () => {
              if (
                socket ===
                nextSocket
              ) {
                socket =
                  null;
              }

              scheduleReconnect();
            };
        };

      void connect().catch(
        (error) => {
          console.error(
            "Kick direct chat:",
            error
          );
          setKickDirectChatError(
            readableErrorMessage(
              error,
              ui(
                "Kunne ikke koble til Kick-chatten.",
                "Could not connect to Kick chat."
              )
            )
          );
          scheduleReconnect();
        }
      );

      return () => {
        disposed =
          true;

        if (
          reconnectTimer !==
          null
        ) {
          window.clearTimeout(
            reconnectTimer
          );
        }

        socket?.close();
      };
    },
    [
      kickViewerChannelSignature,
      networkOnline,
    ]
  );

