  useEffect(
    () =>
      () => {
        stopAllYouTubeChatPolls();
      },
    []
  );

  useEffect(
    () => {
      if (
        FYFLATE_WINDOW_MODE
      ) {
        return;
      }

      const offline =
        () => {
          setNetworkOnline(
            false
          );

          if (
            shouldReconnect.current &&
            hasTrackedTwitchTabs()
          ) {
            beginConnectionLoss();
          }
        };

      const online =
        () => {
          setNetworkOnline(
            true
          );

          if (
            reliabilityRecoveryInProgressRef.current
          ) {
            return;
          }

          reliabilityRecoveryInProgressRef.current =
            true;

          void (async () => {
            const recoveries: Promise<unknown>[] =
              [];

            if (
              !twitchAccessTokenRef.current
            ) {
              recoveries.push(
                restoreTwitchLogin()
              );
            } else if (
              shouldReconnect.current &&
              hasTrackedTwitchTabs()
            ) {
              clearReconnectTimer();
              recoveries.push(
                reconnectAllChannels()
              );
            }

            if (
              !kickAccessTokenRef.current
            ) {
              recoveries.push(
                restoreKickLogin()
              );
            } else if (
              kickRelaySocketRef.current
                ?.readyState !==
              WebSocket.OPEN
            ) {
              recoveries.push(
                connectKickRelay(
                  kickAccessTokenRef.current
                )
              );
            }

            if (
              !youtubeAccessTokenRef.current
            ) {
              recoveries.push(
                restoreYouTubeLogin()
              );
            } else {
              recoveries.push(
                refreshSavedYouTubeLiveStatuses()
              );
            }

            await Promise.allSettled(
              recoveries
            );
          })().finally(() => {
            reliabilityRecoveryInProgressRef.current =
              false;
          });
        };

      window.addEventListener(
        "offline",
        offline
      );

      window.addEventListener(
        "online",
        online
      );

      return () => {
        window.removeEventListener(
          "offline",
          offline
        );

        window.removeEventListener(
          "online",
          online
        );
      };
    },
    []
  );

  useEffect(
    () => {
      return () => {
        shouldReconnect.current =
          false;

        clearKeepaliveTimer();

        clearReconnectTimer();

        twitchSocket.current
          ?.close();

        stopSevenTvLiveSync();

        if (
          mentionAudioContextRef.current
        ) {
          void mentionAudioContextRef.current
            .close();
        }
      };
    },
    []
  );

  function updateTabs(
    updater:
      (
        tabs:
          ChannelTab[]
      ) =>
        ChannelTab[]
  ) {
    const next =
      updater(
        channelTabsRef.current
      );

    channelTabsRef.current =
      next;

    setChannelTabs(
      next
    );

    window.setTimeout(
      syncKickRelaySubscriptions,
      0
    );
  }

  function replaceTabs(
    tabs:
      ChannelTab[]
  ) {
    channelTabsRef.current =
      tabs;

    setChannelTabs(
      tabs
    );

    window.setTimeout(
      syncKickRelaySubscriptions,
      0
    );
  }

  function sanitizeChannelName(
    input: string
  ) {
    let value =
      input
        .trim()
        .replace(
          /^https?:\/\/(www\.)?twitch\.tv\//i,
          ""
        );

    value =
      value
        .split(
          "/"
        )[0]
        .split(
          "?"
        )[0]
        .replace(
          /^[@#]/,
          ""
        );

    return value
      .toLowerCase()
      .trim();
  }

  function saveChannelCache(
    channels:
      CachedChannel[]
  ) {
    const deduped =
      Array.from(
        new Map(
          channels.map(
            (
              channel
            ) => [
              channel.login.toLowerCase(),

              {
                ...channel,

                login:
                  channel.login.toLowerCase(),
              },
            ]
          )
        ).values()
      );

    const bounded = deduped.slice(-250);

    channelCacheRef.current = bounded;

    localStorage.setItem(
      CHANNEL_CACHE_KEY,
      JSON.stringify(
        bounded
      )
    );
  }

  function cacheChannel(
    user: TwitchUser
  ) {
    saveChannelCache([
      ...channelCacheRef.current.filter(
        (
          channel
        ) =>
          channel.login !==
          user.login.toLowerCase()
      ),

      {
        login:
          user.login.toLowerCase(),

        displayName:
          user.display_name,

        profileImageUrl:
          user.profile_image_url,
      },
    ]);
  }

  function preloadSavedChannelTabs() {
    const savedLogins =
      savedChannelLoginsRef.current;

    const savedYouTubeChannels =
      savedYouTubeChannelsRef.current;

    const linkedYouTubeChannels =
      linkedYouTubeChannelsRef.current;

    const savedKickChannels =
      savedKickChannelsRef.current;

    const linkedKickChannels =
      linkedKickChannelsRef.current;

    if (
      savedLogins.length === 0 &&
      savedYouTubeChannels.length === 0 &&
      savedKickChannels.length === 0
    ) {
      return;
    }

    const cachedByLogin =
      new Map<
        string,
        CachedChannel
      >(
        channelCacheRef.current.map(
          (channel) => [
            channel.login,
            channel,
          ]
        )
      );

    const linkedKickFor = (
      hostPlatform:
        "twitch" | "youtube",
      hostKey: string
    ) =>
      linkedKickChannels.find(
        (item) =>
          item.hostPlatform ===
            hostPlatform &&
          item.hostKey ===
            hostKey.toLowerCase()
      );

    const twitchTabs:
      ChannelTab[] =
      savedLogins.map(
        (login) => {
          const cached =
            cachedByLogin.get(
              login
            );

          const linkedYouTube =
            linkedYouTubeChannels.find(
              (item) =>
                item.twitchLogin ===
                login
            );

          const linkedKick =
            linkedKickFor(
              "twitch",
              login
            );

          return {
            broadcasterId:
              `cached:${login}`,
            login,
            displayName:
              cached?.displayName ||
              login,
            profileImageUrl:
              cached?.profileImageUrl ||
              "",
            isLive:
              false,
            canModerate:
              false,
            status:
              "disconnected",
            error:
              "",
            messages:
              [],
            hasMention:
              false,
            platform:
              "twitch",
            youtubeChannelId:
              linkedYouTube?.channelId,
            youtubeUploadsPlaylistId:
              linkedYouTube?.uploadsPlaylistId,
            youtubeIsLive:
              false,
            kickBroadcasterUserId:
              linkedKick?.broadcasterUserId,
            kickChannelSlug:
              linkedKick?.slug,
            kickIsLive:
              false,
          };
        }
      );

    const youtubeTabs:
      ChannelTab[] =
      savedYouTubeChannels
        .filter(
          (channel) =>
            !linkedYouTubeChannels.some(
              (linked) =>
                linked.channelId ===
                channel.channelId
            )
        )
        .map(
          (channel) => {
            const linkedKick =
              linkedKickFor(
                "youtube",
                channel.channelId
              );

            return {
              broadcasterId:
                `youtube-channel:${channel.channelId}`,
              login:
                channel.channelId,
              displayName:
                channel.name,
              profileImageUrl:
                channel.avatarUrl,
              isLive:
                false,
              canModerate:
                false,
              status:
                "disconnected",
              error:
                "",
              messages:
                [],
              hasMention:
                false,
              platform:
                "youtube",
              youtubeChannelId:
                channel.channelId,
              youtubeUploadsPlaylistId:
                channel.uploadsPlaylistId,
              youtubeIsLive:
                false,
              kickBroadcasterUserId:
                linkedKick?.broadcasterUserId,
              kickChannelSlug:
                linkedKick?.slug,
              kickIsLive:
                false,
            };
          }
        );

    const linkedKickIds =
      new Set(
        linkedKickChannels.map(
          (item) =>
            item.broadcasterUserId
        )
      );

    const kickTabs:
      ChannelTab[] =
      savedKickChannels
        .filter(
          (channel) =>
            !linkedKickIds.has(
              channel.broadcasterUserId
            )
        )
        .map(
          (channel) => ({
            broadcasterId:
              `kick:${channel.broadcasterUserId}`,
            login:
              channel.slug,
            displayName:
              channel.name,
            profileImageUrl:
              channel.avatarUrl,
            isLive:
              false,
            canModerate:
              false,
            status:
              "disconnected",
            error:
              "",
            messages:
              [],
            hasMention:
              false,
            platform:
              "kick",
            kickBroadcasterUserId:
              channel.broadcasterUserId,
            kickChannelSlug:
              channel.slug,
            kickIsLive:
              false,
          })
        );

    const cachedTabs = [
      ...twitchTabs,
      ...youtubeTabs,
      ...kickTabs,
    ];

    replaceTabs(
      cachedTabs
    );

    const preferred =
      localStorage.getItem(
        ACTIVE_CHANNEL_KEY
      );

    const active =
      cachedTabs.find(
        (tab) =>
          tab.login ===
          preferred
      ) ||
      cachedTabs[0];

    if (active) {
      activeChannelIdRef.current =
        active.broadcasterId;

      setActiveChannelId(
        active.broadcasterId
      );
    }

    for (const tab of cachedTabs) {
      const historyReads:
        Promise<TwitchChatMessage[]>[] =
        [];

      if (
        tab.platform ===
        "youtube"
      ) {
        historyReads.push(
          loadStoredChannelHistory(
            tab.youtubeChannelId ||
              tab.login,
            "youtube"
          )
        );
      } else if (
        tab.platform ===
        "kick"
      ) {
        historyReads.push(
          loadStoredChannelHistory(
            tab.kickBroadcasterUserId ||
              tab.login,
            "kick"
          )
        );
      } else {
        historyReads.push(
          loadStoredChannelHistory(
            tab.login,
            "twitch"
          )
        );

        if (
          tab.youtubeChannelId
        ) {
          historyReads.push(
            loadStoredChannelHistory(
              tab.youtubeChannelId,
              "youtube"
            )
          );
        }
      }

      if (
        tab.kickBroadcasterUserId &&
        tab.platform !==
          "kick"
      ) {
        historyReads.push(
          loadStoredChannelHistory(
            tab.kickBroadcasterUserId,
            "kick"
          )
        );
      }

      void Promise.all(
        historyReads
      ).then(
        (messageGroups) => {
          const messages =
            messageGroups
              .flat()
              .filter(
                (
                  message,
                  index,
                  all
                ) =>
                  all.findIndex(
                    (candidate) =>
                      candidate.id ===
                      message.id
                  ) === index
              )
              .sort(
                (a, b) =>
                  a.timestampMs -
                  b.timestampMs
              );

          updateTabs(
            (tabs) =>
              tabs.map(
                (item) =>
                  item.broadcasterId ===
                  tab.broadcasterId
                    ? {
                        ...item,
                        messages:
                          [
                            ...messages,
                            ...item.messages.filter(
                              (current) =>
                                !messages.some(
                                  (stored) =>
                                    stored.id ===
                                    current.id
                                )
                            ),
                          ].sort(
                            (a, b) =>
                              a.timestampMs -
                              b.timestampMs
                          ),
                      }
                    : item
              )
          );
        }
      );
    }
  }

