  async function checkForFyFladeUpdate(
    manual: boolean
  ) {
    if (distributionMode === "portable") {
      setUpdateError(
        ui(
          "Portable-utgaven oppdateres ved å laste ned og pakke ut en ny portable-versjon.",
          "Update the portable edition by downloading and extracting a new portable version."
        )
      );
      setAppUpdateStatus("error");
      return;
    }
    if (
      updateOperationRef.current
    ) {
      return;
    }

    updateOperationRef.current =
      true;
    setAppUpdateStatus(
      "checking"
    );
    setUpdateError("");

    try {
      const update =
        await check({
          timeout: 30000,
        });

      if (!update) {
        if (
          availableUpdateRef.current
        ) {
          await availableUpdateRef.current
            .close()
            .catch(
              () => undefined
            );
        }

        availableUpdateRef.current =
          null;
        setAvailableUpdateVersion(
          ""
        );
        setAvailableUpdateNotes(
          ""
        );
        setAppUpdateStatus(
          "current"
        );
        return;
      }

      if (
        availableUpdateRef.current &&
        availableUpdateRef.current !==
          update
      ) {
        await availableUpdateRef.current
          .close()
          .catch(
            () => undefined
          );
      }

      availableUpdateRef.current =
        update;
      setAvailableUpdateVersion(
        update.version
      );
      setAvailableUpdateNotes(
        update.body || ""
      );
      setUpdateProgress(0);
      setAppUpdateStatus(
        "available"
      );
    } catch (error) {
      const message =
        readableErrorMessage(
          error,
          ui(
            "Kunne ikke se etter oppdateringer.",
            "Could not check for updates."
          )
        );

      console.error(
        "FyFlade update check failed",
        error
      );
      setUpdateError(message);
      setAppUpdateStatus(
        manual
          ? "error"
          : "idle"
      );
    } finally {
      updateOperationRef.current =
        false;
    }
  }

  async function installFyFladeUpdate() {
    if (distributionMode === "portable") {
      setUpdateError(
        ui(
          "Installer-oppdatering er deaktivert i portable-utgaven.",
          "Installer updates are disabled in the portable edition."
        )
      );
      setAppUpdateStatus("error");
      return;
    }
    if (
      updateOperationRef.current
    ) {
      return;
    }

    let update =
      availableUpdateRef.current;

    if (!update) {
      await checkForFyFladeUpdate(
        true
      );
      update =
        availableUpdateRef.current;
    }

    if (!update) {
      return;
    }

    updateOperationRef.current =
      true;
    setAppUpdateStatus(
      "downloading"
    );
    setUpdateProgress(0);
    setUpdateError("");

    let contentLength =
      0;
    let downloadedBytes =
      0;

    try {
      await update.downloadAndInstall(
        (event) => {
          if (
            event.event ===
            "Started"
          ) {
            contentLength =
              event.data
                .contentLength ||
              0;
            downloadedBytes =
              0;
            return;
          }

          if (
            event.event ===
            "Progress"
          ) {
            downloadedBytes +=
              event.data
                .chunkLength;

            if (
              contentLength > 0
            ) {
              setUpdateProgress(
                Math.min(
                  100,
                  Math.round(
                    (downloadedBytes /
                      contentLength) *
                      100
                  )
                )
              );
            }
            return;
          }

          setUpdateProgress(100);
          setAppUpdateStatus(
            "installing"
          );
        }
      );

      await relaunch();
    } catch (error) {
      const message =
        readableErrorMessage(
          error,
          ui(
            "Oppdateringen kunne ikke installeres.",
            "The update could not be installed."
          )
        );

      console.error(
        "FyFlade update installation failed",
        error
      );
      setUpdateError(message);
      setAppUpdateStatus(
        "error"
      );
    } finally {
      updateOperationRef.current =
        false;
    }
  }

  function appUpdateStatusText() {
    if (distributionMode === "portable") {
      return ui(
        "Portable-utgaven oppdateres ved å laste ned en ny portable-pakke. Innstillingene og innloggingene dine blir liggende på PC-en.",
        "The portable edition is updated by downloading a new portable package. Your settings and sign-ins remain on this PC."
      );
    }

    switch (
      appUpdateStatus
    ) {
      case "checking":
        return ui(
          "Ser etter ny versjon...",
          "Checking for a new version..."
        );
      case "current":
        return ui(
          "FyFlade er oppdatert.",
          "FyFlade is up to date."
        );
      case "available":
        return ui(
          `FyFlade ${availableUpdateVersion} er tilgjengelig.`,
          `FyFlade ${availableUpdateVersion} is available.`
        );
      case "downloading":
        return ui(
          `Laster ned oppdateringen${updateProgress > 0 ? ` (${updateProgress} %)` : ""}...`,
          `Downloading the update${updateProgress > 0 ? ` (${updateProgress}%)` : ""}...`
        );
      case "installing":
        return ui(
          "Installerer oppdateringen. FyFlade starter på nytt...",
          "Installing the update. FyFlade will restart..."
        );
      case "error":
        return updateError ||
          ui(
            "Oppdateringen kunne ikke fullføres.",
            "The update could not be completed."
          );
      default:
        return autoUpdateEnabled
          ? ui(
              "FyFlade ser automatisk etter nye versjoner.",
              "FyFlade automatically checks for new versions."
            )
          : ui(
              "Automatisk oppdateringssjekk er av.",
              "Automatic update checking is off."
            );
    }
  }

  function isBackupSafeSettingKey(
    key: string
  ) {
    return (
      (key.startsWith("chatnest.") || key === CHANNEL_SETTINGS_KEY || key === CHANNEL_IDENTITIES_KEY || key === PROFILES_KEY || key === CHAT_HISTORY_RETENTION_KEY || key === SETTINGS_NAV_ORDER_KEY || key === DISMISSED_WARNINGS_KEY || key === TTS_SETTINGS_KEY) &&
      !key.startsWith("chatnest.internal.") &&
      !/(oauth|secret|token|client.?id|webhook|banids|quota)/i.test(
        key
      )
    );
  }

  function collectBackupSafeSettings() {
    const settings:
      Record<string, string> =
      {};

    for (
      let index = 0;
      index < localStorage.length;
      index += 1
    ) {
      const key =
        localStorage.key(index);

      if (
        !key ||
        !isBackupSafeSettingKey(key)
      ) {
        continue;
      }

      const value =
        localStorage.getItem(key);

      if (value !== null) {
        settings[key] = value;
      }
    }

    return settings;
  }

  function exportFyFladeBackup() {
    try {
      const backup = {
        app: "FyFlade",
        version: 1,
        createdAt:
          new Date().toISOString(),
        settings:
          collectBackupSafeSettings(),
      };
      const blob =
        new Blob(
          [
            JSON.stringify(
              backup,
              null,
              2
            ),
          ],
          {
            type: "application/json",
          }
        );
      const url =
        URL.createObjectURL(blob);
      const link =
        document.createElement("a");
      const date =
        new Date()
          .toISOString()
          .slice(0, 10);

      link.href = url;
      link.download =
        `FyFlade-backup-${date}.json`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.setTimeout(
        () =>
          URL.revokeObjectURL(url),
        1000
      );

      setBackupStatus(
        ui(
          "✓ Sikkerhetskopien er lagret. Innloggingstokener og hemmelige nøkler er ikke tatt med.",
          "✓ Backup saved. Sign-in tokens and secret keys were not included."
        )
      );
    } catch {
      setBackupStatus(
        ui(
          "Kunne ikke lage sikkerhetskopien.",
          "Could not create the backup."
        )
      );
    }
  }

  async function importFyFladeBackup(
    file: File
  ) {
    setBackupStatus("");

    try {
      const parsed =
        JSON.parse(
          await file.text()
        ) as {
          app?: unknown;
          version?: unknown;
          settings?: unknown;
        };

      if (
        (
          parsed.app !== "FyFlade" &&
          parsed.app !== "Fyflate" &&
          parsed.app !== "Fy Flate" &&
          parsed.app !== "ChatNest"
        ) ||
        parsed.version !== 1 ||
        !parsed.settings ||
        typeof parsed.settings !== "object" ||
        Array.isArray(parsed.settings)
      ) {
        throw new Error(
          ui(
            "Filen er ikke en gyldig FyFlade-sikkerhetskopi.",
            "The file is not a valid FyFlade backup."
          )
        );
      }

      const incoming =
        Object.entries(
          parsed.settings as
            Record<string, unknown>
        ).filter(
          (entry): entry is [string, string] =>
            isBackupSafeSettingKey(entry[0]) &&
            typeof entry[1] === "string"
        );

      if (incoming.length === 0) {
        throw new Error(
          ui(
            "Sikkerhetskopien inneholder ingen innstillinger.",
            "The backup contains no settings."
          )
        );
      }

      const approved =
        window.confirm(
          ui(
            "Vil du gjenopprette denne sikkerhetskopien? Nåværende kanaler og innstillinger blir erstattet. Kontoene dine må fortsatt logges inn på denne PC-en.",
            "Restore this backup? Current channels and settings will be replaced. Your accounts must still be signed in on this PC."
          )
        );

      if (!approved) {
        return;
      }

      localStorage.setItem(
        "chatnest.internal.beforeImportBackup.v1",
        JSON.stringify({
          createdAt:
            new Date().toISOString(),
          settings:
            collectBackupSafeSettings(),
        })
      );

      const removableKeys:
        string[] = [];

      for (
        let index = 0;
        index < localStorage.length;
        index += 1
      ) {
        const key =
          localStorage.key(index);

        if (
          key &&
          isBackupSafeSettingKey(key)
        ) {
          removableKeys.push(key);
        }
      }

      removableKeys.forEach(
        (key) =>
          localStorage.removeItem(key)
      );
      incoming.forEach(
        ([key, value]) =>
          localStorage.setItem(
            key,
            value
          )
      );

      setBackupStatus(
        ui(
          "✓ Gjenopprettet. FyFlade starter innstillingene på nytt…",
          "✓ Restored. FyFlade is reloading the settings…"
        )
      );

      window.setTimeout(
        () =>
          window.location.reload(),
        700
      );
    } catch (error) {
      setBackupStatus(
        error instanceof Error
          ? error.message
          : ui(
              "Kunne ikke lese sikkerhetskopien.",
              "Could not read the backup."
            )
      );
    } finally {
      if (
        backupImportInputRef.current
      ) {
        backupImportInputRef.current.value =
          "";
      }
    }
  }

  function restoreBeforeImportBackup() {
    try {
      const raw =
        localStorage.getItem(
          "chatnest.internal.beforeImportBackup.v1"
        );
      const parsed = raw
        ? JSON.parse(raw) as {
            settings?:
              Record<string, unknown>;
          }
        : null;

      if (
        !parsed?.settings ||
        typeof parsed.settings !== "object"
      ) {
        throw new Error(
          ui(
            "Ingen tidligere innstillinger er tilgjengelige.",
            "No previous settings are available."
          )
        );
      }

      if (
        !window.confirm(
          ui(
            "Vil du angre den siste importen og gå tilbake til innstillingene du hadde før?",
            "Undo the last import and return to the settings you had before it?"
          )
        )
      ) {
        return;
      }

      const currentKeys:
        string[] = [];

      for (
        let index = 0;
        index < localStorage.length;
        index += 1
      ) {
        const key =
          localStorage.key(index);

        if (
          key &&
          isBackupSafeSettingKey(key)
        ) {
          currentKeys.push(key);
        }
      }

      currentKeys.forEach(
        (key) =>
          localStorage.removeItem(key)
      );
      Object.entries(
        parsed.settings
      ).forEach(([key, value]) => {
        if (
          isBackupSafeSettingKey(key) &&
          typeof value === "string"
        ) {
          localStorage.setItem(
            key,
            value
          );
        }
      });
      localStorage.removeItem(
        "chatnest.internal.beforeImportBackup.v1"
      );

      window.location.reload();
    } catch (error) {
      setBackupStatus(
        error instanceof Error
          ? error.message
          : ui(
              "Kunne ikke gjenopprette de tidligere innstillingene.",
              "Could not restore the previous settings."
            )
      );
    }
  }

  function setAndSaveAppearanceMode(
    mode: AppearanceMode
  ) {
    const previousDefault =
      defaultChatBackground(
        appearanceMode
      );

    setAppearanceMode(
      mode
    );

    writeSetting(
      APPEARANCE_MODE_KEY,
      mode
    );

    const nextThemeColors =
      defaultCustomThemeColors(
        mode
      );

    setCustomThemeColors(
      nextThemeColors
    );

    writeSetting(
      CUSTOM_THEME_COLORS_KEY,
      nextThemeColors
    );

    if (
      !localStorage.getItem(
        CHAT_BACKGROUND_KEY
      ) ||
      chatBackground.toLowerCase() ===
        previousDefault.toLowerCase()
    ) {
      const nextBackground =
        defaultChatBackground(
          mode
        );

      setAndSaveChatBackground(
        nextBackground
      );
    }
  }

