  function updateCustomThemeColor(
    key: keyof CustomThemeColors,
    color: string
  ) {
    if (
      !/^#[0-9a-f]{6}$/i.test(
        color
      )
    ) {
      return;
    }

    const normalized =
      color.toUpperCase();

    setCustomThemeColors(
      (
        current
      ) => {
        const next = {
          ...current,
          [key]: normalized,
        };

        writeSetting(
          CUSTOM_THEME_COLORS_KEY,
          next
        );

        return next;
      }
    );
  }

  function resetCustomThemeColor(
    key: keyof CustomThemeColors
  ) {
    updateCustomThemeColor(
      key,
      defaultCustomThemeColors(
        appearanceMode
      )[key]
    );
  }

  function resetAllAppearanceColors() {
    const defaults =
      defaultCustomThemeColors(
        appearanceMode
      );

    setUnifiedThemeEnabled(
      false
    );

    setUnifiedThemeColor(
      DEFAULT_UNIFIED_THEME_COLOR
    );

    setCustomThemeColors(
      defaults
    );

    localStorage.setItem(
      UNIFIED_THEME_ENABLED_KEY,
      "false"
    );

    localStorage.setItem(
      UNIFIED_THEME_COLOR_KEY,
      DEFAULT_UNIFIED_THEME_COLOR
    );

    localStorage.setItem(
      CUSTOM_THEME_COLORS_KEY,
      JSON.stringify(
        defaults
      )
    );

    setAndSaveChatBackground(
      defaultChatBackground(
        appearanceMode
      )
    );
  }

