  async function chooseBackgroundImage(
    file: File | null
  ) {
    if (!file) {
      return;
    }

    if (
      !file.type.startsWith(
        "image/"
      )
    ) {
      setBackgroundImageStatus(
        ui("Velg en bildefil.", "Choose an image file.")
      );
      return;
    }

    if (
      file.size >
      50 * 1024 * 1024
    ) {
      setBackgroundImageStatus(
        ui("Bildet er for stort. Maks 50 MB.", "The image is too large. Maximum 50 MB.")
      );
      return;
    }

    try {
      await saveStoredBackgroundImage(
        file
      );

      const nextUrl =
        URL.createObjectURL(
          file
        );

      if (
        backgroundImageObjectUrlRef.current
      ) {
        URL.revokeObjectURL(
          backgroundImageObjectUrlRef.current
        );
      }

      backgroundImageObjectUrlRef.current =
        nextUrl;

      setBackgroundImageUrl(
        nextUrl
      );

      setBackgroundImageName(
        file.name
      );

      localStorage.setItem(
        BACKGROUND_IMAGE_NAME_KEY,
        file.name
      );

      setBackgroundImageStatus(
        ui("Bakgrunnsbildet er lagret.", "The background image was saved.")
      );
    } catch (
      error
    ) {
      console.error(
        "Could not save background image",
        error
      );

      setBackgroundImageStatus(
        ui("Kunne ikke lagre bildet. Prøv et annet bilde.", "Could not save the image. Try another image.")
      );
    }
  }

  async function removeBackgroundImage() {
    try {
      await deleteStoredBackgroundImage();

      if (
        backgroundImageObjectUrlRef.current
      ) {
        URL.revokeObjectURL(
          backgroundImageObjectUrlRef.current
        );

        backgroundImageObjectUrlRef.current =
          "";
      }

      setBackgroundImageUrl(
        ""
      );

      setBackgroundImageName(
        ""
      );

      localStorage.removeItem(
        BACKGROUND_IMAGE_NAME_KEY
      );

      setBackgroundImageStatus(
        ui("Bakgrunnsbildet er fjernet.", "The background image was removed.")
      );
    } catch (
      error
    ) {
      console.error(
        "Could not remove background image",
        error
      );

      setBackgroundImageStatus(
        ui("Kunne ikke fjerne bildet.", "Could not remove the image.")
      );
    }
  }

