  function kickHostKeyForTab(
    tab: ChannelTab
  ) {
    if (
      tab.platform ===
      "youtube"
    ) {
      return (
        tab.youtubeChannelId ||
        tab.login
      ).toLowerCase();
    }

    return tab.login
      .toLowerCase();
  }

  function kickHostPlatformForTab(
    tab: ChannelTab
  ):
    "twitch" | "youtube" {
    return tab.platform ===
      "youtube"
      ? "youtube"
      : "twitch";
  }

  function saveLinkedKickChannels(
    channels:
      LinkedKickChannel[]
  ) {
    const deduped =
      Array.from(
        new Map(
          channels
            .filter(
              (item) =>
                Boolean(
                  item.hostKey &&
                  item.broadcasterUserId
                )
            )
            .map(
              (item) => {
                const normalized = {
                  ...item,
                  hostKey:
                    item.hostKey.toLowerCase(),
                  slug:
                    item.slug.toLowerCase(),
                };

                return [
                  `${normalized.hostPlatform}:${normalized.hostKey}`,
                  normalized,
                ];
              }
            )
        ).values()
      );

    linkedKickChannelsRef.current =
      deduped;

    localStorage.setItem(
      LINKED_KICK_CHANNELS_KEY,
      JSON.stringify(
        deduped
      )
    );
  }

  function rememberLinkedKickChannel(
    tab: ChannelTab,
    channel:
      SavedKickChannel
  ) {
    if (
      tab.platform ===
      "kick"
    ) {
      return;
    }

    const hostPlatform =
      kickHostPlatformForTab(
        tab
      );

    const hostKey =
      kickHostKeyForTab(
        tab
      );

    saveLinkedKickChannels([
      ...linkedKickChannelsRef.current.filter(
        (item) =>
          !(
            item.hostPlatform ===
              hostPlatform &&
            item.hostKey ===
              hostKey
          ) &&
          item.broadcasterUserId !==
            channel.broadcasterUserId
      ),
      {
        ...channel,
        hostPlatform,
        hostKey,
      },
    ]);
  }

  function forgetLinkedKickChannelForTab(
    tab: ChannelTab
  ) {
    if (
      tab.platform ===
      "kick"
    ) {
      return;
    }

    const hostPlatform =
      kickHostPlatformForTab(
        tab
      );

    const hostKey =
      kickHostKeyForTab(
        tab
      );

    saveLinkedKickChannels(
      linkedKickChannelsRef.current.filter(
        (item) =>
          !(
            item.hostPlatform ===
              hostPlatform &&
            item.hostKey ===
              hostKey
          )
      )
    );
  }

  function moveLinkedKickChannel(
    fromPlatform:
      "twitch" | "youtube",
    fromKey: string,
    toTab: ChannelTab
  ) {
    const linked =
      linkedKickChannelsRef.current.find(
        (item) =>
          item.hostPlatform ===
            fromPlatform &&
          item.hostKey ===
            fromKey.toLowerCase()
      );

    if (!linked) {
      return;
    }

    const toPlatform =
      kickHostPlatformForTab(
        toTab
      );
    const toKey =
      kickHostKeyForTab(
        toTab
      );

    saveLinkedKickChannels([
      ...linkedKickChannelsRef.current.filter(
        (item) =>
          !(
            item.hostPlatform ===
              fromPlatform &&
            item.hostKey ===
              fromKey.toLowerCase()
          ) &&
          !(
            item.hostPlatform ===
              toPlatform &&
            item.hostKey ===
              toKey
          )
      ),
      {
        ...linked,
        hostPlatform:
          toPlatform,
        hostKey:
          toKey,
      },
    ]);
  }

