  function isUserIgnoredForHighlights(
    platform: ChatPlatform,
    userId: string,
    userLogin = ""
  ) {
    const key = localUserKey(
      platform,
      userId,
      userLogin
    );

    return Boolean(
      (userId || userLogin) &&
      (
        ignoredHighlightUsersRef.current.includes(key) ||
        (
          platform === "twitch" &&
          Boolean(userId) &&
          ignoredHighlightUsersRef.current.includes(userId)
        )
      )
    );
  }

  function toggleIgnoreHighlights(
    platform: ChatPlatform,
    userId: string,
    userLogin: string
  ) {
    if (!userId && !userLogin) {
      return;
    }

    const key = localUserKey(
      platform,
      userId,
      userLogin
    );

    saveIgnoredHighlightUsers(
      isUserIgnoredForHighlights(
        platform,
        userId,
        userLogin
      )
        ? ignoredHighlightUsersRef.current
            .filter(
              (id) =>
                id !== key &&
                !(
                  platform === "twitch" &&
                  id === userId
                )
            )
        : [
            ...ignoredHighlightUsersRef.current,
            key,
          ]
    );
  }

