  function updateHighlightPreferences(
    platform: ChatPlatform,
    userId: string,
    login: string,
    patch: Partial<HighlightPreferences>
  ) {
    saveHighlightUsers(
      highlightUsersRef.current.map((user) =>
        user.platform === platform &&
        (
          (userId && user.userId === userId) ||
          user.login === login.toLowerCase()
        )
          ? {
              ...user,
              ...patch,
            }
          : user
      )
    );
  }

  function updateTtsSettings(
    patch: Partial<TtsSettings>
  ) {
    const next = {
      ...ttsSettingsRef.current,
      ...patch,
    };
    ttsSettingsRef.current = next;
    setTtsSettings(next);
    writeTtsSettings(next);
    if (!next.enabled && !next.hoverEnabled) stopTts();
  }

  function ttsMessageText(message: TwitchChatMessage) {
    const author = message.username || message.userLogin || "";
    const tts = ttsSettingsRef.current;
    const parts = [
      tts.includeUsername && author ? author : "",
      tts.includeMessage ? message.text : "",
    ].filter(Boolean);
    return parts.join(": ");
  }

  function messageAllowedForTts(message: TwitchChatMessage) {
    const tts = ttsSettingsRef.current;
    const platform = message.platform || "twitch";
    const author = (message.userLogin || message.username || "").toLowerCase();
    if (!tts.platforms[platform]) return false;
    if (tts.ignoreCommands && /^[!/]/.test(message.text.trim())) return false;
    if (tts.ignoreBots && /(?:^|[_-])bot$/.test(author)) return false;
    return true;
  }

  function scheduleHoverTts(message: TwitchChatMessage) {
    if (!ttsSettingsRef.current.hoverEnabled) return;
    if (hoverTtsTimerRef.current !== null) {
      window.clearTimeout(hoverTtsTimerRef.current);
    }
    hoverTtsTimerRef.current = window.setTimeout(() => {
      hoverTtsTimerRef.current = null;
      if (messageAllowedForTts(message)) {
        enqueueTts(ttsSettingsRef.current, ttsMessageText(message), { priority: 1, createdAt: message.timestampMs });
      }
    }, ttsSettingsRef.current.hoverDelayMs);
  }

  function cancelHoverTts() {
    if (hoverTtsTimerRef.current !== null) {
      window.clearTimeout(hoverTtsTimerRef.current);
      hoverTtsTimerRef.current = null;
    }
  }

  function highlightedUserForMessage(
    message: TwitchChatMessage
  ) {
    const platform =
      message.platform || "twitch";
    const login = (
      message.userLogin ||
      message.username
    ).toLowerCase();

    if (
      isUserIgnoredForHighlights(
        platform,
        message.userId,
        login
      )
    ) {
      return null;
    }

    return (
      highlightUsersRef.current.find(
        (user) =>
          user.platform === platform &&
          (
            Boolean(
              message.userId &&
              user.userId === message.userId
            ) || user.login === login
          )
      ) || null
    );
  }

  function testHighlightSound(
    soundId: HighlightSoundId,
    volume = 0.7,
    customSoundDataUrl = ""
  ) {
    if (soundId === "custom" && customSoundDataUrl.startsWith("data:audio/")) {
      const audio = new Audio(customSoundDataUrl);
      audio.volume = Math.max(0, Math.min(1, volume));
      void audio.play().catch(() => undefined);
      return;
    }

    const context =
      getMentionAudioContext();

    if (!context) {
      return;
    }

    const play = () =>
      playBuiltInHighlightSound(
        context,
        soundId === "custom" ? "pling" : soundId,
        volume
      );

    if (context.state === "suspended") {
      void context.resume().then(play).catch(() => undefined);
    } else {
      play();
    }
  }

  function triggerHighlightFeedback(
    message: TwitchChatMessage,
    channelId = ""
  ) {
    if (messageIsLocallyIgnored(message)) {
      return;
    }

    if (
      channelId &&
      !channelOverride(channelId, "highlights", true)
    ) {
      return;
    }

    const highlighted =
      highlightedUserForMessage(
        message
      );

    const tts = ttsSettingsRef.current;
    const shouldSpeak = tts.enabled && (
      tts.mode === "all" ||
      (tts.mode === "mentions" && storedMessageMentionsMe(message)) ||
      (tts.mode === "highlights" && Boolean(highlighted))
    );

    if (shouldSpeak && messageAllowedForTts(message)) {
      enqueueTts(tts, ttsMessageText(message), {
        priority: storedMessageMentionsMe(message) ? 5 : highlighted ? 3 : 1,
        createdAt: message.timestampMs,
      });
    }

    if (!highlighted) {
      return;
    }

    if (
      (channelId ? channelOverride(channelId, "highlightSound", highlighted.soundEnabled) : highlighted.soundEnabled)
    ) {
      testHighlightSound(
        highlighted.soundId,
        highlighted.soundVolume,
        highlighted.customSoundDataUrl
      );
    }

    if (
      highlighted.pulseEnabled &&
      !reducedMotionEnabled &&
      !highlightPulseDisabled
    ) {
      previewHighlightPulse(
        highlighted.color,
        highlighted.pulseStrength,
        highlighted.pulseSpeed
      );
    }
  }

  function saveCustomHighlightSound(
    user: HighlightUser,
    file: File | undefined
  ) {
    if (!file) return;
    if (!file.type.startsWith("audio/") || file.size > 750 * 1024) {
      window.alert(
        ui(
          "Velg en lydfil på maksimalt 750 KB.",
          "Choose an audio file no larger than 750 KB."
        )
      );
      return;
    }

    const reader = new FileReader();
    reader.onload = () => {
      const dataUrl = typeof reader.result === "string" ? reader.result : "";
      if (!dataUrl.startsWith("data:audio/") || dataUrl.length > 1_100_000) return;
      const otherStoredAudioSize = highlightUsersRef.current.reduce(
        (total, item) =>
          item.platform === user.platform && item.userId === user.userId && item.login === user.login
            ? total
            : total + item.customSoundDataUrl.length,
        0
      );
      if (otherStoredAudioSize + dataUrl.length > 2_500_000) {
        window.alert(
          ui(
            "Egne highlight-lyder bruker allerede maksimal lokal lagringsplass. Bytt eller fjern en eksisterende lyd først.",
            "Custom highlight sounds already use the maximum local storage. Replace or remove an existing sound first."
          )
        );
        return;
      }
      updateHighlightPreferences(user.platform, user.userId, user.login, {
        soundId: "custom",
        customSoundDataUrl: dataUrl,
        customSoundName: file.name,
        soundEnabled: true,
      });
    };
    reader.readAsDataURL(file);
  }

  function previewHighlightPulse(
    color: string,
    strength: HighlightPulseStrength,
    speed: HighlightPulseSpeed = "normal"
  ) {
    if (
      reducedMotionEnabled ||
      highlightPulseDisabled
    ) {
      return;
    }

    if (highlightPulseTimerRef.current !== null) {
      window.clearTimeout(
        highlightPulseTimerRef.current
      );
    }

    setHighlightPulse({
      id: Date.now(),
      color,
      strength,
      speed,
    });

    highlightPulseTimerRef.current =
      window.setTimeout(() => {
        setHighlightPulse(null);
        highlightPulseTimerRef.current = null;
      }, speed === "slow" ? 1250 : speed === "fast" ? 550 : 850);
  }

  function saveLocalNicknames(
    nicknames: Record<string, LocalNickname>
  ) {
    setLocalNicknames(nicknames);
    writeSetting(
      LOCAL_NICKNAMES_KEY,
      nicknames
    );
  }

  function dismissUndoNotice() {
    if (undoNoticeTimerRef.current !== null) {
      window.clearTimeout(
        undoNoticeTimerRef.current
      );
      undoNoticeTimerRef.current = null;
    }
    setUndoNotice(null);
  }

  function showUndoAction(
    message: string,
    undo: () => void
  ) {
    if (undoNoticeTimerRef.current !== null) {
      window.clearTimeout(
        undoNoticeTimerRef.current
      );
    }

    setUndoNotice({
      id: Date.now(),
      message,
      undo,
    });
    undoNoticeTimerRef.current =
      window.setTimeout(() => {
        setUndoNotice(null);
        undoNoticeTimerRef.current = null;
      }, 10_000);
  }

  function runUndoAction() {
    const action = undoNotice;
    dismissUndoNotice();
    action?.undo();
  }

  function nicknameForUser(
    platform: ChatPlatform,
    userId: string,
    userLogin: string
  ) {
    return localNicknames[
      localUserKey(
        platform,
        userId,
        userLogin
      )
    ]?.nickname || "";
  }

  function presentedUserName(
    platform: ChatPlatform,
    userId: string,
    userLogin: string,
    originalName: string
  ) {
    const nickname = nicknameForUser(
      platform,
      userId,
      userLogin
    );

    if (!nickname) {
      return originalName;
    }

    return showOriginalWithNickname
      ? `${nickname} (${originalName})`
      : nickname;
  }

  function presentedMessageUsername(
    message: TwitchChatMessage
  ) {
    return presentedUserName(
      message.platform || "twitch",
      message.userId,
      message.userLogin,
      message.username
    );
  }

  function commitNicknameForUser(
    rawNickname: string
  ) {
    if (!userCard) {
      return;
    }

    const key = localUserKey(
      userCard.platform,
      userCard.userId,
      userCard.userLogin
    );
    const nickname = rawNickname.trim().slice(0, 40);
    const previous = localNicknames[key] || null;
    const next = {
      ...localNicknames,
    };

    if (nickname) {
      next[key] = {
        platform: userCard.platform,
        userId: userCard.userId,
        userLogin: userCard.userLogin,
        nickname,
        updatedAt: Date.now(),
      };
    } else {
      delete next[key];
    }

    saveLocalNicknames(next);
    setShowNicknameEditor(false);
    const status = nickname
      ? ui(`✓ Kallenavnet ${nickname} er lagret lokalt.`, `✓ The nickname ${nickname} was saved locally.`)
      : ui("✓ Kallenavnet er fjernet.", "✓ The nickname was removed.");
    setUserCardActionStatus(status);
    showUndoAction(
      status.replace(/^✓\s*/, ""),
      () => {
        const restored = {
          ...readLocalNicknames(),
        };
        if (previous) {
          restored[key] = previous;
        } else {
          delete restored[key];
        }
        saveLocalNicknames(restored);
        setUserCardActionStatus(
          ui("✓ Kallenavnsendringen ble angret.", "✓ The nickname change was undone.")
        );
      }
    );
  }

  function saveNicknameForUser() {
    commitNicknameForUser(
      nicknameDraft
    );
  }

  function removeNicknameForUser() {
    commitNicknameForUser("");
  }

  function saveLocalIgnores(
    ignores: LocalIgnore[]
  ) {
    const active = normalizeIgnores(
      ignores
    );
    localIgnoresRef.current = active;
    setLocalIgnores(active);
    writeSetting(
      LOCAL_IGNORES_KEY,
      active
    );
  }

  function clearAllLocalNicknames() {
    const previous = {
      ...localNicknames,
    };

    if (Object.keys(previous).length === 0) {
      setPrivacyStatus(
        ui("Ingen lokale kallenavn er lagret.", "No local nicknames are saved.")
      );
      return;
    }

    if (
      !window.confirm(
        ui("Vil du slette alle lokale kallenavn? Kontoer og ekte brukernavn påvirkes ikke.", "Delete all local nicknames? Accounts and real usernames are not affected.")
      )
    ) {
      return;
    }

    saveLocalNicknames({});
    setPrivacyStatus(
      ui("✓ Alle lokale kallenavn er slettet.", "✓ All local nicknames were deleted.")
    );
    showUndoAction(
      ui("Alle lokale kallenavn er slettet.", "All local nicknames were deleted."),
      () => {
        saveLocalNicknames(previous);
        setPrivacyStatus(
          ui("✓ Kallenavnene er gjenopprettet.", "✓ The nicknames were restored.")
        );
      }
    );
  }

  function clearAllLocalIgnores() {
    const previous = [
      ...localIgnoresRef.current,
    ];

    if (previous.length === 0) {
      setPrivacyStatus(
        ui("Ingen lokale ignoreringer er lagret.", "No local ignores are saved.")
      );
      return;
    }

    if (
      !window.confirm(
        ui("Vil du fjerne alle lokale ignoreringer? Alle brukerne blir synlige i FyFlade igjen.", "Remove all local ignores? Every user will become visible in FyFlade again.")
      )
    ) {
      return;
    }

    saveLocalIgnores([]);
    setPrivacyStatus(
      ui("✓ Alle lokale ignoreringer er fjernet.", "✓ All local ignores were removed.")
    );
    showUndoAction(
      ui("Alle lokale ignoreringer er fjernet.", "All local ignores were removed."),
      () => {
        saveLocalIgnores(previous);
        setPrivacyStatus(
          ui("✓ Ignoreringene er gjenopprettet.", "✓ The ignores were restored.")
        );
      }
    );
  }

  function clearTemporaryCaches() {
    channelCacheRef.current = [];
    youtubeLiveDiscoveryCacheRef.current.clear();
    youtubeMetadataCacheRef.current.clear();
    youtubeLiveDiscoveryInFlightRef.current.clear();
    kickBadgeCatalogCacheRef.current = {};
    sevenTvGlobalEmotesRef.current = {};
    sevenTvChannelEmotesRef.current = {};
    bttvGlobalEmotesRef.current = {};
    bttvChannelEmotesRef.current = {};
    thirdPartyEmoteLoadedAtRef.current = {};
    sevenTvChannelSetIdsRef.current = {};
    sevenTvSetChannelIdsRef.current = {};
    sevenTvCosmeticsCacheRef.current = {};
    sevenTvCosmeticsQueueRef.current = {};
    sevenTvCosmeticsLoadingRef.current.clear();
    localStorage.removeItem(CHANNEL_CACHE_KEY);
    localStorage.removeItem(YOUTUBE_PROFILE_CACHE_KEY);
    bumpThirdPartyEmotes();
    setSevenTvCosmeticsVersion((current) => current + 1);
    setPrivacyStatus(
      ui(
        "✓ Midlertidig kanal-, emote- og profilcache er tømt. Kontoer, innstillinger og chat-historikk er beholdt.",
        "✓ Temporary channel, emote, and profile caches were cleared. Accounts, settings, and chat history were kept."
      )
    );
  }

  async function sendAnonymousDailyUsage() {
    if (!anonymousUsageEnabled) {
      return;
    }
    const today = new Date().toISOString().slice(0, 10);
    if (
      localStorage.getItem(ANONYMOUS_USAGE_LAST_SENT_DAY_KEY) === today
    ) {
      return;
    }
    localStorage.setItem(ANONYMOUS_USAGE_LAST_SENT_DAY_KEY, today);
    try {
      const response = await fetch(`${KICK_RELAY_URL}/usage`, {
        method: "POST",
      });
      if (!response.ok) {
        throw new Error(`Usage endpoint returned ${response.status}.`);
      }
    } catch {
      // Anonymous statistics must never interrupt chat or sign-in.
    }
  }

  function changeAnonymousUsageEnabled(enabled: boolean) {
    setAnonymousUsageEnabled(enabled);
    writeSetting(ANONYMOUS_USAGE_ENABLED_KEY, enabled);
    if (enabled) {
      setPrivacyStatus(
        ui(
          "✓ Anonym brukstelling er slått på.",
          "✓ Anonymous usage counting is enabled."
        )
      );
    } else {
      localStorage.removeItem(ANONYMOUS_USAGE_LAST_SENT_DAY_KEY);
      setPrivacyStatus(
        ui(
          "✓ Anonym brukstelling er slått av.",
          "✓ Anonymous usage counting is disabled."
        )
      );
    }
  }

  function messageIsLocallyIgnored(
    message: TwitchChatMessage
  ) {
    return isUserLocallyIgnored(
      localIgnoresRef.current,
      message.platform || "twitch",
      message.userId,
      message.userLogin || message.username
    );
  }

  function locallyIgnoreUser(
    duration: IgnoreDuration
  ) {
    if (!userCard) {
      return;
    }

    const entry = createLocalIgnore({
      platform: userCard.platform,
      userId: userCard.userId,
      userLogin: userCard.userLogin,
      displayName: userCard.username,
      channelId: userCard.broadcasterId,
      duration,
    });
    const key = localUserKey(
      entry.platform,
      entry.userId,
      entry.userLogin
    );
    const previous = localIgnoresRef.current.find(
      (item) =>
        localUserKey(
          item.platform,
          item.userId,
          item.userLogin
        ) === key
    ) || null;
    saveLocalIgnores([
      ...localIgnoresRef.current.filter(
        (item) =>
          localUserKey(
            item.platform,
            item.userId,
            item.userLogin
          ) !== key
      ),
      entry,
    ]);
    setLastIgnoreUndo(null);
    setShowIgnoreMenu(false);

    const durationLabel =
      duration === "10m"
        ? ui("10 minutter", "10 minutes")
        : duration === "1h"
          ? ui("1 time", "1 hour")
          : duration === "stream"
            ? ui("resten av sendingen", "the rest of the stream")
            : ui("permanent", "permanently");
    const status =
      `✓ ${userCard.username} ${ui("er ignorert i", "is ignored for")} ${durationLabel}.`;
    setUserCardActionStatus(status);
    showUndoAction(
      status.replace(/^✓\s*/, ""),
      () => {
        const current = readLocalIgnores().filter(
          (item) =>
            localUserKey(
              item.platform,
              item.userId,
              item.userLogin
            ) !== key
        );
        saveLocalIgnores(
          previous
            ? [...current, previous]
            : current
        );
        setUserCardActionStatus(
          ui("✓ Ignoreringen ble angret.", "✓ The ignore was undone.")
        );
      }
    );
  }

  function removeLocalIgnore(
    entry: LocalIgnore,
    offerUndo = true
  ) {
    const key = localUserKey(
      entry.platform,
      entry.userId,
      entry.userLogin
    );
    saveLocalIgnores(
      localIgnoresRef.current.filter(
        (item) =>
          localUserKey(
            item.platform,
            item.userId,
            item.userLogin
          ) !== key
      )
    );

    if (offerUndo) {
      showUndoAction(
        ui(
          `${entry.displayName} vises i chatten igjen.`,
          `${entry.displayName} is visible in chat again.`
        ),
        () => {
          const current = readLocalIgnores().filter(
            (item) =>
              localUserKey(
                item.platform,
                item.userId,
                item.userLogin
              ) !== key
          );
          saveLocalIgnores([
            ...current,
            entry,
          ]);
        }
      );
    }
  }

  function isHighlightedUser(
    platform: ChatPlatform,
    userId: string,
    login: string
  ) {
    const cleanLogin =
      login.toLowerCase();

    return highlightUsersRef.current
      .some(
        (
          user
        ) =>
          user.platform === platform &&
          (
            (
              userId &&
              user.userId === userId
            ) ||
            user.login === cleanLogin
          )
      );
  }

  function toggleUserHighlight(
    platform: ChatPlatform,
    userId: string,
    login: string,
    displayName: string
  ) {
    const cleanLogin =
      login.toLowerCase();

    if (
      isHighlightedUser(
        platform,
        userId,
        cleanLogin
      )
    ) {
      saveHighlightUsers(
        highlightUsersRef.current
          .filter(
            (
              user
            ) =>
              !(
                user.platform === platform &&
                (
                  (
                    userId &&
                    user.userId === userId
                  ) ||
                  user.login === cleanLogin
                )
              )
          )
      );

      return;
    }

    saveHighlightUsers([
      ...highlightUsersRef.current,

      {
        ...DEFAULT_HIGHLIGHT_PREFERENCES,

        platform,

        userId,

        login:
          cleanLogin,

        displayName,
      },
    ]);
  }

  async function addHighlightUserFromSettings() {
    const login =
      sanitizeChannelName(
        highlightInput
      );

    if (
      !login
    ) {
      setHighlightError(
        ui("Skriv inn et Twitch-navn.", "Enter a Twitch name.")
      );

      return;
    }

    setAddingHighlight(
      true
    );

    setHighlightError(
      ""
    );

    try {
      const user =
        await getTwitchUserByLogin(
          login
        );

      if (
        isHighlightedUser(
          "twitch",
          user.id,
          user.login
        )
      ) {
        setHighlightError(
          ui(`${user.display_name} er allerede på markeringslisten.`, `${user.display_name} is already on the highlight list.`)
        );

        return;
      }

      saveHighlightUsers([
        ...highlightUsersRef.current,

        {
          ...DEFAULT_HIGHLIGHT_PREFERENCES,

          platform:
            "twitch",

          userId:
            user.id,

          login:
            user.login.toLowerCase(),

          displayName:
            user.display_name,
        },
      ]);

      setHighlightInput(
        ""
      );
    } catch (
      error
    ) {
      setHighlightError(
        error instanceof
        Error
          ? error.message
          : ui("Kunne ikke finne brukeren.", "Could not find the user.")
      );
    } finally {
      setAddingHighlight(
        false
      );
    }
  }

  function setAndSaveFontSize(
    size: number
  ) {
    const clean =
      Math.max(
        10,
        Math.min(
          24,
          Math.round(
            size
          )
        )
      );

    setChatFontSize(
      clean
    );

    writeSettingDebounced(
      CHAT_FONT_SIZE_KEY,
      clean
    );
  }

