  async function copyKickWebhookUrl() {
    const webhookUrl =
      kickTunnelStatus.webhookUrl;

    if (
      !webhookUrl
    ) {
      setKickSetupError(
        ui("Den offentlige webhook-adressen er ikke klar ennå.", "The public webhook address is not ready yet.")
      );
      return;
    }

    try {
      await navigator.clipboard.writeText(
        webhookUrl
      );
      setKickSetupError(
        ""
      );
      setAccountNotice(
        ui("✓ Webhook-adressen er kopiert. Lim den inn under Webhooks i Kick Developer og lagre.", "✓ The webhook address was copied. Paste it under Webhooks in Kick Developer and save.")
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke kopiere Kick webhook-adressen:",
        error
      );
      setKickSetupError(
        ui("Kunne ikke kopiere automatisk. Marker adressen og kopier den manuelt.", "Could not copy automatically. Select the address and copy it manually.")
      );
    }
  }

  function confirmKickWebhookUrl() {
    const webhookUrl =
      kickTunnelStatus.webhookUrl;

    if (
      !kickPublicWebhookReady ||
      !webhookUrl
    ) {
      setKickSetupError(
        ui("Vent til den offentlige tunnelen er klar.", "Wait until the public tunnel is ready.")
      );
      return;
    }

    localStorage.setItem(
      KICK_WEBHOOK_CONFIRMED_URL_KEY,
      webhookUrl
    );

    kickSubscriptionSyncQueueRef.current.clear();
    setKickConfirmedWebhookUrl(
      webhookUrl
    );
    setKickSetupError(
      ""
    );
    setAccountNotice(
      ui("✓ Kick-webhooken er bekreftet. FyFlade fornyer nå chat-abonnementene.", "✓ The Kick webhook is confirmed. FyFlade is now renewing the chat subscriptions.")
    );
  }

  async function saveKickRefreshToken(
    refreshToken: string
  ) {
    await invoke(
      "save_kick_refresh_token",
      {
        refreshToken,
      }
    );
  }

  async function deleteSavedKickLogin() {
    await invoke(
      "delete_kick_refresh_token"
    );
  }

  async function getLoggedInKickUser(
    accessToken: string
  ):
    Promise<KickUserProfile> {
    const response =
      await fetch(
        "https://api.kick.com/public/v1/users",
        {
          headers: {
            Authorization:
              `Bearer ${accessToken}`,

            Accept:
              "application/json",
          },
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke hente Kick-brukeren (HTTP ${response.status}).`, `Could not load the Kick user (HTTP ${response.status}).`)
      );
    }

    const data =
      (
        await response.json()
      ) as KickUsersResponse;

    const user =
      data.data?.[0];

    if (
      !user
    ) {
      throw new Error(
        ui("Kick-kontoen ble godkjent, men API-et returnerte ingen bruker.", "The Kick account was approved, but the API returned no user.")
      );
    }

    const username =
      String(
        user.username ||
        user.name ||
        "Kick"
      );

    return {
      id:
        String(
          user.user_id ||
          user.id ||
          ""
        ),

      username,

      slug:
        String(
          user.channel_slug ||
          user.slug ||
          username
            .toLowerCase()
            .replace(
              /\s+/g,
              ""
            )
        ),

      avatarUrl:
        String(
          user.profile_picture ||
          user.profile_picture_url ||
          ""
        ),
    };
  }

  function applyKickUser(
    user: KickUserProfile,
    accessToken: string
  ) {
    kickAccessTokenRef.current =
      accessToken;

    setKickUserId(
      user.id
    );

    setKickUsername(
      user.username
    );

    setKickChannelSlug(
      user.slug
    );

    setKickAvatar(
      user.avatarUrl
    );

    setKickConnected(
      true
    );

    setKickLoginError(
      ""
    );

    void connectKickRelay(
      accessToken
    );
  }

  async function kickRelayError(
    response: Response,
    fallback: string
  ) {
    const raw =
      await response.text();

    try {
      const parsed =
        JSON.parse(
          raw
        ) as {
          error?: string;
          message?: string;
        };

      return (
        parsed.error ||
        parsed.message ||
        fallback
      );
    } catch {
      return raw.trim() ||
        fallback;
    }
  }

  async function loadKickRelayConfig() {
    const response =
      await fetch(
        `${KICK_RELAY_URL}/config`,
        {
          headers: {
            Accept:
              "application/json",
          },
        }
      );

    if (!response.ok) {
      throw new Error(
        ui("FyFlade sin Kick-tjeneste er ikke tilgjengelig akkurat nå.", "FyFlade's Kick service is not available right now.")
      );
    }

    const config =
      (await response.json()) as KickRelayConfig;

    if (
      !config.configured ||
      !config.clientId ||
      config.redirectUri !==
        KICK_REDIRECT_URI
    ) {
      setKickRelayConfig(
        config
      );

      throw new Error(
        ui("FyFlade sin Kick-tjeneste er ikke ferdig konfigurert ennå.", "FyFlade's Kick service is not fully configured yet.")
      );
    }

    localStorage.setItem(
      KICK_OAUTH_CLIENT_ID_KEY,
      config.clientId
    );

    setKickOAuthClientId(
      config.clientId
    );

    setKickRelayConfig(
      config
    );

    return config;
  }

  function kickRelayBroadcasterIds() {
    return Array.from(
      new Set(
        channelTabsRef.current
          .map(
            (tab) =>
              tab.kickBroadcasterUserId ||
              ""
          )
          .filter(Boolean)
      )
    );
  }

  function syncKickRelaySubscriptions() {
    const socket =
      kickRelaySocketRef.current;

    if (
      !socket ||
      socket.readyState !==
        WebSocket.OPEN
    ) {
      return;
    }

    socket.send(
      JSON.stringify({
        type:
          "subscribe",
        broadcasterIds:
          kickRelayBroadcasterIds(),
      })
    );
  }

  function scheduleKickRelayReconnect(
    accessToken: string,
    generation: number
  ) {
    if (
      generation !==
        kickRelayGenerationRef.current ||
      accessToken !==
        kickAccessTokenRef.current
    ) {
      return;
    }

    if (!navigator.onLine) {
      setKickRelaySocketStatus(
        "error"
      );
      return;
    }

    setKickRelaySocketStatus(
      "error"
    );

    kickRelayReconnectAttemptRef.current +=
      1;

    const delay =
      Math.min(
        30_000,
        1_000 *
          2 **
            Math.min(
              kickRelayReconnectAttemptRef.current -
                1,
              5
            )
      );

    if (
      kickRelayReconnectTimerRef.current !==
      null
    ) {
      window.clearTimeout(
        kickRelayReconnectTimerRef.current
      );
    }

    kickRelayReconnectTimerRef.current =
      window.setTimeout(
        () => {
          kickRelayReconnectTimerRef.current =
            null;

          void openKickRelaySocket(
            accessToken,
            generation
          ).catch(
            () =>
              scheduleKickRelayReconnect(
                accessToken,
                generation
              )
          );
        },
        delay
      );
  }

  async function openKickRelaySocket(
    accessToken: string,
    generation: number
  ) {
    setKickRelaySocketStatus(
      "connecting"
    );

    const ticketResponse =
      await fetch(
        `${KICK_RELAY_URL}/relay/ticket`,
        {
          method:
            "POST",
          headers: {
            Authorization:
              `Bearer ${accessToken}`,
            Accept:
              "application/json",
          },
        }
      );

    if (!ticketResponse.ok) {
      throw new Error(
        await kickRelayError(
          ticketResponse,
          ui("Kunne ikke koble til Kick-chatten.", "Could not connect to Kick chat.")
        )
      );
    }

    const ticketData =
      (await ticketResponse.json()) as {
        ticket?: string;
      };

    if (!ticketData.ticket) {
      throw new Error(
        ui("Kick-tjenesten returnerte ingen tilkoblingsnøkkel.", "The Kick service returned no connection ticket.")
      );
    }

    if (
      generation !==
      kickRelayGenerationRef.current
    ) {
      return;
    }

    const socketUrl =
      KICK_RELAY_URL.replace(
        /^http/i,
        "ws"
      ) +
      `/relay?ticket=${encodeURIComponent(
        ticketData.ticket
      )}`;

    const socket =
      new WebSocket(
        socketUrl
      );

    kickRelaySocketRef.current =
      socket;

    socket.onopen =
      () => {
        if (
          generation !==
          kickRelayGenerationRef.current
        ) {
          socket.close();
          return;
        }

        kickRelayReconnectAttemptRef.current =
          0;

        setKickRelaySocketStatus(
          "ready"
        );

        syncKickRelaySubscriptions();
      };

    socket.onmessage =
      (event) => {
        try {
          const message =
            JSON.parse(
              String(
                event.data ||
                ""
              )
            ) as {
              type?: string;
              payload?: string[];
              broadcasterIds?: string[];
            };

          if (
            message.type ===
              "subscribed" &&
            Array.isArray(
              message.broadcasterIds
            )
          ) {
            setKickRelaySubscribedBroadcasterIds(
              message.broadcasterIds.map(
                (id) => String(id)
              )
            );
            return;
          }

          if (
            message.type ===
              "kick-webhook-event" &&
            Array.isArray(
              message.payload
            )
          ) {
            setKickRelayLastMessageAt(
              Date.now()
            );
            void processKickWebhookEvent(
              message.payload
            );
          }
        } catch {
          // Ignorer ukjente kontrollmeldinger fra reléet.
        }
      };

    socket.onerror =
      () => {
        if (
          generation ===
          kickRelayGenerationRef.current
        ) {
          setKickRelaySocketStatus(
            "error"
          );
        }
      };

    socket.onclose =
      () => {
        if (
          kickRelaySocketRef.current ===
          socket
        ) {
          kickRelaySocketRef.current =
            null;

          setKickRelaySubscribedBroadcasterIds(
            []
          );
        }

        scheduleKickRelayReconnect(
          accessToken,
          generation
        );
      };
  }

  async function connectKickRelay(
    accessToken: string
  ) {
    kickRelayGenerationRef.current +=
      1;

    const generation =
      kickRelayGenerationRef.current;

    if (
      kickRelayReconnectTimerRef.current !==
      null
    ) {
      window.clearTimeout(
        kickRelayReconnectTimerRef.current
      );

      kickRelayReconnectTimerRef.current =
        null;
    }

    kickRelaySocketRef.current
      ?.close();

    kickRelaySocketRef.current =
      null;

    kickRelayReconnectAttemptRef.current =
      0;

    await openKickRelaySocket(
      accessToken,
      generation
    ).catch(
      (error) => {
        console.error(
          "Kick relay:",
          safeDiagnosticError(error)
        );

        scheduleKickRelayReconnect(
          accessToken,
          generation
        );
      }
    );
  }

  async function loadKickClientSecret() {
    const secret =
      await invoke<
        string | null
      >(
        "load_kick_client_secret"
      );

    setKickClientSecretSaved(
      Boolean(
        secret
      )
    );

    return secret ||
      "";
  }

  async function exchangeKickAuthorizationCode(
    code: string,
    codeVerifier: string,
    redirectUri: string
  ) {
    const response =
      await fetch(
        `${KICK_RELAY_URL}/oauth/token`,
        {
          method:
            "POST",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",
          },

          body:
            JSON.stringify({
              grant_type:
                "authorization_code",
              redirect_uri:
                redirectUri,
              code_verifier:
                codeVerifier,
              code,
            }),
        }
      );

    if (
      !response.ok
    ) {
      const raw =
        await response.text();

      let message =
        raw;

      try {
        const parsed =
          JSON.parse(
            raw
          ) as {
            error?: string;
            error_description?: string;
            message?: string;
          };

        message =
          parsed.error_description ||
          parsed.message ||
          parsed.error ||
          raw;
      } catch {
        // vanlig tekst
      }

      throw new Error(
        message ||
        ui(`Kick-tokenutvekslingen mislyktes (HTTP ${response.status}).`, `Kick token exchange failed (HTTP ${response.status}).`)
      );
    }

    return (
      await response.json()
    ) as KickTokenResponse;
  }

  async function finishKickLogin(
    tokenData: KickTokenResponse
  ) {
    if (
      !tokenData.access_token
    ) {
      throw new Error(
        ui("Kick returnerte ikke et tilgangstoken.", "Kick did not return an access token.")
      );
    }

    if (
      tokenData.refresh_token
    ) {
      await saveKickRefreshToken(
        tokenData.refresh_token
      );
    } else {
      const existing =
        await invoke<
          string | null
        >(
          "load_kick_refresh_token"
        );

      if (
        !existing
      ) {
        throw new Error(
          ui("Kick returnerte ikke et oppdateringstoken. Prøv å logge inn igjen.", "Kick did not return a refresh token. Try signing in again.")
        );
      }
    }

    const user =
      await getLoggedInKickUser(
        tokenData.access_token
      );

    setHasSavedKickSession(
      true
    );

    applyKickUser(
      user,
      tokenData.access_token
    );

    setAccountNotice(
      ui(`✓ Kick er koblet til som ${user.username}.`, `✓ Kick is connected as ${user.username}.`)
    );

    setShowAddAccount(
      false
    );

    setShowKickSetup(
      false
    );
  }

  async function connectKick() {
    setConnectingKick(
      true
    );

    setKickLoginError(
      ""
    );

    setAccountNotice(
      ""
    );

    let unlisten:
      | (() => void)
      | null =
      null;

    let timeoutId:
      | number
      | null =
      null;

    try {
      const relayConfig =
        await loadKickRelayConfig();

      const clientId =
        relayConfig.clientId;

      const state =
        randomBase64Url(
          32
        );

      const codeVerifier =
        randomBase64Url(
          64
        );

      const codeChallenge =
        await sha256Base64Url(
          codeVerifier
        );

      let resolveCallback:
        (code: string) => void =
        () => undefined;

      let rejectCallback:
        (error: Error) => void =
        () => undefined;

      const callbackPromise =
        new Promise<string>(
          (
            resolve,
            reject
          ) => {
            resolveCallback =
              resolve;

            rejectCallback =
              reject;
          }
        );

      // Registrer event-listener FØR den lokale OAuth-serveren startes,
      // så vi ikke kan miste en rask callback fra Kick.
      unlisten =
        await listen<string>(
          "kick-oauth-result",
          (
            event
          ) => {
            const payload =
              String(
                event.payload ||
                ""
              );

            if (
              payload.startsWith(
                "ok:"
              )
            ) {
              resolveCallback(
                payload.slice(
                  3
                )
              );

              return;
            }

            if (
              payload.startsWith(
                "error:"
              )
            ) {
              rejectCallback(
                new Error(
                  payload.slice(
                    6
                  ) ||
                  ui("Kick-innloggingen mislyktes.", "Kick sign-in failed.")
                )
              );
            }
          }
        );

      await invoke<number>(
        "start_kick_oauth_listener",
        {
          expectedState:
            state,
        }
      );

      timeoutId =
        window.setTimeout(
          () => {
            rejectCallback(
              new Error(
                ui("Kick-innloggingen gikk ut på tid. Prøv igjen.", "Kick sign-in timed out. Try again.")
              )
            );
          },
          305000
        );

      const params =
        new URLSearchParams({
          response_type:
            "code",

          client_id:
            clientId,

          redirect_uri:
            KICK_REDIRECT_URI,

          state,

          scope:
            KICK_OAUTH_SCOPE,

          code_challenge:
            codeChallenge,

          code_challenge_method:
            "S256",
        });

      await openUrl(
        "https://id.kick.com/oauth/authorize?" +
          params.toString()
      );

      setAccountNotice(
        ui("Venter på Kick-godkjenning i nettleseren...", "Waiting for Kick approval in the browser...")
      );

      const code =
        await callbackPromise;

      const tokenData =
        await exchangeKickAuthorizationCode(
          code,
          codeVerifier,
          KICK_REDIRECT_URI
        );

      await finishKickLogin(
        tokenData
      );
    } catch (
      error
    ) {
      const message =
        readableErrorMessage(
          error,
          ui("Kick-innloggingen mislyktes.", "Kick sign-in failed.")
        );

      console.error(
        "Kick-login feilet:",
        safeDiagnosticError(error)
      );

      setKickLoginError(
        message
      );

      setAccountNotice(
        message
      );
    } finally {
      if (
        timeoutId !==
        null
      ) {
        window.clearTimeout(
          timeoutId
        );
      }

      unlisten?.();

      setConnectingKick(
        false
      );
    }
  }

  async function restoreKickLogin() {
    try {
      const refreshToken =
        await invoke<
          string | null
        >(
          "load_kick_refresh_token"
        );

      if (
        !refreshToken
      ) {
        setHasSavedKickSession(
          false
        );
        return;
      }

      setHasSavedKickSession(
        true
      );

      setConnectingKick(
        true
      );

      await loadKickRelayConfig();

      const response =
        await fetch(
          `${KICK_RELAY_URL}/oauth/token`,
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/json",

              Accept:
                "application/json",
            },

            body:
              JSON.stringify({
                grant_type:
                  "refresh_token",
                refresh_token:
                  refreshToken,
              }),
          }
        );

      if (
        !response.ok
      ) {
        throw new Error(
          response.status === 400 ||
          response.status === 401
            ? ui("Kick-innloggingen er utløpt. Logg inn på nytt fra Kontoer.", "Kick sign-in has expired. Sign in again from Accounts.")
            : ui("Kick kunne ikke kobles til akkurat nå. FyFlade prøver igjen når nettet er tilbake.", "Kick could not connect right now. FyFlade will retry when the network returns.")
        );
      }

      const tokenData =
        (
          await response.json()
        ) as KickTokenResponse;

      if (
        tokenData.refresh_token
      ) {
        await saveKickRefreshToken(
          tokenData.refresh_token
        );
      }

      const user =
        await getLoggedInKickUser(
          tokenData.access_token
        );

      applyKickUser(
        user,
        tokenData.access_token
      );
    } catch (
      error
    ) {
      console.error(
        "Kick auto-login feilet:",
        safeDiagnosticError(error)
      );

      setKickConnected(
        false
      );

      kickAccessTokenRef.current =
        "";

      setKickLoginError(
        readableErrorMessage(
          error,
          ui("Kick kunne ikke kobles til akkurat nå.", "Kick could not connect right now.")
        )
      );
    } finally {
      setConnectingKick(
        false
      );
    }
  }

  async function disconnectKick() {
    setConnectingKick(
      true
    );

    setKickLoginError(
      ""
    );

    try {
      const accessToken =
        kickAccessTokenRef.current;

      if (
        accessToken
      ) {
        const params =
          new URLSearchParams({
            token:
              accessToken,

            token_hint_type:
              "access_token",
          });

        await fetch(
          "https://id.kick.com/oauth/revoke?" +
            params.toString(),
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },
          }
        ).catch(
          () => undefined
        );
      }

      await deleteSavedKickLogin()
        .catch(
          () => undefined
        );

      kickAccessTokenRef.current =
        "";

      kickRelayGenerationRef.current +=
        1;

      if (
        kickRelayReconnectTimerRef.current !==
        null
      ) {
        window.clearTimeout(
          kickRelayReconnectTimerRef.current
        );

        kickRelayReconnectTimerRef.current =
          null;
      }

      kickRelaySocketRef.current
        ?.close();

      kickRelaySocketRef.current =
        null;

      setKickRelaySocketStatus(
        "idle"
      );

      setKickConnected(
        false
      );

      setHasSavedKickSession(
        false
      );

      setKickUserId(
        ""
      );

      setKickUsername(
        ""
      );

      setKickChannelSlug(
        ""
      );

      setKickAvatar(
        ""
      );

      setAccountNotice(
        ui("Kick-kontoen er koblet fra FyFlade.", "The Kick account was disconnected from FyFlade.")
      );
    } finally {
      setConnectingKick(
        false
      );
    }
  }

  async function openKickChannel() {
    const slug =
      kickChannelSlug ||
      kickUsername;

    if (
      !slug
    ) {
      return;
    }

    try {
      await openUrl(
        `https://kick.com/${encodeURIComponent(
          slug
        )}`
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke åpne Kick-kanalen:",
        error
      );
    }
  }

  async function getKickAppAccessToken() {
    const now = Date.now();

    if (
      kickAppAccessTokenRef.current &&
      kickAppAccessTokenExpiresAtRef.current >
        now + 60_000
    ) {
      return kickAppAccessTokenRef.current;
    }

    const userAccessToken =
      kickAccessTokenRef.current;

    if (!userAccessToken) {
      throw new Error(
        ui("Logg inn på Kick først.", "Sign in to Kick first.")
      );
    }

    const response =
      await fetch(
        `${KICK_RELAY_URL}/kick/app-token`,
        {
          method: "POST",
          headers: {
            Authorization:
              `Bearer ${userAccessToken}`,
            Accept:
              "application/json",
          },
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke hente Kick-apptoken (HTTP ${response.status}).`, `Could not load the Kick app token (HTTP ${response.status}).`)
      );
    }

    const data =
      (await response.json()) as KickTokenResponse;

    if (
      !data.access_token
    ) {
      throw new Error(
        ui("Kick returnerte ikke et apptilgangstoken.", "Kick did not return an app access token.")
      );
    }

    kickAppAccessTokenRef.current =
      data.access_token;

    kickAppAccessTokenExpiresAtRef.current =
      Date.now() +
      Math.max(
        60,
        Number(
          data.expires_in ||
          3600
        )
      ) *
        1000;

    return data.access_token;
  }

  function sanitizeKickChannelInput(
    input: string
  ) {
    let value =
      input.trim();

    value =
      value.replace(
        /^https?:\/\/(www\.)?kick\.com\//i,
        ""
      );

    value =
      value.replace(
        /^kick\.com\//i,
        ""
      );

    value =
      value
        .split("/")[0]
        .split("?")[0]
        .replace(/^@/, "")
        .trim()
        .toLowerCase();

    return value;
  }


  async function getKickBadgeCatalog(
    channelSlug: string
  ): Promise<KickBadgeCatalog | null> {
    const slug =
      sanitizeKickChannelInput(
        channelSlug
      );

    if (!slug) {
      return null;
    }

    const cached =
      kickBadgeCatalogCacheRef.current[
        slug
      ];

    if (
      cached &&
      Date.now() - cached.fetchedAt <
        10 * 60 * 1000
    ) {
      return cached;
    }

    try {
      const response =
        await fetch(
          `https://kick.com/api/v2/channels/${encodeURIComponent(
            slug
          )}`,
          {
            headers: {
              Accept:
                "application/json",
            },
          }
        );

      if (!response.ok) {
        return null;
      }

      const data =
        (await response.json()) as KickWebsiteChannelResponse;

      const catalog:
        KickBadgeCatalog = {
        subscriberBadges:
          Array.isArray(
            data.subscriber_badges
          )
            ? data.subscriber_badges
            : [],
        followerBadges:
          Array.isArray(
            data.follower_badges
          )
            ? data.follower_badges
            : [],
        fetchedAt:
          Date.now(),
      };

      kickBadgeCatalogCacheRef.current[
        slug
      ] = catalog;

      return catalog;
    } catch (
      error
    ) {
      console.warn(
        "Kunne ikke hente KICK badge-katalog:",
        error
      );
      return null;
    }
  }

  function pickKickBadgeImage(
    badges: KickWebsiteBadge[],
    count: number
  ) {
    const usable =
      badges
        .filter(
          (badge) =>
            Boolean(
              badge.badge_image
                ?.src
            )
        )
        .sort(
          (a, b) =>
            Number(
              a.months ||
                0
            ) -
            Number(
              b.months ||
                0
            )
        );

    if (
      usable.length === 0
    ) {
      return "";
    }

    if (
      count <= 0
    ) {
      return (
        usable[0]
          .badge_image?.src ||
        ""
      );
    }

    const matching =
      usable.filter(
        (badge) =>
          Number(
            badge.months ||
              0
          ) <= count
      );

    const chosen =
      matching[
        matching.length - 1
      ] || usable[0];

    return (
      chosen.badge_image
        ?.src || ""
    );
  }

  async function resolveKickWebhookBadges(
    sender: KickWebhookPerson,
    channelSlug: string
  ): Promise<ResolvedBadge[]> {
    const rawBadges =
      sender.identity
        ?.badges || [];

    const needsChannelImages =
      rawBadges.some(
        (badge) => {
          const type =
            (
              badge.type ||
              ""
            ).toLowerCase();

          return (
            type.includes(
              "subscriber"
            ) ||
            type.includes(
              "follower"
            )
          );
        }
      );

    const catalog =
      needsChannelImages
        ? await getKickBadgeCatalog(
            channelSlug
          )
        : null;

    const result:
      ResolvedBadge[] = [];

    if (
      sender.is_verified &&
      !rawBadges.some(
        (badge) =>
          (
            badge.type ||
            ""
          )
            .toLowerCase()
            .includes(
              "verified"
            )
      )
    ) {
      result.push({
        setId:
          "verified",
        id:
          "verified",
        info:
          "Verified",
        imageUrl:
          "",
        title:
          "Verified",
      });
    }

    rawBadges.forEach(
      (
        badge,
        index
      ) => {
        const type =
          (
            badge.type ||
            badge.text ||
            "kick"
          )
            .toLowerCase()
            .replace(
              /[\s-]+/g,
              "_"
            );

        const count =
          Number(
            badge.count ||
              0
          );

        let imageUrl =
          "";

        if (
          type.includes(
            "subscriber"
          )
        ) {
          imageUrl =
            pickKickBadgeImage(
              catalog?.subscriberBadges ||
                [],
              count
            );
        } else if (
          type.includes(
            "follower"
          )
        ) {
          imageUrl =
            pickKickBadgeImage(
              catalog?.followerBadges ||
                [],
              count
            );
        }

        result.push({
          setId:
            type,
          id:
            String(
              badge.count ??
                index
            ),
          info:
            badge.text ||
            (count > 0
              ? String(
                  count
                )
              : ""),
          imageUrl,
          title:
            badge.text ||
            badge.type ||
            "KICK badge",
          count:
            Number.isFinite(
              count
            ) && count > 0
              ? count
              : undefined,
        });
      }
    );

    return result.sort(
      (a, b) =>
        kickBadgeDisplayOrder(
          a
        ) -
        kickBadgeDisplayOrder(
          b
        )
    );
  }

  async function getKickUserById(
    broadcasterUserId: string,
    accessToken: string
  ) {
    try {
      const params =
        new URLSearchParams();

      params.append(
        "id",
        broadcasterUserId
      );

      const response =
        await fetch(
          `https://api.kick.com/public/v1/users?${params.toString()}`,
          {
            headers: {
              Authorization:
                `Bearer ${accessToken}`,
              Accept:
                "application/json",
            },
          }
        );

      if (
        !response.ok
      ) {
        return null;
      }

      const data =
        (await response.json()) as KickUsersResponse;

      return data.data?.[0] ||
        null;
    } catch {
      return null;
    }
  }

  async function resolveKickChannel(
    rawInput: string
  ): Promise<{
    channel: SavedKickChannel;
    isLive: boolean;
  }> {
    const slug =
      sanitizeKickChannelInput(
        rawInput
      );

    if (
      !slug
    ) {
      throw new Error(
        ui("Skriv inn en Kick-kanal eller kick.com/kanalnavn.", "Enter a Kick channel or kick.com/channel-name.")
      );
    }

    const accessToken =
      await getKickAppAccessToken();

    const params =
      new URLSearchParams({
        slug,
      });

    const response =
      await fetch(
        `https://api.kick.com/public/v1/channels?${params.toString()}`,
        {
          headers: {
            Authorization:
              `Bearer ${accessToken}`,
            Accept:
              "application/json",
          },
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke finne Kick-kanalen (HTTP ${response.status}).`, `Could not find the Kick channel (HTTP ${response.status}).`)
      );
    }

    const data =
      (await response.json()) as KickChannelsResponse;

    const item =
      data.data?.[0];

    const broadcasterUserId =
      item?.broadcaster_user_id != null
        ? String(
            item.broadcaster_user_id
          )
        : "";

    if (
      !item ||
      !broadcasterUserId
    ) {
      throw new Error(
        ui(`Fant ikke Kick-kanalen «${slug}».`, `Could not find the Kick channel "${slug}".`)
      );
    }

    const actualSlug =
      (item.slug || slug)
        .toLowerCase();

    const user =
      await getKickUserById(
        broadcasterUserId,
        accessToken
      );

    return {
      channel: {
        broadcasterUserId,
        slug:
          actualSlug,
        name:
          user?.name ||
          user?.username ||
          actualSlug,
        avatarUrl:
          user?.profile_picture ||
          user?.profile_picture_url ||
          "",
      },
      isLive:
        Boolean(
          item.stream?.is_live
        ),
    };
  }

  async function resolveKickChannelById(
    broadcasterUserId: string
  ): Promise<{
    channel: SavedKickChannel;
    isLive: boolean;
  } | null> {
    const cleanId =
      String(
        broadcasterUserId ||
        ""
      ).trim();

    if (!cleanId) {
      return null;
    }

    try {
      const accessToken =
        await getKickAppAccessToken();

      const params =
        new URLSearchParams();

      params.append(
        "broadcaster_user_id",
        cleanId
      );

      const response =
        await fetch(
          `https://api.kick.com/public/v1/channels?${params.toString()}`,
          {
            headers: {
              Authorization:
                `Bearer ${accessToken}`,
              Accept:
                "application/json",
            },
          }
        );

      if (!response.ok) {
        return null;
      }

      const data =
        (await response.json()) as KickChannelsResponse;

      const item =
        data.data?.[0];

      if (!item) {
        return null;
      }

      const user =
        await getKickUserById(
          cleanId,
          accessToken
        );

      const slug =
        (item.slug ||
          user?.channel_slug ||
          user?.slug ||
          cleanId)
          .toLowerCase();

      return {
        channel: {
          broadcasterUserId:
            cleanId,
          slug,
          name:
            user?.name ||
            user?.username ||
            slug,
          avatarUrl:
            user?.profile_picture ||
            user?.profile_picture_url ||
            "",
        },
        isLive:
          Boolean(
            item.stream?.is_live
          ),
      };
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke oppdatere Kick-kanal:",
        error
      );
      return null;
    }
  }

  async function syncKickEventSubscriptions(
    broadcasterUserId: string,
    includeChat: boolean
  ) {
    // Event subscriptions require the signed-in user's OAuth scopes.
    // An app token is only meant for public, server-to-server reads and can
    // appear valid while Kick never delivers chat.message.sent events.
    const accessToken =
      kickAccessTokenRef.current;

    if (!accessToken) {
      throw new Error(
        ui(
          "Logg inn på Kick før chatabonnementene synkroniseres.",
          "Sign in to Kick before synchronizing chat subscriptions."
        )
      );
    }

    const knownEvents = [
      "chat.message.sent",
      "livestream.status.updated",
    ];

    const wantedEvents =
      new Set([
        "livestream.status.updated",
        ...(includeChat
          ? [
              "chat.message.sent",
            ]
          : []),
      ]);

    const numericId =
      Number(
        broadcasterUserId
      );

    if (
      !Number.isFinite(
        numericId
      )
    ) {
      throw new Error(
        ui("Kick-strømmerens bruker-ID er ugyldig.", "The Kick broadcaster user ID is invalid.")
      );
    }

    const subscriptionUrl =
      "https://api.kick.com/public/v1/events/subscriptions";

    const headers = {
      Authorization:
        `Bearer ${accessToken}`,
      Accept:
        "application/json",
    };

    const params =
      new URLSearchParams();

    params.append(
      "broadcaster_user_id",
      broadcasterUserId
    );

    const existingResponse =
      await fetch(
        `${subscriptionUrl}?${params.toString()}`,
        { headers }
      );

    if (
      !existingResponse.ok
    ) {
      const responseDetails =
        (await existingResponse.text())
          .trim()
          .slice(0, 400);

      throw new Error(
        ui(
          `Kick kunne ikke lese kanalabonnementene (HTTP ${existingResponse.status})${responseDetails ? `: ${responseDetails}` : "."}`,
          `Kick could not read the channel subscriptions (HTTP ${existingResponse.status})${responseDetails ? `: ${responseDetails}` : "."}`
        )
      );
    }

    const existing =
      (await existingResponse.json()) as KickEventSubscriptionsResponse;

    const keptEvents =
      new Set<string>();

    const idsToDelete:
      string[] = [];

    for (
      const subscription
      of existing.data || []
    ) {
      const name =
        typeof subscription.event ===
        "string"
          ? subscription.event
          : "";

      if (
        !knownEvents.includes(
          name
        )
      ) {
        continue;
      }

      const shouldKeep =
        wantedEvents.has(
          name
        ) &&
        !keptEvents.has(
          name
        );

      if (
        shouldKeep
      ) {
        keptEvents.add(
          name
        );
      } else if (
        subscription.id
      ) {
        idsToDelete.push(
          subscription.id
        );
      }
    }

    if (
      idsToDelete.length >
      0
    ) {
      const deleteParams =
        new URLSearchParams();

      for (
        const id
        of idsToDelete
      ) {
        deleteParams.append(
          "id",
          id
        );
      }

      const deleteResponse =
        await fetch(
          `${subscriptionUrl}?${deleteParams.toString()}`,
          {
            method:
              "DELETE",
            headers,
          }
        );

      if (
        !deleteResponse.ok
      ) {
        throw new Error(
          ui(`Kick kunne ikke stoppe offline-chatten (HTTP ${deleteResponse.status}).`, `Kick could not stop the offline chat (HTTP ${deleteResponse.status}).`)
        );
      }
    }

    const missing =
      Array.from(
        wantedEvents
      ).filter(
        (name) =>
          !keptEvents.has(
            name
          )
      );

    if (
      missing.length ===
      0
    ) {
      return;
    }

    const response =
      await fetch(
        subscriptionUrl,
        {
          method:
            "POST",
          headers: {
            ...headers,
            "Content-Type":
              "application/json",
          },
          body:
            JSON.stringify({
              broadcaster_user_id:
                numericId,
              method:
                "webhook",
              events:
                missing.map(
                  (name) => ({
                    name,
                    version:
                      1,
                  })
                ),
            }),
        }
      );

    if (
      !response.ok
    ) {
      const responseDetails =
        (await response.text())
          .trim()
          .slice(0, 400);

      const limitReached =
        response.status === 429 ||
        /limit|too many|grense/i.test(
          responseDetails
        );

      throw new Error(
        limitReached
          ? ui(
              `Kick meldte at en API- eller abonnementsgrense er nådd (HTTP ${response.status}).`,
              `Kick reported that an API or subscription limit was reached (HTTP ${response.status}).`
            )
          : ui(
              `Kick kunne ikke oppdatere kanalabonnementene (HTTP ${response.status})${responseDetails ? `: ${responseDetails}` : "."} Kontroller at Webhooks er aktivert og logg inn på Kick på nytt.`,
              `Kick could not update the channel subscriptions (HTTP ${response.status})${responseDetails ? `: ${responseDetails}` : "."} Check that Webhooks are enabled and sign in to Kick again.`
            )
      );
    }
  }

  async function ensureKickEventSubscriptions(
    broadcasterUserId: string
  ) {
    const shouldIncludeChat =
      channelTabsRef.current.some(
        (tab) =>
          tab.kickBroadcasterUserId ===
          broadcasterUserId
      );

    const previous =
      kickSubscriptionSyncQueueRef.current.get(
        broadcasterUserId
      ) ||
      Promise.resolve();

    const next =
      previous
        .catch(
          () =>
            undefined
        )
        .then(
          () =>
            syncKickEventSubscriptions(
              broadcasterUserId,
              shouldIncludeChat
            )
        );

    kickSubscriptionSyncQueueRef.current.set(
      broadcasterUserId,
      next
    );

    try {
      await next;
      setKickSubscriptionHealth({
        status: "ok",
        message: ui(
          "Kick-abonnementene er synkronisert.",
          "Kick subscriptions are synchronized."
        ),
        updatedAt: Date.now(),
      });
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : ui(
              "Kick-abonnementene kunne ikke synkroniseres.",
              "Kick subscriptions could not be synchronized."
            );

      setKickSubscriptionHealth({
        status:
          /HTTP 429|limit|grense/i.test(
            message
          )
            ? "limited"
            : "error",
        message,
        updatedAt: Date.now(),
      });

      throw error;
    } finally {
      if (
        kickSubscriptionSyncQueueRef.current.get(
          broadcasterUserId
        ) ===
        next
      ) {
        kickSubscriptionSyncQueueRef.current.delete(
          broadcasterUserId
        );
      }
    }
  }

  async function repairKickChatReception() {
    const broadcasterIds =
      kickRelayBroadcasterIds();

    if (
      !kickConnected ||
      !kickAccessTokenRef.current
    ) {
      setKickSubscriptionHealth({
        status: "error",
        message: ui(
          "Logg inn på Kick før chatten repareres.",
          "Sign in to Kick before repairing chat."
        ),
        updatedAt: Date.now(),
      });
      return;
    }

    if (broadcasterIds.length === 0) {
      setKickSubscriptionHealth({
        status: "error",
        message: ui(
          "Ingen Kick-kanal med gyldig kanal-ID er lagt til.",
          "No Kick channel with a valid channel ID has been added."
        ),
        updatedAt: Date.now(),
      });
      return;
    }

    setRepairingKickChat(true);

    try {
      for (const broadcasterId of broadcasterIds) {
        await ensureKickEventSubscriptions(
          broadcasterId
        );
      }

      if (
        kickRelaySocketRef.current
          ?.readyState ===
        WebSocket.OPEN
      ) {
        syncKickRelaySubscriptions();
      } else {
        await connectKickRelay(
          kickAccessTokenRef.current
        );
      }

      setKickSubscriptionHealth({
        status: "ok",
        message: ui(
          "Kick-chatten er reparert. Send en ny testmelding i Kick.",
          "Kick chat was repaired. Send a new test message on Kick."
        ),
        updatedAt: Date.now(),
      });
    } catch (error) {
      setKickSubscriptionHealth({
        status: "error",
        message:
          error instanceof Error
            ? error.message
            : ui(
                "Kick-chatten kunne ikke repareres.",
                "Kick chat could not be repaired."
              ),
        updatedAt: Date.now(),
      });
    } finally {
      setRepairingKickChat(false);
    }
  }

  function pemToArrayBuffer(
    pem: string
  ) {
    const base64 =
      pem
        .replace(
          /-----BEGIN PUBLIC KEY-----/g,
          ""
        )
        .replace(
          /-----END PUBLIC KEY-----/g,
          ""
        )
        .replace(
          /\s+/g,
          ""
        );

    const binary =
      atob(
        base64
      );

    const bytes =
      new Uint8Array(
        binary.length
      );

    for (
      let index = 0;
      index <
      binary.length;
      index += 1
    ) {
      bytes[index] =
        binary.charCodeAt(
          index
        );
    }

    return bytes.buffer;
  }

  async function getKickWebhookPublicKey() {
    if (
      kickWebhookPublicKeyRef.current
    ) {
      return kickWebhookPublicKeyRef.current;
    }

    const request =
      async (
        accessToken?: string
      ) =>
        fetch(
          "https://api.kick.com/public/v1/public-key",
          {
            headers:
              accessToken
                ? {
                    Authorization:
                      `Bearer ${accessToken}`,
                    Accept:
                      "application/json",
                  }
                : {
                    Accept:
                      "application/json",
                  },
          }
        );

    let response =
      await request();

    if (
      !response.ok
    ) {
      const accessToken =
        await getKickAppAccessToken();

      response =
        await request(
          accessToken
        );
    }

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke hente den offentlige Kick-webhooknøkkelen (HTTP ${response.status}).`, `Could not load the Kick webhook public key (HTTP ${response.status}).`)
      );
    }

    const data =
      (await response.json()) as {
        data?:
          | {
              public_key?: string;
            }
          | Array<{
              public_key?: string;
            }>;
        public_key?: string;
      };

    const publicKeyPem =
      data.public_key ||
      (Array.isArray(
        data.data
      )
        ? data.data[0]
            ?.public_key
        : data.data
            ?.public_key) ||
      "";

    if (
      !publicKeyPem
    ) {
      throw new Error(
        ui("Svaret for Kick sin offentlige nøkkel manglet public_key.", "The Kick public key response was missing public_key.")
      );
    }

    const key =
      await crypto.subtle.importKey(
        "spki",
        pemToArrayBuffer(
          publicKeyPem
        ),
        {
          name:
            "RSASSA-PKCS1-v1_5",
          hash:
            "SHA-256",
        },
        false,
        [
          "verify",
        ]
      );

    kickWebhookPublicKeyRef.current =
      key;

    return key;
  }

  async function verifyKickWebhookSignature(
    messageId: string,
    timestamp: string,
    signature: string,
    rawBody: string
  ) {
    if (
      !messageId ||
      !timestamp ||
      !signature
    ) {
      return false;
    }

    try {
      const key =
        await getKickWebhookPublicKey();

      const signedPayload =
        `${messageId}.${timestamp}.${rawBody}`;

      const signatureBinary =
        atob(
          signature
        );

      const signatureBytes =
        new Uint8Array(
          signatureBinary.length
        );

      for (
        let index = 0;
        index <
        signatureBinary.length;
        index += 1
      ) {
        signatureBytes[index] =
          signatureBinary.charCodeAt(
            index
          );
      }

      return await crypto.subtle.verify(
        {
          name:
            "RSASSA-PKCS1-v1_5",
        },
        key,
        signatureBytes,
        new TextEncoder().encode(
          signedPayload
        )
      );
    } catch (
      error
    ) {
      console.error(
        "Kick webhook-signatur kunne ikke verifiseres:",
        error
      );
      return false;
    }
  }

  function kickEmoteImageUrl(
    emoteId: string
  ) {
    return `https://files.kick.com/emotes/${encodeURIComponent(
      emoteId
    )}/fullsize`;
  }

  function kickContentToText(
    content: string
  ) {
    return content.replace(
      /\[emote:\d+:([^\]]+)\]/g,
      "$1"
    );
  }

  function kickContentToFragments(
    content: string
  ): TwitchMessageFragment[] {
    const fragments: TwitchMessageFragment[] = [];
    const regex =
      /\[emote:(\d+):([^\]]+)\]/g;

    let lastIndex = 0;
    let match: RegExpExecArray | null;

    while (
      (match = regex.exec(content)) !== null
    ) {
      if (match.index > lastIndex) {
        fragments.push({
          type: "text",
          text: content.slice(
            lastIndex,
            match.index
          ),
        });
      }

      const emoteId =
        match[1] || "";
      const emoteName =
        match[2] || "Kick emote";

      fragments.push({
        type: "kick-emote",
        text: emoteName,
        kickEmote: {
          id: emoteId,
          name: emoteName,
        },
      });

      lastIndex =
        regex.lastIndex;
    }

    if (lastIndex < content.length) {
      fragments.push({
        type: "text",
        text: content.slice(
          lastIndex
        ),
      });
    }

    if (fragments.length === 0) {
      fragments.push({
        type: "text",
        text: content,
      });
    }

    return fragments;
  }

  function kickBadgeLabel(
    badge: ResolvedBadge
  ) {
    const type =
      badge.setId.toLowerCase();

    if (type.includes("moderator")) {
      return "MOD";
    }
    if (type.includes("verified")) {
      return "✓";
    }
    if (type.includes("vip")) {
      return "VIP";
    }
    if (type.includes("og")) {
      return "OG";
    }
    if (
      type.includes("sub_gifter") ||
      type.includes("gifter")
    ) {
      return "GIFT";
    }
    if (type.includes("subscriber")) {
      return "SUB";
    }

    const fallback =
      (badge.title || badge.setId)
        .replace(/[^a-z0-9]/gi, "")
        .slice(0, 4)
        .toUpperCase();

    return fallback || "K";
  }

  function kickBadgeColors(
    badge: ResolvedBadge
  ) {
    const type =
      badge.setId.toLowerCase();

    if (type.includes("moderator")) {
      return {
        background: "#1f6f43",
        color: "#d9ffe8",
      };
    }
    if (type.includes("verified")) {
      return {
        background: "#2b6fc7",
        color: "#ffffff",
      };
    }
    if (type.includes("vip")) {
      return {
        background: "#8b3fa8",
        color: "#ffffff",
      };
    }
    if (type.includes("og")) {
      return {
        background: "#5b5f66",
        color: "#ffffff",
      };
    }
    if (
      type.includes("sub_gifter") ||
      type.includes("gifter")
    ) {
      return {
        background: "#7a5a14",
        color: "#fff2b8",
      };
    }
    if (type.includes("subscriber")) {
      return {
        background: "#315f1e",
        color: "#dcffc8",
      };
    }

    return {
      background: "#34383e",
      color: "#f0f1f2",
    };
  }

  async function processKickViewerFrame(
    channelSlug: string,
    rawFrame: string
  ) {
    if (
      !channelSlug ||
      !rawFrame
    ) {
      return;
    }

    try {
      const frame =
        JSON.parse(
          rawFrame
        ) as KickViewerSocketFrame;

      if (
        !/ChatMessageEvent|chat\.message\.sent/i.test(
          frame.event ||
            ""
        )
      ) {
        return;
      }

      const parsedData =
        typeof frame.data ===
        "string"
          ? JSON.parse(
              frame.data
            )
          : frame.data;

      const data =
        ((parsedData as {
          message?: KickViewerChatMessage;
        } | null)?.message ||
          parsedData) as
          | KickViewerChatMessage
          | undefined;

      const sender =
        data?.sender;

      if (
        !data ||
        !sender
      ) {
        return;
      }

      const cleanSlug =
        channelSlug
          .toLowerCase()
          .trim();

      const matchedTab =
        channelTabsRef.current.find(
          (tab) =>
            (
              tab.kickChannelSlug ||
              (tab.platform ===
              "kick"
                ? tab.login
                : "")
            )
              .toLowerCase() ===
            cleanSlug
        );

      if (!matchedTab) {
        return;
      }

      const broadcasterUserId =
        matchedTab.kickBroadcasterUserId ||
        matchedTab.broadcasterId.replace(
          /^kick:/,
          ""
        );

      const senderId =
        String(
          sender.user_id ??
            sender.id ??
            ""
        );
      const senderName =
        sender.username ||
        sender.slug ||
        "Kick user";
      const senderPerson:
        KickWebhookPerson = {
          user_id:
            senderId,
          username:
            senderName,
          channel_slug:
            sender.channel_slug ||
            sender.slug ||
            senderName.toLowerCase(),
          profile_picture:
            sender.profile_picture ||
            "",
          is_verified:
            sender.is_verified,
          identity:
            sender.identity
              ? {
                  username_color:
                    sender.identity
                      .username_color ||
                    sender.identity
                      .color ||
                    "#53fc18",
                  badges:
                    sender.identity
                      .badges ||
                    [],
                }
              : null,
        };
      const text =
        kickContentToText(
          data.content ||
            ""
        );

      if (!text) {
        return;
      }

      const createdAt =
        Date.parse(
          data.created_at ||
            ""
        );
      const timestampMs =
        Number.isFinite(
          createdAt
        )
          ? createdAt
          : Date.now();
      const nativeMessageId =
        data.message_id ||
        data.id ||
        `${timestampMs}-${senderId}-${text}`;
      const kickBadges =
        await resolveKickWebhookBadges(
          senderPerson,
          cleanSlug
        );
      const chatMessage:
        TwitchChatMessage = {
          id:
            `kick:${nativeMessageId}`,
          kind:
            "chat",
          timestampMs,
          time:
            clockTime(
              timestampMs
            ),
          userId:
            senderId,
          userLogin:
            (
              senderPerson.channel_slug ||
              senderName
            ).toLowerCase(),
          username:
            senderName,
          text,
          color:
            senderPerson.identity
              ?.username_color ||
            "#53fc18",
          badges:
            kickBadges,
          fragments:
            kickContentToFragments(
              data.content ||
                ""
            ),
          reply:
            null,
          platform:
            "kick",
          avatarUrl:
            senderPerson.profile_picture ||
            "",
        };

      let targetTab:
        ChannelTab | undefined;
      let didInsert =
        false;

      updateTabs(
        (tabs) =>
          tabs.map(
            (tab) => {
              const tabSlug =
                (
                  tab.kickChannelSlug ||
                  (tab.platform ===
                  "kick"
                    ? tab.login
                    : "")
                ).toLowerCase();

              if (
                tabSlug !==
                cleanSlug
              ) {
                return tab;
              }

              targetTab =
                tab;

              const existingIndex =
                findAuthoritativeMessageMatch(
                  tab.messages,
                  chatMessage
                );

              if (
                existingIndex >= 0
              ) {
                const existingMessage =
                  tab.messages[
                    existingIndex
                  ];
                const mergedMessage =
                  mergeAuthoritativeMessage(
                    existingMessage,
                    chatMessage
                  );

                if (
                  mergedMessage ===
                  existingMessage
                ) {
                  return tab;
                }

                didInsert =
                  Boolean(
                    existingMessage
                      .optimistic
                  );

                return {
                  ...tab,
                  messages:
                    tab.messages.map(
                      (
                        message,
                        index
                      ) =>
                        index ===
                        existingIndex
                          ? mergedMessage
                          : message
                    ),
                };
              }

              didInsert =
                true;

              return {
                ...tab,
                messages: [
                  ...tab.messages,
                  chatMessage,
                ].sort(
                  (a, b) =>
                    a.timestampMs -
                    b.timestampMs
                ),
              };
            }
          )
      );

      if (
        targetTab &&
        didInsert
      ) {
        const isOwnMessage =
          Boolean(
            senderId &&
            kickUserId &&
            senderId ===
              kickUserId
          );
        const mentionedMe =
          storedMessageMentionsMe(
            chatMessage
          );

        captureMention(
          targetTab,
          chatMessage,
          isOwnMessage
        );

        if (
          mentionedMe &&
          !isOwnMessage &&
          !isMentionSoundMuted(
            targetTab.login,
            targetTab.broadcasterId
          )
        ) {
          playMentionSound();
        }

        saveMessageToDisk(
          broadcasterUserId,
          chatMessage,
          "kick"
        );
      }

      setKickRelayLastMessageAt(
        Date.now()
      );
    } catch (
      error
    ) {
      console.warn(
        "Kick viewer frame:",
        error
      );
    }
  }

  async function processKickWebhookEvent(
    payload: string[]
  ) {
    const [
      eventType = "",
      messageId = "",
      timestamp = "",
      signature = "",
      rawBody = "",
    ] = payload || [];

    if (
      !eventType ||
      !rawBody
    ) {
      return;
    }

    const signatureOk =
      await verifyKickWebhookSignature(
        messageId,
        timestamp,
        signature,
        rawBody
      );

    if (
      !signatureOk
    ) {
      console.warn(
        "Ignorerte Kick webhook med ugyldig signatur."
      );
      return;
    }

    if (
      messageId &&
      processedKickWebhookIdsRef.current.has(
        messageId
      )
    ) {
      return;
    }

    if (messageId) {
      processedKickWebhookIdsRef.current.add(
        messageId
      );

      if (
        processedKickWebhookIdsRef.current.size >
        5000
      ) {
        processedKickWebhookIdsRef.current =
          new Set(
            Array.from(
              processedKickWebhookIdsRef.current
            ).slice(
              -2500
            )
          );
      }
    }

    if (
      eventType ===
      "chat.message.sent"
    ) {
      const data =
        JSON.parse(
          rawBody
        ) as KickChatWebhookPayload;

      const broadcasterUserId =
        data.broadcaster?.user_id !=
        null
          ? String(
              data.broadcaster.user_id
            )
          : "";

      const sender =
        data.sender;

      if (
        !broadcasterUserId ||
        !sender
      ) {
        return;
      }

      const text =
        kickContentToText(
          data.content ||
          ""
        );

      const createdAt =
        Date.parse(
          data.created_at ||
          ""
        );

      const timestampMs =
        Number.isFinite(
          createdAt
        )
          ? createdAt
          : Date.now();

      const senderId =
        sender.user_id != null
          ? String(
              sender.user_id
            )
          : "";

      const senderName =
        sender.username ||
        sender.channel_slug ||
        "Kick user";

      const replySender =
        data.replies_to
          ?.sender;

      const reply:
        | TwitchReplyInfo
        | null =
        data.replies_to
          ?.message_id
          ? {
              parentMessageId:
                data.replies_to.message_id,
              parentMessageBody:
                kickContentToText(
                  data.replies_to.content ||
                  ""
                ),
              parentUserId:
                replySender?.user_id != null
                  ? String(
                      replySender.user_id
                    )
                  : "",
              parentUserName:
                replySender?.username ||
                "",
              parentUserLogin:
                (
                  replySender?.channel_slug ||
                  replySender?.username ||
                  ""
                ).toLowerCase(),
              threadMessageId:
                data.message_id ||
                messageId,
              threadUserId:
                senderId,
              threadUserName:
                senderName,
              threadUserLogin:
                (
                  sender.channel_slug ||
                  senderName
                ).toLowerCase(),
            }
          : null;

      const kickChannelSlugForBadges =
        data.broadcaster
          ?.channel_slug ||
        channelTabsRef.current.find(
          (tab) =>
            tab.kickBroadcasterUserId ===
            broadcasterUserId
        )?.kickChannelSlug ||
        "";

      const kickBadges =
        await resolveKickWebhookBadges(
          sender,
          kickChannelSlugForBadges
        );

      const chatMessage:
        TwitchChatMessage = {
        id:
          `kick:${data.message_id || messageId || `${timestampMs}-${Math.random()}`}`,
        kind:
          "chat",
        timestampMs,
        time:
          clockTime(
            timestampMs
          ),
        userId:
          senderId,
        userLogin:
          (
            sender.channel_slug ||
            senderName
          ).toLowerCase(),
        username:
          senderName,
        text,
        color:
          sender.identity
            ?.username_color ||
          "#53fc18",
        badges:
          kickBadges,
        fragments:
          kickContentToFragments(
            data.content ||
            ""
          ),
        reply,
        platform:
          "kick",
        avatarUrl:
          sender.profile_picture ||
          "",
      };

      let targetTab:
        ChannelTab | undefined;
      let didInsert =
        false;

      updateTabs(
        (tabs) =>
          tabs.map(
            (tab) => {
              if (
                tab.kickBroadcasterUserId !==
                broadcasterUserId
              ) {
                return tab;
              }

              targetTab =
                tab;

              const existingIndex =
                findAuthoritativeMessageMatch(
                  tab.messages,
                  chatMessage
                );

              if (
                existingIndex >= 0
              ) {
                const existingMessage =
                  tab.messages[
                    existingIndex
                  ];
                const mergedMessage =
                  mergeAuthoritativeMessage(
                    existingMessage,
                    chatMessage
                  );

                if (
                  mergedMessage ===
                  existingMessage
                ) {
                  return tab;
                }

                didInsert =
                  Boolean(
                    existingMessage
                      .optimistic
                  );

                return {
                  ...tab,
                  messages:
                    tab.messages.map(
                      (
                        message,
                        index
                      ) =>
                        index ===
                        existingIndex
                          ? mergedMessage
                          : message
                    ),
                };
              }

              didInsert =
                true;

              return {
                ...tab,
                messages: [
                  ...tab.messages,
                  chatMessage,
                ].sort(
                  (a, b) =>
                    a.timestampMs -
                    b.timestampMs
                ),
              };
            }
          )
      );

      if (
        targetTab &&
        didInsert
      ) {
        const isOwnMessage =
          Boolean(
            senderId &&
            kickUserId &&
            senderId === kickUserId
          );
        const mentionedMe =
          storedMessageMentionsMe(
            chatMessage
          );

        captureMention(
          targetTab,
          chatMessage,
          isOwnMessage
        );

        if (
          mentionedMe &&
          !isOwnMessage &&
          !isMentionSoundMuted(
            targetTab.login,
            targetTab.broadcasterId
          )
        ) {
          playMentionSound();
        }

        saveMessageToDisk(
          broadcasterUserId,
          chatMessage,
          "kick"
        );
      }

      return;
    }

    if (
      eventType ===
      "livestream.status.updated"
    ) {
      const data =
        JSON.parse(
          rawBody
        ) as KickLivestreamStatusPayload;

      const broadcasterUserId =
        data.broadcaster?.user_id !=
        null
          ? String(
              data.broadcaster.user_id
            )
          : "";

      if (
        !broadcasterUserId
      ) {
        return;
      }

      const isLive =
        Boolean(
          data.is_live
        );

      updateTabs(
        (tabs) =>
          tabs.map(
            (tab) =>
              tab.kickBroadcasterUserId ===
              broadcasterUserId
                ? {
                    ...tab,
                    kickIsLive:
                      isLive,
                    isLive:
                      tab.platform ===
                      "kick"
                        ? isLive
                        : tab.isLive,
                    status:
                      tab.platform ===
                      "kick"
                        ? isLive
                          ? "live"
                          : "disconnected"
                        : tab.status,
                  }
                : tab
          )
      );

      void ensureKickEventSubscriptions(
        broadcasterUserId
      ).catch(
        (error) =>
          console.warn(
            "Kick event subscription:",
            error
          )
      );
    }
  }

  async function refreshSavedKickChannels() {
    if (
      !kickConnected ||
      !kickWebhookConfigured
    ) {
      return;
    }

    const ids =
      Array.from(
        new Set([
          ...savedKickChannelsRef.current.map(
            (item) =>
              item.broadcasterUserId
          ),
          ...linkedKickChannelsRef.current.map(
            (item) =>
              item.broadcasterUserId
          ),
        ])
      ).filter(
        Boolean
      );

    for (
      const broadcasterUserId
      of ids
    ) {
      const resolved =
        await resolveKickChannelById(
          broadcasterUserId
        );

      if (
        resolved
      ) {
        const {
          channel,
          isLive,
        } = resolved;

        if (
          savedKickChannelsRef.current.some(
            (item) =>
              item.broadcasterUserId ===
              broadcasterUserId
          )
        ) {
          rememberKickChannel(
            channel
          );
        }

        const linked =
          linkedKickChannelsRef.current.find(
            (item) =>
              item.broadcasterUserId ===
              broadcasterUserId
          );

        if (
          linked
        ) {
          saveLinkedKickChannels([
            ...linkedKickChannelsRef.current.filter(
              (item) =>
                item.broadcasterUserId !==
                broadcasterUserId
            ),
            {
              ...channel,
              hostPlatform:
                linked.hostPlatform,
              hostKey:
                linked.hostKey,
            },
          ]);
        }

        updateTabs(
          (tabs) =>
            tabs.map(
              (tab) =>
                tab.kickBroadcasterUserId ===
                broadcasterUserId
                  ? {
                      ...tab,
                      kickChannelSlug:
                        channel.slug,
                      kickIsLive:
                        isLive,
                      profileImageUrl:
                        tab.platform ===
                        "kick"
                          ? channel.avatarUrl ||
                            tab.profileImageUrl
                          : tab.profileImageUrl,
                      displayName:
                        tab.platform ===
                        "kick"
                          ? channel.name
                          : tab.displayName,
                      isLive:
                        tab.platform ===
                        "kick"
                          ? isLive
                          : tab.isLive,
                      status:
                        tab.platform ===
                        "kick"
                          ? isLive
                            ? "live"
                            : "disconnected"
                          : tab.status,
                    }
                  : tab
            )
        );
      }

      void ensureKickEventSubscriptions(
        broadcasterUserId
      ).catch(
        (error) =>
          console.warn(
            "Kick event subscription:",
            error
          )
      );
    }
  }

  async function loadYouTubeClientSecret() {
    if (FYFLADE_YOUTUBE_OAUTH_CLIENT_SECRET) {
      setYoutubeOAuthClientSecret(
        FYFLADE_YOUTUBE_OAUTH_CLIENT_SECRET
      );
      return FYFLADE_YOUTUBE_OAUTH_CLIENT_SECRET;
    }

    if (!import.meta.env.DEV) {
      setYoutubeOAuthClientSecret("");
      return "";
    }

    let secret =
      (await invoke<string | null>(
        "load_youtube_client_secret"
      ).catch(() => null)) || "";
    const legacySecret =
      readYouTubeOAuthClientSecret();

    if (!secret && legacySecret) {
      await invoke(
        "save_youtube_client_secret",
        {
          clientSecret:
            legacySecret,
        }
      );
      secret = legacySecret;
    }

    if (secret) {
      localStorage.removeItem(
        YOUTUBE_OAUTH_CLIENT_SECRET_KEY
      );
    }

    setYoutubeOAuthClientSecret(
      secret
    );

    return secret;
  }

  function saveYouTubeQuotaTracker(
    tracker:
      YouTubeQuotaTracker
  ) {
    setYoutubeQuotaTracker(
      tracker
    );

    localStorage.setItem(
      YOUTUBE_QUOTA_TRACKER_KEY,
      JSON.stringify(
        tracker
      )
    );
  }

  function normalizeYouTubeQuotaDay(
    tracker:
      YouTubeQuotaTracker
  ) {
    const today =
      youtubeQuotaPacificDayKey();

    if (
      tracker.dayKey !==
      today
    ) {
      return emptyYouTubeQuotaTracker();
    }

    return tracker;
  }

  function recordYouTubeQuotaUnits(
    units: number,
    action: string
  ) {
    const safeUnits =
      Math.max(
        0,
        Math.floor(
          Number(
            units
          ) ||
          0
        )
      );

    setYoutubeQuotaTracker(
      (
        current
      ) => {
        const normalized =
          normalizeYouTubeQuotaDay(
            current
          );

        const next:
          YouTubeQuotaTracker = {
          ...normalized,
          usedUnits:
            normalized.usedUnits +
            safeUnits,
          requestCount:
            normalized.requestCount + 1,
          endpointCalls: {
            ...normalized.endpointCalls,
            [action]:
              (normalized.endpointCalls[action] || 0) + 1,
          },
          lastAction:
            action,
          updatedAt:
            Date.now(),
        };

        localStorage.setItem(
          YOUTUBE_QUOTA_TRACKER_KEY,
          JSON.stringify(
            next
          )
        );

        return next;
      }
    );
  }

  function recordYouTubeCacheEvent(
    event: RequestCacheEvent
  ) {
    setYoutubeQuotaTracker((current) => {
      const normalized = normalizeYouTubeQuotaDay(current);
      const next: YouTubeQuotaTracker = {
        ...normalized,
        cacheHits:
          normalized.cacheHits +
          (event === "hit" || event === "stale-hit" ? 1 : 0),
        cacheMisses:
          normalized.cacheMisses + (event === "miss" ? 1 : 0),
        deduplicatedRequests:
          normalized.deduplicatedRequests +
          (event === "deduplicated" ? 1 : 0),
        updatedAt: Date.now(),
      };
      localStorage.setItem(
        YOUTUBE_QUOTA_TRACKER_KEY,
        JSON.stringify(next)
      );
      return next;
    });
  }

  function markYouTubeQuotaExhausted(
    action:
      string
  ) {
    setYoutubeQuotaTracker(
      (
        current
      ) => {
        const normalized =
          normalizeYouTubeQuotaDay(
            current
          );

        const next:
          YouTubeQuotaTracker = {
          ...normalized,
          exhausted:
            true,
          lastAction:
            action,
          updatedAt:
            Date.now(),
        };

        localStorage.setItem(
          YOUTUBE_QUOTA_TRACKER_KEY,
          JSON.stringify(
            next
          )
        );

        return next;
      }
    );
  }

  async function inspectYouTubeQuotaResponse(
    response: Response,
    action: string
  ) {
    if (response.ok) {
      return;
    }

    const isRateLimited =
      response.status === 403 || response.status === 429;

    setYoutubeQuotaTracker((current) => {
      const normalized = normalizeYouTubeQuotaDay(current);
      const next: YouTubeQuotaTracker = {
        ...normalized,
        errorCount: normalized.errorCount + 1,
        rateLimitCount:
          normalized.rateLimitCount + (isRateLimited ? 1 : 0),
        lastError: `${action} · HTTP ${response.status}`,
        updatedAt: Date.now(),
      };

      localStorage.setItem(
        YOUTUBE_QUOTA_TRACKER_KEY,
        JSON.stringify(next)
      );
      return next;
    });

    if (response.status !== 403) {
      return;
    }

    try {
      const raw =
        await response
          .clone()
          .text();

      if (
        /quotaExceeded/i.test(
          raw
        )
      ) {
        markYouTubeQuotaExhausted(
          action
        );
      }
    } catch {
      // Bare fortsett. Selve API-kallet håndterer feilen videre.
    }
  }

  function resetYouTubeQuotaTrackerIfNeeded() {
    const today =
      youtubeQuotaPacificDayKey();

    if (
      youtubeQuotaTracker.dayKey ===
      today
    ) {
      return;
    }

    saveYouTubeQuotaTracker(
      emptyYouTubeQuotaTracker()
    );
  }

