  async function getLoggedInYouTubeChannel(
    accessToken: string
  ):
    Promise<YouTubeChannelProfile> {
    recordYouTubeQuotaUnits(
      1,
      "channels.list · YouTube-konto"
    );

    const response =
      await fetch(
        "https://www.googleapis.com/youtube/v3/channels?part=snippet&mine=true&maxResults=1",
        {
          headers: {
            Authorization:
              `Bearer ${accessToken}`,
          },
        }
      );

    void inspectYouTubeQuotaResponse(
      response,
      "channels.list · YouTube-konto"
    );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke hente YouTube-kanalen (HTTP ${response.status}).`, `Could not load the YouTube channel (HTTP ${response.status}).`)
      );
    }

    const data =
      (
        await response.json()
      ) as YouTubeChannelResponse;

    const channel =
      data.items?.[0];

    if (
      !channel
    ) {
      throw new Error(
        ui("Google-kontoen er godkjent, men ingen YouTube-kanal ble funnet på kontoen.", "The Google account was approved, but no YouTube channel was found on the account.")
      );
    }

    const thumbnails =
      channel.snippet
        ?.thumbnails;

    return {
      id:
        channel.id,

      name:
        channel.snippet
          ?.title ||
        "YouTube",

      handle:
        String(
          channel.snippet
            ?.customUrl ||
          ""
        ).replace(
          /^@/,
          ""
        ),

      avatarUrl:
        thumbnails
          ?.high
          ?.url ||
        thumbnails
          ?.medium
          ?.url ||
        thumbnails
          ?.default
          ?.url ||
        "",
    };
  }

  function applyYouTubeChannel(
    channel: YouTubeChannelProfile,
    accessToken: string
  ) {
    youtubeAccessTokenRef.current =
      accessToken;

    saveYouTubeProfileCache(
      channel
    );

    setYoutubeChannelId(
      channel.id
    );

    setYoutubeChannelName(
      channel.name
    );

    setYoutubeChannelHandle(
      channel.handle
    );

    setYoutubeChannelAvatar(
      channel.avatarUrl
    );

    setYoutubeConnected(
      true
    );

    setYoutubeLoginError(
      ""
    );
  }

  async function exchangeYouTubeAuthorizationCode(
    code: string,
    codeVerifier: string,
    redirectUri: string
  ) {
    const body =
      new URLSearchParams({
        client_id:
          youtubeOAuthClientId,

        code,

        code_verifier:
          codeVerifier,

        grant_type:
          "authorization_code",

        redirect_uri:
          redirectUri,
      });

    if (youtubeOAuthClientSecret) {
      body.set(
        "client_secret",
        youtubeOAuthClientSecret
      );
    }

    const response =
      await fetch(
        "https://oauth2.googleapis.com/token",
        {
          method:
            "POST",

          headers: {
            "Content-Type":
              "application/x-www-form-urlencoded",
          },

          body:
            body.toString(),
        }
      );

    if (
      !response.ok
    ) {
      const raw =
        await response.text();

      let message =
        raw;

      try {
        const parsed =
          JSON.parse(
            raw
          ) as {
            error?: string;
            error_description?: string;
          };

        message =
          parsed.error_description ||
          parsed.error ||
          raw;
      } catch {
        // vanlig tekst
      }

      throw new Error(
        ui(`Google-tokenutvekslingen mislyktes (HTTP ${response.status}).`, `Google token exchange failed (HTTP ${response.status}).`)
      );
    }

    return (
      await response.json()
    ) as YouTubeTokenResponse;
  }

  async function finishYouTubeLogin(
    tokenData: YouTubeTokenResponse
  ) {
    if (
      !tokenData.access_token
    ) {
      throw new Error(
        ui("Google returnerte ikke et tilgangstoken.", "Google did not return an access token.")
      );
    }

    if (
      tokenData.scope &&
      !tokenData.scope
        .split(/\s+/)
        .includes(
          YOUTUBE_OAUTH_SCOPE
        )
    ) {
      throw new Error(
        ui("YouTube-tilgangen ble ikke godkjent. Prøv å logge inn igjen og godkjenn YouTube-tilgangen.", "YouTube access was not approved. Try signing in again and approve YouTube access.")
      );
    }

    if (
      tokenData.refresh_token
    ) {
      await saveYouTubeRefreshToken(
        tokenData.refresh_token
      );
    } else {
      const existing =
        await invoke<
          string | null
        >(
          "load_youtube_refresh_token"
        );

      if (
        !existing
      ) {
        throw new Error(
          ui("Google returnerte ikke et oppdateringstoken. Prøv å logge inn igjen og godkjenn tilgangen på nytt.", "Google did not return a refresh token. Try signing in again and approve access again.")
        );
      }
    }

    let channel:
      YouTubeChannelProfile;

    setHasSavedYouTubeSession(
      true
    );

    try {
      channel =
        await getLoggedInYouTubeChannel(
          tokenData.access_token
        );
    } catch (
      profileError
    ) {
      console.warn(
        "YouTube-kontoen er godkjent, men kanalprofilen kunne ikke hentes:",
        safeDiagnosticError(profileError)
      );

      channel =
        readYouTubeProfileCache() ||
        {
          id:
            "",
          name:
            "YouTube",
          handle:
            "",
          avatarUrl:
            "",
        };
    }

    applyYouTubeChannel(
      channel,
      tokenData.access_token
    );

    setAccountNotice(
      channel.id
        ? ui(`✓ YouTube er koblet til som ${channel.name}.`, `✓ YouTube is connected as ${channel.name}.`)
        : ui("✓ YouTube-kontoen er koblet til. Kanalprofilen hentes når YouTube API-kvoten er tilgjengelig.", "✓ The YouTube account is connected. The channel profile will load when YouTube API quota is available.")
    );

    setShowAddAccount(
      false
    );

  }

  async function connectYouTube() {
    if (
      !youtubeOAuthConfigured
    ) {
      const message = ui(
        "Denne FyFlade-versjonen mangler den offisielle YouTube-innloggingen. Installer en offentlig utgivelse eller konfigurer VITE_YOUTUBE_OAUTH_CLIENT_ID når appen bygges.",
        "This FyFlade build is missing the official YouTube sign-in. Install a public release or configure VITE_YOUTUBE_OAUTH_CLIENT_ID when building the app."
      );

      setYoutubeLoginError(message);
      setAccountNotice(message);

      return;
    }

    setConnectingYoutube(
      true
    );

    setYoutubeLoginError(
      ""
    );

    setAccountNotice(
      ""
    );

    let unlisten:
      | (() => void)
      | null =
      null;

    let timeoutId:
      | number
      | null =
      null;

    try {
      const state =
        randomBase64Url(
          32
        );

      const codeVerifier =
        randomBase64Url(
          64
        );

      const codeChallenge =
        await sha256Base64Url(
          codeVerifier
        );

      const port =
        await invoke<number>(
          "start_youtube_oauth_listener",
          {
            expectedState:
              state,
          }
        );

      const redirectUri =
        `http://127.0.0.1:${port}`;

      let resolveCallback:
        (code: string) => void =
        () => undefined;

      let rejectCallback:
        (error: Error) => void =
        () => undefined;

      const callbackPromise =
        new Promise<string>(
          (
            resolve,
            reject
          ) => {
            resolveCallback =
              resolve;

            rejectCallback =
              reject;
          }
        );

      unlisten =
        await listen<string>(
          "youtube-oauth-result",
          (
            event
          ) => {
            const payload =
              String(
                event.payload ||
                ""
              );

            if (
              payload.startsWith(
                "ok:"
              )
            ) {
              resolveCallback(
                payload.slice(
                  3
                )
              );

              return;
            }

            if (
              payload.startsWith(
                "error:"
              )
            ) {
              rejectCallback(
                new Error(
                  payload.slice(
                    6
                  ) ||
                  ui("YouTube-innloggingen mislyktes.", "YouTube sign-in failed.")
                )
              );
            }
          }
        );

      timeoutId =
        window.setTimeout(
          () => {
            rejectCallback(
              new Error(
                ui("YouTube-innloggingen gikk ut på tid. Prøv igjen.", "YouTube sign-in timed out. Try again.")
              )
            );
          },
          305000
        );

      const params =
        new URLSearchParams({
          client_id:
            youtubeOAuthClientId,

          redirect_uri:
            redirectUri,

          response_type:
            "code",

          scope:
            YOUTUBE_OAUTH_SCOPE,

          code_challenge:
            codeChallenge,

          code_challenge_method:
            "S256",

          state,

          access_type:
            "offline",

          prompt:
            "consent",
        });

      await openUrl(
        "https://accounts.google.com/o/oauth2/v2/auth?" +
          params.toString()
      );

      setAccountNotice(
        ui("Venter på Google/YouTube-godkjenning i nettleseren...", "Waiting for Google/YouTube approval in the browser...")
      );

      const code =
        await callbackPromise;

      const tokenData =
        await exchangeYouTubeAuthorizationCode(
          code,
          codeVerifier,
          redirectUri
        );

      await finishYouTubeLogin(
        tokenData
      );
    } catch (
      error
    ) {
      const message =
        error instanceof
        Error
          ? error.message
          : ui("YouTube-innloggingen mislyktes.", "YouTube sign-in failed.");

      setYoutubeLoginError(
        message
      );

      setAccountNotice(
        message
      );
    } finally {
      if (
        timeoutId !==
        null
      ) {
        window.clearTimeout(
          timeoutId
        );
      }

      unlisten?.();

      setConnectingYoutube(
        false
      );
    }
  }

  async function restoreYouTubeLogin() {
    const clientId =
      readYouTubeOAuthClientId();

    const clientSecret =
      await loadYouTubeClientSecret();

    if (
      !isValidYouTubeOAuthClientId(
        clientId
      )
    ) {
      return;
    }

    try {
      const refreshToken =
        await invoke<
          string | null
        >(
          "load_youtube_refresh_token"
        );

      if (
        !refreshToken
      ) {
        setHasSavedYouTubeSession(
          false
        );
        return;
      }

      setHasSavedYouTubeSession(
        true
      );

      setConnectingYoutube(
        true
      );

      const body =
        new URLSearchParams({
          client_id:
            clientId,

          refresh_token:
            refreshToken,

          grant_type:
            "refresh_token",
        });

      if (clientSecret) {
        body.set(
          "client_secret",
          clientSecret
        );
      }

      const response =
        await fetch(
          "https://oauth2.googleapis.com/token",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },

            body:
              body.toString(),
          }
        );

      if (
        !response.ok
      ) {
        throw new Error(
          response.status === 400 ||
          response.status === 401
            ? ui("YouTube-innloggingen er utløpt. Logg inn på nytt fra Kontoer.", "YouTube sign-in has expired. Sign in again from Accounts.")
            : ui("YouTube kunne ikke kobles til akkurat nå. FyFlade prøver igjen når nettet er tilbake.", "YouTube could not connect right now. FyFlade will retry when the network returns.")
        );
      }

      const tokenData =
        (
          await response.json()
        ) as YouTubeTokenResponse;

      let channel:
        YouTubeChannelProfile;

      try {
        channel =
          await getLoggedInYouTubeChannel(
            tokenData.access_token
          );
      } catch (
        profileError
      ) {
        console.warn(
          "YouTube access token er gyldig, men kanalprofilen kunne ikke hentes (for eksempel quotaExceeded):",
          safeDiagnosticError(profileError)
        );

        channel =
          readYouTubeProfileCache() ||
          {
            id:
              "",
            name:
              "YouTube",
            handle:
              "",
            avatarUrl:
              "",
          };
      }

      applyYouTubeChannel(
        channel,
        tokenData.access_token
      );
    } catch (
      error
    ) {
      console.error(
        "YouTube auto-login feilet:",
        safeDiagnosticError(error)
      );

      setYoutubeConnected(
        false
      );

      youtubeAccessTokenRef.current =
        "";

      setYoutubeLoginError(
        readableErrorMessage(
          error,
          ui("YouTube kunne ikke kobles til akkurat nå.", "YouTube could not connect right now.")
        )
      );
    } finally {
      setConnectingYoutube(
        false
      );
    }
  }

  async function disconnectYouTube() {
    setConnectingYoutube(
      true
    );

    setYoutubeLoginError(
      ""
    );

    try {
      const accessToken =
        youtubeAccessTokenRef.current;

      if (
        accessToken
      ) {
        const body =
          new URLSearchParams({
            token:
              accessToken,
          });

        await fetch(
          "https://oauth2.googleapis.com/revoke",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },

            body:
              body.toString(),
          }
        ).catch(
          () => undefined
        );
      }

      await deleteSavedYouTubeLogin()
        .catch(
          () => undefined
        );

      stopAllYouTubeChatPolls();

      youtubeAccessTokenRef.current =
        "";

      updateTabs(
        (
          tabs
        ) =>
          tabs.map(
            (
              tab
            ) =>
              tab.platform ===
                "youtube"
                ? {
                    ...tab,

                    status:
                      "disconnected",

                    isLive:
                      false,

                    error:
                      "YouTube-kontoen er koblet fra.",
                  }
                : tab
          )
      );

      setYoutubeConnected(
        false
      );

      setHasSavedYouTubeSession(
        false
      );

      setYoutubeChannelId(
        ""
      );

      setYoutubeChannelName(
        ""
      );

      setYoutubeChannelHandle(
        ""
      );

      setYoutubeChannelAvatar(
        ""
      );

      setAccountNotice(
        ui("YouTube-kontoen er koblet fra FyFlade.", "The YouTube account was disconnected from FyFlade.")
      );
    } finally {
      setConnectingYoutube(
        false
      );
    }
  }

  async function openYouTubeChannel() {
    if (
      !youtubeChannelId
    ) {
      return;
    }

    try {
      await openUrl(
        `https://www.youtube.com/channel/${encodeURIComponent(
          youtubeChannelId
        )}`
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke åpne YouTube-kanalen:",
        error
      );
    }
  }

  function extractYouTubeVideoId(
    input: string
  ) {
    const value =
      input.trim();

    if (
      !value
    ) {
      return "";
    }

    if (
      /^[A-Za-z0-9_-]{11}$/.test(
        value
      )
    ) {
      return value;
    }

    try {
      const normalized =
        /^https?:\/\//i.test(
          value
        )
          ? value
          : `https://${value}`;

      const url =
        new URL(
          normalized
        );

      const host =
        url.hostname
          .toLowerCase()
          .replace(
            /^www\./,
            ""
          );

      if (
        host ===
        "youtu.be"
      ) {
        return (
          url.pathname
            .split(
              "/"
            )
            .filter(
              Boolean
            )[0] ||
          ""
        );
      }

      if (
        host ===
          "youtube.com" ||
        host.endsWith(
          ".youtube.com"
        )
      ) {
        const fromQuery =
          url.searchParams.get(
            "v"
          );

        if (
          fromQuery
        ) {
          return fromQuery;
        }

        const parts =
          url.pathname
            .split(
              "/"
            )
            .filter(
              Boolean
            );

        if (
          (
            parts[0] ===
              "live" ||
            parts[0] ===
              "shorts" ||
            parts[0] ===
              "embed"
          ) &&
          parts[1]
        ) {
          return parts[1];
        }
      }
    } catch {
      // Ikke en URL.
    }

    return "";
  }

  function extractYouTubeChannelHint(
    input: string
  ):
    | {
        kind:
          | "id"
          | "handle";
        value: string;
      }
    | null {
    const value =
      input.trim();

    if (
      !value
    ) {
      return null;
    }

    if (
      /^UC[A-Za-z0-9_-]{22}$/.test(
        value
      )
    ) {
      return {
        kind:
          "id",
        value,
      };
    }

    if (
      value.startsWith(
        "@"
      ) &&
      value.length >
        1
    ) {
      return {
        kind:
          "handle",
        value,
      };
    }

    try {
      const normalized =
        /^https?:\/\//i.test(
          value
        )
          ? value
          : `https://${value}`;

      const url =
        new URL(
          normalized
        );

      const host =
        url.hostname
          .toLowerCase()
          .replace(
            /^www\./,
            ""
          );

      if (
        host ===
          "youtube.com" ||
        host.endsWith(
          ".youtube.com"
        )
      ) {
        const parts =
          url.pathname
            .split(
              "/"
            )
            .filter(
              Boolean
            );

        if (
          parts[0] ===
            "channel" &&
          /^UC[A-Za-z0-9_-]{22}$/.test(
            parts[1] ||
              ""
          )
        ) {
          return {
            kind:
              "id",
            value:
              parts[1],
          };
        }

        if (
          parts[0]
            ?.startsWith(
              "@"
            )
        ) {
          return {
            kind:
              "handle",
            value:
              parts[0],
          };
        }
      }
    } catch {
      // Ikke en kanal-URL.
    }

    return null;
  }

  async function youtubeApiRequest(
    url: string
  ) {
    const endpoint = (() => {
      try {
        const resource =
          new URL(url).pathname.split("/").filter(Boolean).pop() || "list";
        return `${resource}.list`;
      } catch {
        return "YouTube Data API · list";
      }
    })();

    let accessToken =
      youtubeAccessTokenRef.current;

    if (
      !accessToken
    ) {
      accessToken =
        await refreshYouTubeAccessToken();
    }

    const request =
      async (
        token:
          string
      ) => {
        recordYouTubeQuotaUnits(
          1,
          endpoint
        );

        const response =
          await fetch(
            url,
            {
              headers: {
                Authorization:
                  `Bearer ${token}`,
              },
            }
          );

        void inspectYouTubeQuotaResponse(
          response,
          endpoint
        );

        return response;
      };

    let response =
      await request(
        accessToken
      );

    if (
      response.status ===
      401
    ) {
      accessToken =
        await refreshYouTubeAccessToken();

      response =
        await request(
          accessToken
        );
    }

    return response;
  }

  async function fetchYouTubeChannelRecord(
    hint: {
      kind:
        | "id"
        | "handle";
      value: string;
    }
  ):
    Promise<
      SavedYouTubeChannel
    > {
    const params =
      new URLSearchParams({
        part:
          "snippet,contentDetails",
      });

    if (
      hint.kind ===
      "id"
    ) {
      params.set(
        "id",
        hint.value
      );
    } else {
      params.set(
        "forHandle",
        hint.value
      );
    }

    const response =
      await youtubeApiRequest(
        "https://www.googleapis.com/youtube/v3/channels?" +
          params.toString()
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke hente YouTube-kanalen (HTTP ${response.status}).`, `Could not load the YouTube channel (HTTP ${response.status}).`)
      );
    }

    const data =
      (
        await response.json()
      ) as YouTubeChannelResponse;

    const channel =
      data.items?.[0];

    if (
      !channel
    ) {
      throw new Error(
        ui("Fant ikke YouTube-kanalen. Prøv @handle eller en /channel/UC...-URL.", "Could not find the YouTube channel. Try an @handle or a /channel/UC... URL.")
      );
    }

    const uploadsPlaylistId =
      channel.contentDetails
        ?.relatedPlaylists
        ?.uploads ||
      "";

    if (
      !uploadsPlaylistId
    ) {
      throw new Error(
        ui("Fant kanalen, men YouTube returnerte ingen opplastingsspilleliste.", "The channel was found, but YouTube returned no uploads playlist.")
      );
    }

    return {
      channelId:
        channel.id,

      name:
        channel.snippet
          ?.title ||
        "YouTube",

      avatarUrl:
        channel.snippet
          ?.thumbnails
          ?.high
          ?.url ||
        channel.snippet
          ?.thumbnails
          ?.medium
          ?.url ||
        channel.snippet
          ?.thumbnails
          ?.default
          ?.url ||
        "",

      uploadsPlaylistId,
    };
  }

  async function getYouTubeChannelRecord(
    hint: {
      kind: "id" | "handle";
      value: string;
    }
  ): Promise<SavedYouTubeChannel> {
    const key = `youtube-channel:${hint.kind}:${hint.value.trim().toLowerCase()}`;
    const value = await youtubeMetadataCacheRef.current.getOrLoad(
      key,
      () => fetchYouTubeChannelRecord(hint),
      {
        ttlMs: 6 * 60 * 60 * 1000,
        staleWhileRevalidateMs: 18 * 60 * 60 * 1000,
      },
      recordYouTubeCacheEvent
    );
    return value as SavedYouTubeChannel;
  }

  async function fetchYouTubeVideoRecord(
    videoId: string
  ) {
    const params =
      new URLSearchParams({
        part:
          "snippet,liveStreamingDetails",
        id:
          videoId,
      });

    const response =
      await youtubeApiRequest(
        "https://www.googleapis.com/youtube/v3/videos?" +
          params.toString()
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke hente YouTube-videoen (HTTP ${response.status}).`, `Could not load the YouTube video (HTTP ${response.status}).`)
      );
    }

    const data =
      (
        await response.json()
      ) as YouTubeVideoResponse;

    return data.items?.[0] ||
      null;
  }

  async function getYouTubeVideoRecord(
    videoId: string
  ): Promise<YouTubeVideoRecord | null> {
    const value = await youtubeMetadataCacheRef.current.getOrLoad(
      `youtube-video:${videoId.trim()}`,
      () => fetchYouTubeVideoRecord(videoId),
      {
        ttlMs: 30 * 1000,
        negativeTtlMs: 2 * 60 * 1000,
        staleWhileRevalidateMs: 30 * 1000,
        isNegative: (record) => record === null,
      },
      recordYouTubeCacheEvent
    );
    return value as YouTubeVideoRecord | null;
  }

  async function findActiveYouTubeLive(
    channel:
      SavedYouTubeChannel
  ):
    Promise<YouTubeLiveDiscoveryResult> {
    const playlistParams =
      new URLSearchParams({
        part:
          "contentDetails",
        playlistId:
          channel.uploadsPlaylistId,
        maxResults:
          "10",
      });

    const playlistResponse =
      await youtubeApiRequest(
        "https://www.googleapis.com/youtube/v3/playlistItems?" +
          playlistParams.toString()
      );

    if (
      !playlistResponse.ok
    ) {
      throw new Error(
        ui(`Kunne ikke sjekke YouTube-kanalen (HTTP ${playlistResponse.status}).`, `Could not check the YouTube channel (HTTP ${playlistResponse.status}).`)
      );
    }

    const playlistData =
      (
        await playlistResponse.json()
      ) as YouTubePlaylistItemsResponse;

    const videoIds =
      (
        playlistData.items ||
        []
      )
        .map(
          (
            item
          ) =>
            item.contentDetails
              ?.videoId ||
            ""
        )
        .filter(
          Boolean
        );

    if (
      videoIds.length ===
      0
    ) {
      return null;
    }

    const videoParams =
      new URLSearchParams({
        part:
          "snippet,liveStreamingDetails",
        id:
          videoIds.join(
            ","
          ),
      });

    const videoResponse =
      await youtubeApiRequest(
        "https://www.googleapis.com/youtube/v3/videos?" +
          videoParams.toString()
      );

    if (
      !videoResponse.ok
    ) {
      throw new Error(
        ui(`Kunne ikke sjekke YouTube-direktesendingen (HTTP ${videoResponse.status}).`, `Could not check the YouTube live stream (HTTP ${videoResponse.status}).`)
      );
    }

    const videoData =
      (
        await videoResponse.json()
      ) as YouTubeVideoResponse;

    const liveVideo =
      (
        videoData.items ||
        []
      ).find(
        (
          video
        ) =>
          video.snippet
            ?.liveBroadcastContent ===
            "live" &&
          Boolean(
            video.liveStreamingDetails
              ?.activeLiveChatId
          )
      );

    if (
      !liveVideo ||
      !liveVideo.liveStreamingDetails
        ?.activeLiveChatId
    ) {
      return null;
    }

    return {
      videoId:
        liveVideo.id,

      liveChatId:
        liveVideo.liveStreamingDetails
          .activeLiveChatId,
    };
  }

  async function findActiveYouTubeLiveCached(
    channel: SavedYouTubeChannel
  ): Promise<YouTubeLiveDiscoveryResult> {
    const cacheKey =
      channel.channelId || channel.uploadsPlaylistId;
    const now = Date.now();
    if (youtubeLiveDiscoveryCacheRef.current.size > 300) {
      const oldest = Array.from(youtubeLiveDiscoveryCacheRef.current.entries())
        .sort((left, right) => left[1].checkedAt - right[1].checkedAt)
        .slice(0, youtubeLiveDiscoveryCacheRef.current.size - 200);
      oldest.forEach(([key]) => youtubeLiveDiscoveryCacheRef.current.delete(key));
    }
    const cached =
      youtubeLiveDiscoveryCacheRef.current.get(cacheKey);

    if (cached && now < cached.nextCheckAt) {
      recordYouTubeCacheEvent("hit");
      return cached.live;
    }

    const inFlight =
      youtubeLiveDiscoveryInFlightRef.current.get(cacheKey);

    if (inFlight) {
      recordYouTubeCacheEvent("deduplicated");
      return inFlight;
    }

    recordYouTubeCacheEvent("miss");

    const request =
      findActiveYouTubeLive(channel)
        .then((live) => {
          const previousOfflineStreak =
            cached?.offlineStreak || 0;
          const offlineStreak = live
            ? 0
            : Math.min(previousOfflineStreak + 1, 6);
          const offlineDelay = Math.min(
            YOUTUBE_LIVE_CHECK_OFFLINE_MAX_MS,
            YOUTUBE_LIVE_CHECK_OFFLINE_BASE_MS *
              Math.max(1, 2 ** Math.max(0, offlineStreak - 1))
          );

          youtubeLiveDiscoveryCacheRef.current.set(cacheKey, {
            live,
            checkedAt: Date.now(),
            nextCheckAt:
              Date.now() +
              (live
                ? YOUTUBE_LIVE_CHECK_SCHEDULER_MS
                : offlineDelay),
            offlineStreak,
          });

          return live;
        })
        .catch((error) => {
          youtubeLiveDiscoveryCacheRef.current.set(cacheKey, {
            live: cached?.live || null,
            checkedAt: Date.now(),
            nextCheckAt:
              Date.now() + YOUTUBE_LIVE_CHECK_ERROR_RETRY_MS,
            offlineStreak: cached?.offlineStreak || 0,
          });
          throw error;
        })
        .finally(() => {
          youtubeLiveDiscoveryInFlightRef.current.delete(cacheKey);
        });

    youtubeLiveDiscoveryInFlightRef.current.set(cacheKey, request);
    return request;
  }

  function isYouTubeLiveDiscoveryDeferred(
    channel: SavedYouTubeChannel
  ) {
    const cacheKey =
      channel.channelId || channel.uploadsPlaylistId;
    const cached =
      youtubeLiveDiscoveryCacheRef.current.get(cacheKey);

    return Boolean(
      cached && Date.now() < cached.nextCheckAt
    );
  }

  async function resolveYouTubeChannelInput(
    input: string
  ):
    Promise<{
      channel:
        SavedYouTubeChannel;
      live:
        | {
            videoId: string;
            liveChatId: string;
          }
        | null;
    }> {
    const channelHint =
      extractYouTubeChannelHint(
        input
      );

    if (
      channelHint
    ) {
      const channel =
        await getYouTubeChannelRecord(
          channelHint
        );

      return {
        channel,
        live:
          await findActiveYouTubeLive(
            channel
          ),
      };
    }

    const videoId =
      extractYouTubeVideoId(
        input
      );

    if (
      videoId
    ) {
      const video =
        await getYouTubeVideoRecord(
          videoId
        );

      const channelId =
        video?.snippet
          ?.channelId ||
        "";

      if (
        video &&
        channelId
      ) {
        const channel =
          await getYouTubeChannelRecord({
            kind:
              "id",
            value:
              channelId,
          });

        const liveChatId =
          video.snippet
            ?.liveBroadcastContent ===
            "live"
            ? video.liveStreamingDetails
                ?.activeLiveChatId ||
              ""
            : "";

        return {
          channel,
          live:
            liveChatId
              ? {
                  videoId:
                    video.id,
                  liveChatId,
                }
              : await findActiveYouTubeLive(
                  channel
                ),
        };
      }
    }

    const plainHandle =
      input
        .trim()
        .replace(
          /^@/,
          ""
        );

    if (
      /^[A-Za-z0-9._-]{3,30}$/.test(
        plainHandle
      )
    ) {
      const channel =
        await getYouTubeChannelRecord({
          kind:
            "handle",
          value:
            `@${plainHandle}`,
        });

      return {
        channel,
        live:
          await findActiveYouTubeLive(
            channel
          ),
      };
    }

    throw new Error(
      ui("Lim inn @handle, YouTube-kanal-URL, kanal-ID eller en video-/direktesendings-URL.", "Paste an @handle, YouTube channel URL, channel ID or a video/live URL.")
    );
  }

  async function refreshSavedYouTubeLiveStatuses() {
    if (
      !youtubeConnected
    ) {
      return;
    }

    // Egne YouTube-faner.
    for (
      const channel
      of savedYouTubeChannelsRef.current
    ) {
      // Ikke opprett/sjekk en separat YouTube-fane hvis kanalen
      // allerede er koblet inn i en Twitch-fane.
      if (
        linkedYouTubeChannelsRef.current.some(
          (
            linked
          ) =>
            linked.channelId ===
            channel.channelId
        )
      ) {
        continue;
      }

      const tabId =
        `youtube-channel:${channel.channelId}`;

      const currentTab =
        channelTabsRef.current
          .find(
            (
              tab
            ) =>
              tab.broadcasterId ===
              tabId
          );

      if (
        currentTab
          ?.isLive &&
        currentTab
          ?.youtubeLiveChatId
      ) {
        continue;
      }

      if (isYouTubeLiveDiscoveryDeferred(channel)) {
        continue;
      }

      try {
        const live =
          await findActiveYouTubeLiveCached(
            channel
          );

        if (
          live
        ) {
          updateTabs(
            (
              tabs
            ) =>
              tabs.map(
                (
                  tab
                ) =>
                  tab.broadcasterId ===
                  tabId
                    ? {
                        ...tab,
                        isLive:
                          true,
                        status:
                          "joining",
                        error:
                          "",
                        youtubeVideoId:
                          live.videoId,
                        youtubeLiveChatId:
                          live.liveChatId,
                        youtubeIsLive:
                          true,
                      }
                    : tab
              )
          );

          startYouTubeChatPoll(
            tabId,
            live.liveChatId
          );
        } else {
          updateTabs(
            (
              tabs
            ) =>
              tabs.map(
                (
                  tab
                ) =>
                  tab.broadcasterId ===
                  tabId
                    ? {
                        ...tab,
                        isLive:
                          false,
                        status:
                          "disconnected",
                        error:
                          "",
                        youtubeVideoId:
                          undefined,
                        youtubeLiveChatId:
                          undefined,
                        youtubeIsLive:
                          false,
                      }
                    : tab
              )
          );
        }
      } catch (
        error
      ) {
        console.error(
          `Kunne ikke sjekke YouTube-kanalen ${channel.name}:`,
          error
        );
      }
    }

    // YouTube-kilder som er koblet inn i en Twitch-fane.
    for (
      const linked
      of linkedYouTubeChannelsRef.current
    ) {
      const currentTab =
        channelTabsRef.current
          .find(
            (
              tab
            ) =>
              tab.platform !==
                "youtube" &&
              tab.login ===
                linked.twitchLogin
          );

      // Vent til den cachede Twitch-fanen er løst til ekte broadcaster-id.
      if (
        !currentTab ||
        currentTab.broadcasterId
          .startsWith(
            "cached:"
          )
      ) {
        continue;
      }

      if (
        currentTab.youtubeIsLive &&
        currentTab.youtubeLiveChatId
      ) {
        continue;
      }

      if (isYouTubeLiveDiscoveryDeferred(linked)) {
        continue;
      }

      try {
        const live =
          await findActiveYouTubeLiveCached(
            linked
          );

        if (
          live
        ) {
          updateTabs(
            (
              tabs
            ) =>
              tabs.map(
                (
                  tab
                ) =>
                  tab.broadcasterId ===
                  currentTab.broadcasterId
                    ? {
                        ...tab,
                        youtubeChannelId:
                          linked.channelId,
                        youtubeUploadsPlaylistId:
                          linked.uploadsPlaylistId,
                        youtubeVideoId:
                          live.videoId,
                        youtubeLiveChatId:
                          live.liveChatId,
                        youtubeIsLive:
                          true,
                      }
                    : tab
              )
          );

          startYouTubeChatPoll(
            currentTab.broadcasterId,
            live.liveChatId
          );
        } else {
          updateTabs(
            (
              tabs
            ) =>
              tabs.map(
                (
                  tab
                ) =>
                  tab.broadcasterId ===
                  currentTab.broadcasterId
                    ? {
                        ...tab,
                        youtubeChannelId:
                          linked.channelId,
                        youtubeUploadsPlaylistId:
                          linked.uploadsPlaylistId,
                        youtubeVideoId:
                          undefined,
                        youtubeLiveChatId:
                          undefined,
                        youtubeIsLive:
                          false,
                      }
                    : tab
              )
          );
        }
      } catch (
        error
      ) {
        console.error(
          `Kunne ikke sjekke koblet YouTube-kanal ${linked.name}:`,
          error
        );
      }
    }
  }

  async function refreshYouTubeAccessToken() {
    const clientId =
      readYouTubeOAuthClientId();

    const clientSecret =
      await loadYouTubeClientSecret();

    const refreshToken =
      await invoke<
        string | null
      >(
        "load_youtube_refresh_token"
      );

    if (
      !clientId ||
      !refreshToken
    ) {
      throw new Error(
        ui("YouTube-innloggingen mangler. Logg inn på nytt fra Kontoer.", "YouTube sign-in is missing. Sign in again from Accounts.")
      );
    }

    const body =
      new URLSearchParams({
        client_id:
          clientId,

        refresh_token:
          refreshToken,

        grant_type:
          "refresh_token",
      });

    if (clientSecret) {
      body.set(
        "client_secret",
        clientSecret
      );
    }

    const response =
      await fetch(
        "https://oauth2.googleapis.com/token",
        {
          method:
            "POST",

          headers: {
            "Content-Type":
              "application/x-www-form-urlencoded",
          },

          body:
            body.toString(),
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke fornye YouTube-tilkoblingen (HTTP ${response.status}).`, `Could not renew the YouTube connection (HTTP ${response.status}).`)
      );
    }

    const tokenData =
      (
        await response.json()
      ) as YouTubeTokenResponse;

    if (
      !tokenData.access_token
    ) {
      throw new Error(
        ui("Google returnerte ikke et nytt tilgangstoken.", "Google did not return a new access token.")
      );
    }

    youtubeAccessTokenRef.current =
      tokenData.access_token;

    return tokenData.access_token;
  }

  function updateYouTubeStreamHealth(
    tabId: string,
    generation: number,
    state: ConnectionHealthState | null
  ) {
    setYoutubeStreamHealthByTab((current) => {
      if (youtubeChatPollGenerationRef.current[tabId] !== generation) {
        return current;
      }
      if (state === null) {
        if (!current[tabId]) return current;
        const next = { ...current };
        delete next[tabId];
        return next;
      }
      if (current[tabId]?.generation === generation && current[tabId]?.state === state) {
        return current;
      }
      return { ...current, [tabId]: { generation, state } };
    });
  }

  function stopYouTubeChatPoll(
    tabId: string
  ) {
    const timer =
      youtubeChatReconnectTimersRef
        .current[
          tabId
        ];

    if (
      timer !==
      undefined
    ) {
      window.clearTimeout(
        timer
      );

      delete youtubeChatReconnectTimersRef
        .current[
          tabId
        ];
    }

    youtubeChatPollGenerationRef
      .current[
        tabId
      ] =
      (
        youtubeChatPollGenerationRef
          .current[
            tabId
          ] ||
        0
      ) +
      1;

    updateYouTubeStreamHealth(
      tabId,
      youtubeChatPollGenerationRef.current[tabId],
      null
    );

    void invoke(
      "stop_youtube_chat_stream",
      {
        tabId,
      }
    ).catch(
      (
        error
      ) =>
        console.warn(
          "Kunne ikke stoppe YouTube stream:",
          error
        )
    );
  }

  function stopAllYouTubeChatPolls() {
    setYoutubeStreamHealthByTab({});
    for (
      const timer
      of Object.values(
        youtubeChatReconnectTimersRef
          .current
      )
    ) {
      window.clearTimeout(
        timer
      );
    }

    youtubeChatReconnectTimersRef.current =
      {};

    for (
      const tab
      of channelTabsRef.current
    ) {
      if (
        tab.platform ===
          "youtube" ||
        tab.youtubeChannelId
      ) {
        youtubeChatPollGenerationRef
          .current[
            tab.broadcasterId
          ] =
          (
            youtubeChatPollGenerationRef
              .current[
                tab.broadcasterId
              ] ||
            0
          ) +
          1;

        void invoke(
          "stop_youtube_chat_stream",
          {
            tabId:
              tab.broadcasterId,
          }
        ).catch(
          () => undefined
        );
      }
    }
  }

  function youtubeAuthorColor(
    author:
      YouTubeLiveChatMessageApi["authorDetails"]
  ) {
    if (
      author?.isChatOwner
    ) {
      return "#ffd166";
    }

    if (
      author?.isChatModerator
    ) {
      return "#5ab4ff";
    }

    if (
      author?.isChatSponsor
    ) {
      return "#67d17a";
    }

    return "#ff6b6b";
  }

  function youtubeMessageToChatMessage(
    item:
      YouTubeLiveChatMessageApi
  ):
    TwitchChatMessage | null {
    const id =
      String(
        item.id ||
        ""
      );

    const username =
      String(
        item.authorDetails
          ?.displayName ||
        "YouTube"
      );

    const eventType =
      String(
        item.snippet?.type ||
        "textMessageEvent"
      );

    let text =
      String(
        item.snippet
          ?.displayMessage ||
        item.snippet
          ?.textMessageDetails
          ?.messageText ||
          ""
      ).trim();
    let mentionText = text;

    if (
      eventType ===
      "superChatEvent"
    ) {
      const amount =
        item.snippet
          ?.superChatDetails
          ?.amountDisplayString ||
        "Super Chat";
      const comment =
        item.snippet
          ?.superChatDetails
          ?.userComment ||
        "";

      mentionText = String(comment).trim();
      text = `💰 ${amount}${comment ? ` · ${comment}` : ""}`;
    } else if (
      eventType ===
      "superStickerEvent"
    ) {
      mentionText = "";
      const amount =
        item.snippet
          ?.superStickerDetails
          ?.amountDisplayString ||
        "";

      text = `💎 Super Sticker${amount ? ` · ${amount}` : ""}`;
    } else if (
      eventType ===
      "newSponsorEvent"
    ) {
      mentionText = "";
      text = ui(
        `⭐ ${username} ble medlem`,
        `⭐ ${username} became a member`
      );
    } else if (
      eventType ===
      "memberMilestoneChatEvent"
    ) {
      text = `⭐ ${text || ui("Medlemsmilepæl", "Membership milestone")}`;
    } else if (
      eventType ===
      "membershipGiftingEvent"
    ) {
      mentionText = "";
      const count =
        item.snippet
          ?.membershipGiftingDetails
          ?.giftMembershipsCount ||
        0;

      text = ui(
        `🎁 ${username} ga ${count || "flere"} medlemskap`,
        `🎁 ${username} gifted ${count || "multiple"} memberships`
      );
    } else if (
      eventType ===
      "giftMembershipReceivedEvent"
    ) {
      mentionText = "";
      const level =
        item.snippet
          ?.giftMembershipReceivedDetails
          ?.memberLevelName ||
        "";

      text = ui(
        `🎁 ${username} mottok et medlemskap${level ? ` · ${level}` : ""}`,
        `🎁 ${username} received a membership${level ? ` · ${level}` : ""}`
      );
    }

    if (
      !id ||
      !text
    ) {
      return null;
    }

    const parsedTimestamp =
      Date.parse(
        String(
          item.snippet
            ?.publishedAt ||
          ""
        )
      );

    const timestampMs =
      Number.isFinite(
        parsedTimestamp
      )
        ? parsedTimestamp
        : Date.now();

    const youtubeBadges:
      ResolvedBadge[] =
        [];

    if (
      item.authorDetails
        ?.isChatOwner
    ) {
      youtubeBadges.push({
        setId:
          "broadcaster",
        id:
          "1",
        info:
          "",
        imageUrl:
          "",
        title:
          "YouTube channel owner",
      });
    }

    if (
      item.authorDetails
        ?.isChatModerator
    ) {
      youtubeBadges.push({
        setId:
          "moderator",
        id:
          "1",
        info:
          "",
        imageUrl:
          "",
        title:
          "YouTube moderator",
      });
    }

    if (
      item.authorDetails
        ?.isChatSponsor
    ) {
      youtubeBadges.push({
        setId:
          "subscriber",
        id:
          "1",
        info:
          "",
        imageUrl:
          "",
        title:
          "YouTube member",
      });
    }

    return {
      id:
        `youtube-message:${id}`,

      kind:
        "chat",

      timestampMs,

      time:
        clockTime(
          timestampMs
        ),

      userId:
        String(
          item.authorDetails
            ?.channelId ||
          item.snippet
            ?.authorChannelId ||
          ""
        ),

      userLogin:
        username
          .toLowerCase(),

      username,

      text,

      color:
        youtubeAuthorColor(
          item.authorDetails
        ),

      badges:
        youtubeBadges,

      fragments: [
        {
          type:
            "text",

          text,
        },
      ],

      reply:
        null,

      platform:
        "youtube",

      avatarUrl:
        String(
          item.authorDetails
            ?.profileImageUrl ||
          ""
        ),

      eventType,

      mentionText,
    };
  }

  async function processYouTubeStreamPayload(
    payload: string[]
  ) {
    const [
      tabId = "",
      generationRaw = "",
      rawJson = "",
    ] =
      payload || [];

    const generation =
      Number(
        generationRaw
      );

    if (
      !tabId ||
      !rawJson ||
      !Number.isFinite(
        generation
      ) ||
      youtubeChatPollGenerationRef
        .current[
          tabId
        ] !==
        generation
    ) {
      return;
    }

    let data:
      YouTubeLiveChatListResponse;

    try {
      data =
        JSON.parse(
          rawJson
        ) as YouTubeLiveChatListResponse;
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke lese YouTube stream-payload:",
        error
      );
      return;
    }

    updateYouTubeStreamHealth(tabId, generation, null);

    const incoming =
      (
        data.items ||
        []
      )
        .map(
          youtubeMessageToChatMessage
        )
        .filter(
          (
            message
          ):
            message is TwitchChatMessage =>
              Boolean(
                message
              )
        );

    const inserted:
      TwitchChatMessage[] =
      [];

    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            current
          ) => {
            if (
              current.broadcasterId !==
                tabId
            ) {
              return current;
            }

            const fresh:
              TwitchChatMessage[] =
              [];
            const replacements =
              new Map<
                number,
                TwitchChatMessage
              >();

            for (
              const message
              of incoming
            ) {
              const existingIndex =
                findAuthoritativeMessageMatch(
                  current.messages,
                  message
                );

              if (
                existingIndex < 0
              ) {
                fresh.push(
                  message
                );
                inserted.push(
                  message
                );
                continue;
              }

              if (
                current.messages[
                  existingIndex
                ]?.optimistic &&
                !replacements.has(
                  existingIndex
                )
              ) {
                replacements.set(
                  existingIndex,
                  message
                );
                inserted.push(
                  message
                );
              }
            }

            const standaloneYouTube =
              current.platform ===
              "youtube";

            const offline =
              Boolean(
                data.offlineAt
              );

            return {
              ...current,

              ...(standaloneYouTube
                ? {
                    status:
                      offline
                        ? "disconnected"
                        : "live",
                    error:
                      "",
                    isLive:
                      !offline,
                  }
                : {
                    youtubeIsLive:
                      !offline,
                  }),

              youtubeVideoId:
                offline
                  ? undefined
                  : current.youtubeVideoId,

              youtubeLiveChatId:
                offline
                  ? undefined
                  : current.youtubeLiveChatId,

              messages: [
                ...current.messages.map(
                  (message, index) =>
                    replacements.get(
                      index
                    ) || message
                ),
                ...fresh,
              ].sort(
                (
                  a,
                  b
                ) =>
                  a.timestampMs -
                  b.timestampMs
              ),
            };
          }
        )
    );

    const currentTab =
      channelTabsRef.current
        .find(
          (
            item
          ) =>
            item.broadcasterId ===
            tabId
        );

    if (
      currentTab
    ) {
      for (
        const message
        of inserted
      ) {
        const isOwnMessage =
          Boolean(
            message.userId &&
            youtubeChannelId &&
            message.userId ===
              youtubeChannelId
          );
        const mentionedMe =
          storedMessageMentionsMe(
            message
          );

        captureMention(
          currentTab,
          message,
          isOwnMessage
        );

        if (
          mentionedMe &&
          !isOwnMessage &&
          !isMentionSoundMuted(
            currentTab.login,
            currentTab.broadcasterId
          )
        ) {
          playMentionSound();
        }

        saveMessageToDisk(
          currentTab.youtubeChannelId ||
            currentTab.login,
          message,
          "youtube"
        );
      }
    }

    if (
      data.offlineAt
    ) {
      addSystemLine(
        ui("YouTube-direktesendingen er avsluttet.", "The YouTube live stream has ended."),
        tabId,
        "youtube"
      );

      stopYouTubeChatPoll(
        tabId
      );
    }
  }

  async function restartYouTubeStreamAfterAuth(
    tabId: string,
    generation: number
  ) {
    if (
      youtubeChatPollGenerationRef
        .current[
          tabId
        ] !==
        generation
    ) {
      return;
    }

    const tab =
      channelTabsRef.current
        .find(
          (
            item
          ) =>
            item.broadcasterId ===
            tabId
        );

    const liveChatId =
      tab?.youtubeLiveChatId ||
      "";

    if (
      !tab ||
      !liveChatId
    ) {
      return;
    }

    updateYouTubeStreamHealth(tabId, generation, "reconnecting");

    try {
      const token =
        await refreshYouTubeAccessToken();

      if (
        youtubeChatPollGenerationRef
          .current[
            tabId
          ] !==
          generation
      ) {
        return;
      }

      await invoke<number>(
        "start_youtube_chat_stream",
        {
          tabId,
          liveChatId,
          accessToken:
            token,
          generation,
          pageToken:
            "",
        }
      );
    } catch (
      error
    ) {
      const message =
        error instanceof
        Error
          ? error.message
          : String(
              error
            );

      updateTabs(
        (
          tabs
        ) =>
          tabs.map(
            (
              current
            ) =>
              current.broadcasterId ===
              tabId
                ? {
                    ...current,
                    status:
                      current.platform ===
                      "youtube"
                        ? "error"
                        : current.status,
                    error:
                      current.platform ===
                      "youtube"
                        ? message
                        : current.error,
                    youtubeIsLive:
                      false,
                  }
                : current
          )
      );

      addSystemLine(
        ui("YouTube-direktesendingen kunne ikke fornye innloggingen.", "The YouTube live stream could not renew sign-in."),
        tabId,
        "youtube"
      );

      updateYouTubeStreamHealth(
        tabId,
        generation,
        connectionErrorNeedsSignIn(message) || /HTTP (400|401)\b/.test(message)
          ? "sign-in"
          : "unavailable"
      );
    }
  }

  async function processYouTubeStreamError(
    payload: string[]
  ) {
    const [
      tabId = "",
      generationRaw = "",
      rawMessage = "",
    ] =
      payload || [];

    const generation =
      Number(
        generationRaw
      );

    if (
      !tabId ||
      !Number.isFinite(
        generation
      ) ||
      youtubeChatPollGenerationRef
        .current[
          tabId
        ] !==
        generation
    ) {
      return;
    }

    if (
      rawMessage.startsWith(
        "AUTH_EXPIRED:"
      )
    ) {
      await restartYouTubeStreamAfterAuth(
        tabId,
        generation
      );
      return;
    }

    const cleanMessage =
      ui("YouTube-direktesendingen mistet forbindelsen.", "The YouTube live stream lost its connection.");

    updateYouTubeStreamHealth(tabId, generation, "disconnected");

    const tab =
      channelTabsRef.current
        .find(
          (
            item
          ) =>
            item.broadcasterId ===
            tabId
        );

    if (
      !tab
    ) {
      return;
    }

    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            current
          ) =>
            current.broadcasterId ===
            tabId
              ? current.platform ===
                  "youtube"
                ? {
                    ...current,
                    status:
                      "error",
                    error:
                      cleanMessage,
                    isLive:
                      false,
                    youtubeIsLive:
                      false,
                  }
                : {
                    ...current,
                    youtubeIsLive:
                      false,
                  }
              : current
        )
    );

    addSystemLine(
      cleanMessage,
      tabId,
      "youtube"
    );
  }

  async function connectYouTubeChatStream(
    tabId: string,
    liveChatId: string,
    generation: number
  ) {
    if (
      youtubeChatPollGenerationRef
        .current[
          tabId
        ] !==
        generation
    ) {
      return;
    }

    let accessToken =
      youtubeAccessTokenRef.current;

    updateYouTubeStreamHealth(tabId, generation, "connecting");

    try {
      if (
        !accessToken
      ) {
        accessToken =
          await refreshYouTubeAccessToken();
      }

      if (
        youtubeChatPollGenerationRef
          .current[
            tabId
          ] !==
          generation
      ) {
        return;
      }

      await invoke<number>(
        "start_youtube_chat_stream",
        {
          tabId,
          liveChatId,
          accessToken,
          generation,
          pageToken:
            "",
        }
      );
    } catch (
      error
    ) {
      if (
        youtubeChatPollGenerationRef
          .current[
            tabId
          ] !==
        generation
      ) {
        return;
      }

      const message =
        error instanceof
        Error
          ? error.message
          : String(
              error
            );

      updateTabs(
        (
          tabs
        ) =>
          tabs.map(
            (
              current
            ) =>
              current.broadcasterId ===
              tabId
                ? current.platform ===
                    "youtube"
                  ? {
                      ...current,
                      status:
                        "error",
                      error:
                        message,
                      isLive:
                        false,
                      youtubeIsLive:
                        false,
                    }
                  : {
                      ...current,
                      youtubeIsLive:
                        false,
                    }
                : current
          )
      );

      addSystemLine(
        ui("YouTube-direktesendingen kunne ikke starte.", "The YouTube live stream could not start."),
        tabId,
        "youtube"
      );

      updateYouTubeStreamHealth(
        tabId,
        generation,
        connectionErrorNeedsSignIn(message) || /HTTP (400|401)\b/.test(message)
          ? "sign-in"
          : "unavailable"
      );
    }
  }

  function startYouTubeChatPoll(
    tabId: string,
    liveChatId: string
  ) {
    stopYouTubeChatPoll(
      tabId
    );

    const generation =
      (
        youtubeChatPollGenerationRef
          .current[
            tabId
          ] ||
        0
      ) +
      1;

    youtubeChatPollGenerationRef
      .current[
        tabId
      ] =
      generation;

    void connectYouTubeChatStream(
      tabId,
      liveChatId,
      generation
    );
  }

  async function addYouTubeChannel() {
    primeMentionSound();

    if (
      !youtubeConnected
    ) {
      setAddChannelError(
        ui("Koble til YouTube fra Kontoer først.", "Connect YouTube from Accounts first.")
      );

      return;
    }

    if (
      !newChannelInput
        .trim()
    ) {
      setAddChannelError(
        ui("Lim inn @handle, YouTube-kanal-URL, kanal-ID eller en video-/direktesendings-URL.", "Paste an @handle, YouTube channel URL, channel ID or a video/live URL.")
      );

      return;
    }

    setAddingChannel(
      true
    );

    setAddChannelError(
      ""
    );

    try {
      const {
        channel,
        live,
      } =
        await resolveYouTubeChannelInput(
          newChannelInput
        );

      rememberYouTubeChannel(
        channel
      );

      const tabId =
        `youtube-channel:${channel.channelId}`;

      const existing =
        channelTabsRef.current
          .find(
            (
              tab
            ) =>
              tab.broadcasterId ===
              tabId
          );

      if (
        existing
      ) {
        updateTabs(
          (
            tabs
          ) =>
            tabs.map(
              (
                tab
              ) =>
                tab.broadcasterId ===
                tabId
                  ? {
                      ...tab,

                      displayName:
                        channel.name,

                      profileImageUrl:
                        channel.avatarUrl,

                      youtubeChannelId:
                        channel.channelId,

                      youtubeUploadsPlaylistId:
                        channel.uploadsPlaylistId,

                      youtubeVideoId:
                        live?.videoId,

                      youtubeLiveChatId:
                        live?.liveChatId,

                      youtubeIsLive:
                        Boolean(
                          live
                        ),

                      isLive:
                        Boolean(
                          live
                        ),

                      status:
                        live
                          ? "joining"
                          : "disconnected",

                      error:
                        "",
                    }
                  : tab
            )
        );

        activateChannel(
          tabId
        );

        if (
          live
        ) {
          startYouTubeChatPoll(
            tabId,
            live.liveChatId
          );
        }

        setNewChannelInput(
          ""
        );

        setShowAddChannel(
          false
        );

        return;
      }

      const storedMessages =
        await loadStoredChannelHistory(
          channel.channelId,
          "youtube"
        );

      const tab:
        ChannelTab = {
          broadcasterId:
            tabId,

          login:
            channel.channelId,

          displayName:
            channel.name,

          profileImageUrl:
            channel.avatarUrl,

          isLive:
            Boolean(
              live
            ),

          canModerate:
            false,

          status:
            live
              ? "joining"
              : "disconnected",

          error:
            "",

          messages:
            storedMessages,

          hasMention:
            false,

          platform:
            "youtube",

          youtubeChannelId:
            channel.channelId,

          youtubeUploadsPlaylistId:
            channel.uploadsPlaylistId,

          youtubeVideoId:
            live?.videoId,

          youtubeLiveChatId:
            live?.liveChatId,

          youtubeIsLive:
            Boolean(
              live
            ),
        };

      updateTabs(
        (
          tabs
        ) => [
          ...tabs,
          tab,
        ]
      );

      activateChannel(
        tabId
      );

      setNewChannelInput(
        ""
      );

      setShowAddChannel(
        false
      );

      if (
        live
      ) {
        startYouTubeChatPoll(
          tabId,
          live.liveChatId
        );
      }
    } catch (
      error
    ) {
      setAddChannelError(
        error instanceof
        Error
          ? error.message
          : ui("Kunne ikke legge til YouTube-kanalen.", "Could not add the YouTube channel.")
      );
    } finally {
      setAddingChannel(
        false
      );
    }
  }

  async function addKickChannel() {
    primeMentionSound();

    if (
      !kickConnected
    ) {
      setAddChannelError(
        ui("Koble til Kick fra Kontoer først.", "Connect Kick from Accounts first.")
      );
      return;
    }

    if (
      !kickPublicWebhookReady
    ) {
      setAddChannelError(
        ui("FyFlade sin Kick-tjeneste er ikke klar. Vent litt og prøv igjen.", "FyFlade's Kick service is not ready. Wait a moment and try again.")
      );
      return;
    }

    if (
      !kickWebhookConfigured
    ) {
      setAddChannelError(
        ui("FyFlade sin Kick-chat er ikke ferdig konfigurert ennå.", "FyFlade's Kick chat is not fully configured yet.")
      );
      return;
    }

    if (
      !newChannelInput.trim()
    ) {
      setAddChannelError(
        ui("Skriv inn Kick-kanalnavn eller kick.com/kanalnavn.", "Enter a Kick channel name or kick.com/channel-name.")
      );
      return;
    }

    setAddingChannel(
      true
    );
    setAddChannelError(
      ""
    );

    try {
      const {
        channel,
        isLive,
      } =
        await resolveKickChannel(
          newChannelInput
        );

      const merged =
        channelTabsRef.current.find(
          (tab) =>
            tab.kickBroadcasterUserId ===
            channel.broadcasterUserId &&
            tab.platform !==
              "kick"
        );

      if (
        merged
      ) {
        activateChannel(
          merged.broadcasterId
        );
        setNewChannelInput(
          ""
        );
        setShowAddChannel(
          false
        );
        return;
      }

      rememberKickChannel(
        channel
      );

      const tabId =
        `kick:${channel.broadcasterUserId}`;

      const existing =
        channelTabsRef.current.find(
          (tab) =>
            tab.broadcasterId ===
            tabId
        );

      if (
        existing
      ) {
        updateTabs(
          (tabs) =>
            tabs.map(
              (tab) =>
                tab.broadcasterId ===
                tabId
                  ? {
                      ...tab,
                      displayName:
                        channel.name,
                      profileImageUrl:
                        channel.avatarUrl,
                      login:
                        channel.slug,
                      isLive,
                      status:
                        isLive
                          ? "live"
                          : "disconnected",
                      error:
                        "",
                      kickBroadcasterUserId:
                        channel.broadcasterUserId,
                      kickChannelSlug:
                        channel.slug,
                      kickIsLive:
                        isLive,
                    }
                  : tab
            )
        );
      } else {
        const storedMessages =
          await loadStoredChannelHistory(
            channel.broadcasterUserId,
            "kick"
          );

        const tab:
          ChannelTab = {
          broadcasterId:
            tabId,
          login:
            channel.slug,
          displayName:
            channel.name,
          profileImageUrl:
            channel.avatarUrl,
          isLive,
          canModerate:
            false,
          status:
            isLive
              ? "live"
              : "disconnected",
          error:
            "",
          messages:
            storedMessages,
          hasMention:
            false,
          platform:
            "kick",
          kickBroadcasterUserId:
            channel.broadcasterUserId,
          kickChannelSlug:
            channel.slug,
          kickIsLive:
            isLive,
        };

        updateTabs(
          (tabs) => [
            ...tabs,
            tab,
          ]
        );
      }

      activateChannel(
        tabId
      );

      try {
        await ensureKickEventSubscriptions(
          channel.broadcasterUserId
        );
      } catch (
        error
      ) {
        const message =
          error instanceof
          Error
            ? error.message
            : ui("Kick-chathendelser kunne ikke aktiveres.", "Kick chat events could not be enabled.");

        addSystemLine(
          message,
          tabId,
          "kick"
        );
      }

      setNewChannelInput(
        ""
      );
      setShowAddChannel(
        false
      );
    } catch (
      error
    ) {
      setAddChannelError(
        error instanceof
        Error
          ? error.message
          : ui("Kunne ikke legge til Kick-kanalen.", "Could not add the Kick channel.")
      );
    } finally {
      setAddingChannel(
        false
      );
    }
  }

  async function addSelectedChannel() {
    if (
      newChannelPlatform ===
      "youtube"
    ) {
      await addYouTubeChannel();
      return;
    }

    if (
      newChannelPlatform ===
      "kick"
    ) {
      await addKickChannel();
      return;
    }

    await addTwitchChannel();
  }

  async function openYouTubeVideo(
    tab:
      ChannelTab
  ) {
    const url =
      tab.youtubeVideoId
        ? `https://www.youtube.com/watch?v=${encodeURIComponent(
            tab.youtubeVideoId
          )}`
        : tab.youtubeChannelId
          ? `https://www.youtube.com/channel/${encodeURIComponent(
              tab.youtubeChannelId
            )}`
          : "";

    if (
      !url
    ) {
      return;
    }

    try {
      await openUrl(
        url
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke åpne YouTube:",
        error
      );
    }
  }

  function saveUserNote(
    userId: string,
    note: string
  ) {
    if (
      !userId
    ) {
      return;
    }

    const next = {
      ...userNotes,
    };

    const clean =
      note.trim();

    if (
      clean
    ) {
      next[
        userId
      ] =
        clean;
    } else {
      delete next[
        userId
      ];
    }

    setUserNotes(
      next
    );

    localStorage.setItem(
      USER_NOTES_KEY,
      JSON.stringify(
        next
      )
    );

    setNoteDraft(
      clean
    );

    setShowNoteEditor(
      false
    );

    setShowNicknameEditor(false);
    setShowIgnoreMenu(false);
    setShowWhisperEditor(false);
    setWhisperDraft("");
    setLastIgnoreUndo(null);

    setUserCardActionStatus(
      clean
        ? ui("Notat lagret lokalt.", "Note saved locally.")
        : ui("Notat fjernet.", "Note removed.")
    );
  }

  function activateChannel(
    broadcasterId:
      string
  ) {
    setMentionInboxOpen(
      false
    );

    const tab =
      channelTabsRef.current
        .find(
          (
            item
          ) =>
            item.broadcasterId ===
            broadcasterId
        );

    activeChannelIdRef.current =
      broadcasterId;

    setActiveChannelId(
      broadcasterId
    );

    setUnreadMessageCounts(
      (current) => {
        if (!current[broadcasterId]) {
          return current;
        }

        const next = {
          ...current,
        };
        delete next[broadcasterId];
        return next;
      }
    );

    if (
      tab?.platform &&
      tab.platform !==
        "twitch"
    ) {
      setReplyingTo(
        null
      );

      setUserCard(
        null
      );
    }

    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            item
          ) =>
            item.broadcasterId ===
            broadcasterId
              ? {
                  ...item,

                  hasMention:
                    false,
                }
              : item
        )
    );

    if (
      tab &&
      (tab.platform ||
        "twitch") ===
        "twitch"
    ) {
      saveActiveChannel(
        tab.login
      );
    }
  }

  function toggleFavoriteChannel(
    broadcasterId: string
  ) {
    setFavoriteChannelIds(
      (current) => {
        const next =
          current.includes(
            broadcasterId
          )
            ? current.filter(
                (id) =>
                  id !== broadcasterId
              )
            : [
                ...current,
                broadcasterId,
              ];

        localStorage.setItem(
          FAVORITE_CHANNELS_KEY,
          JSON.stringify(next)
        );

        return next;
      }
    );
  }

  function setChannelGroup(
    broadcasterId: string,
    groupName: string
  ) {
    const clean =
      groupName
        .trim()
        .slice(0, 28);

    setChannelGroupById(
      (current) => {
        const next = {
          ...current,
        };

        if (clean) {
          next[broadcasterId] =
            clean;
        } else {
          delete next[
            broadcasterId
          ];
        }

        localStorage.setItem(
          CHANNEL_GROUPS_KEY,
          JSON.stringify(next)
        );

        return next;
      }
    );
  }

  async function loadModeratedChannels(
    accessToken:
      string,

    userId:
      string
  ) {
    const ids =
      new Set<
        string
      >([
        userId,
      ]);

    try {
      let after =
        "";

      do {
        const params =
          new URLSearchParams({
            user_id:
              userId,

            first:
              "100",
          });

        if (
          after
        ) {
          params.set(
            "after",
            after
          );
        }

        const response =
          await fetch(
            `https://api.twitch.tv/helix/moderation/channels?${params}`,
            {
              headers: {
                Authorization:
                  `Bearer ${accessToken}`,

                "Client-Id":
                  TWITCH_CLIENT_ID,
              },
            }
          );

        if (
          !response.ok
        ) {
          throw new Error(
            await response.text()
          );
        }

        const data =
          (
            await response.json()
          ) as TwitchModeratedChannelsResponse;

        for (
          const channel
          of data.data
        ) {
          ids.add(
            channel.broadcaster_id
          );
        }

        after =
          data.pagination
            ?.cursor ||
          "";
      } while (
        after
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke hente moderator-kanaler:",
        error
      );
    }

    // A broadcaster can always moderate their own channel even when the
    // moderated-channels response only contains channels owned by others.
    ids.add(userId);

    moderatedChannelIdsRef.current = ids;

    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            tab
          ) => ({
            ...tab,

            canModerate:
              ids.has(
                tab.broadcasterId
              ),
          })
        )
    );
  }

  function startReply(
    message:
      TwitchChatMessage
  ) {
    if (
      message.kind !==
      "chat"
    ) {
      return;
    }

    setReplyingTo({
      messageId:
        message.id,

      username:
        message.username,

      text:
        message.text,
    });

    window.requestAnimationFrame(
      () =>
        chatInputRef.current
          ?.focus()
    );
  }

  async function translateChatMessage(
    message:
      TwitchChatMessage
  ) {
    const targetLanguage =
      resolvedAppLanguage === "no"
        ? "no"
        : "en";
    if (!hasExternalTranslationConsent()) {
      const approved = window.confirm(
        ui(
          "Meldingsteksten åpnes hos Google Translate. FyFlade lagrer ikke oversettelsen. Fortsette?",
          "The message text will be opened in Google Translate. FyFlade does not store the translation. Continue?"
        )
      );
      if (!approved) return;
      rememberExternalTranslationConsent();
    }
    const url = googleWebTranslationProvider.buildUrl({
      text: message.text,
      targetLanguage,
    });

    try {
      await openUrl(url);
    } catch {
      setTwitchError(
        ui(
          "Kunne ikke åpne oversettelsen.",
          "Could not open the translation."
        )
      );
    }
  }

  function openTabContextMenu(
    event:
      MouseEvent<
        HTMLElement
      >,

    broadcasterId:
      string
  ) {
    event.preventDefault();

    event.stopPropagation();

    const width =
      235;

    const height =
      315;

    setTabContextMenu({
      x:
        Math.max(
          8,
          Math.min(
            event.clientX,
            window.innerWidth -
              width -
              8
          )
        ),

      y:
        Math.max(
          8,
          Math.min(
            event.clientY,
            window.innerHeight -
              height -
              8
          )
        ),

      broadcasterId,
    });
  }

  async function openOnTwitch(
    login: string
  ) {
    try {
      await openUrl(
        `https://www.twitch.tv/${encodeURIComponent(
          login
        )}`
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke åpne Twitch:",
        error
      );
    }
  }

  async function refreshChatHistoryStorage() {
    setChatHistoryStorageLoading(true);
    try {
      const entries = await invoke<ChatHistoryStorageEntry[]>(
        "list_chat_history_storage"
      );
      setChatHistoryStorage(Array.isArray(entries) ? entries : []);
    } catch {
      setChatHistoryStorage([]);
    } finally {
      setChatHistoryStorageLoading(false);
    }
  }

  async function clearAllChatHistory() {
    if (!window.confirm(ui("Vil du slette all lokalt lagret chat-historikk for alle kanaler? Dette kan ikke angres.", "Delete all locally stored chat history for every channel? This cannot be undone."))) {
      return;
    }

    try {
      await invoke("clear_all_chat_history");
      updateTabs((tabs) => tabs.map((tab) => ({
        ...tab,
        messages: tab.messages.filter((message) => message.kind === "system"),
      })));
      setSearchHistory([]);
      setChatHistoryStorage([]);
      setPrivacyStatus(ui("✓ All lokal chat-historikk er slettet.", "✓ All local chat history was deleted."));
    } catch {
      setPrivacyStatus(ui("Kunne ikke slette all chat-historikk.", "Could not delete all chat history."));
    }
  }

  async function clearChannelHistory(
    tab:
      ChannelTab
  ) {
    setTabContextMenu(
      null
    );

    if (
      !window.confirm(
        ui(`Vil du tømme den lokale chatloggen for ${tab.displayName}?`, `Do you want to clear the local chat history for ${tab.displayName}?`)
      )
    ) {
      return;
    }

    try {
      const basePlatform =
        tab.platform ||
        "twitch";

      if (
        basePlatform ===
        "youtube"
      ) {
        await invoke(
          "clear_channel_chat_history",
          {
            platform:
              "youtube",
            channel:
              tab.youtubeChannelId ||
              tab.login,
          }
        );
      } else if (
        basePlatform ===
        "kick"
      ) {
        await invoke(
          "clear_channel_chat_history",
          {
            platform:
              "kick",
            channel:
              tab.kickBroadcasterUserId ||
              tab.login,
          }
        );
      } else {
        await invoke(
          "clear_channel_chat_history",
          {
            platform:
              "twitch",
            channel:
              tab.login,
          }
        );

        if (
          tab.youtubeChannelId
        ) {
          await invoke(
            "clear_channel_chat_history",
            {
              platform:
                "youtube",
              channel:
                tab.youtubeChannelId,
            }
          );
        }
      }

      if (
        basePlatform !==
          "kick" &&
        tab.kickBroadcasterUserId
      ) {
        await invoke(
          "clear_channel_chat_history",
          {
            platform:
              "kick",
            channel:
              tab.kickBroadcasterUserId,
          }
        );
      }

      updateTabs(
        (tabs) =>
          tabs.map(
            (item) =>
              item.broadcasterId ===
              tab.broadcasterId
                ? {
                    ...item,
                    messages:
                      item.messages.filter(
                        (message) =>
                          message.kind ===
                          "system"
                      ),
                  }
                : item
          )
      );
      setPrivacyStatus(
        ui(`✓ Chatloggen for ${tab.displayName} er slettet.`, `✓ Chat history for ${tab.displayName} was deleted.`)
      );
      void refreshChatHistoryStorage();
    } catch {
      setTwitchError(
        ui("Kunne ikke tømme chatloggen.", "Could not clear the chat history.")
      );
    }
  }

  function getMentionAudioContext() {
    try {
      if (
        !mentionAudioContextRef.current
      ) {
        mentionAudioContextRef.current =
          new AudioContext();
      }

      return mentionAudioContextRef.current;
    } catch {
      return null;
    }
  }

  function primeMentionSound() {
    const context =
      getMentionAudioContext();

    if (
      context
        ?.state ===
      "suspended"
    ) {
      void context
        .resume()
        .catch(
          () =>
            undefined
        );
    }
  }

  function playMentionSound() {
    const context =
      getMentionAudioContext();

    if (
      !context
    ) {
      return;
    }

    const play =
      () => {
        const now =
          context.currentTime;

        for (
          const note
          of [
            {
              frequency:
                880,

              delay:
                0,
            },

            {
              frequency:
                1175,

              delay:
                0.12,
            },
          ]
        ) {
          const oscillator =
            context.createOscillator();

          const gain =
            context.createGain();

          const start =
            now +
            note.delay;

          oscillator.type =
            "sine";

          oscillator.frequency
            .setValueAtTime(
              note.frequency,
              start
            );

          gain.gain
            .setValueAtTime(
              0.0001,
              start
            );

          gain.gain
            .exponentialRampToValueAtTime(
              0.16,
              start +
                0.012
            );

          gain.gain
            .exponentialRampToValueAtTime(
              0.0001,
              start +
                0.18
            );

          oscillator.connect(
            gain
          );

          gain.connect(
            context.destination
          );

          oscillator.start(
            start
          );

          oscillator.stop(
            start +
              0.2
          );
        }
      };

    if (
      context.state ===
      "suspended"
    ) {
      void context
        .resume()
        .then(
          play
        )
        .catch(
          () =>
            undefined
        );
    } else {
      play();
    }
  }

  function connectedMentionAliases(platform?: ChatPlatform) {
    return platform
      ? connectedMentionAliasesByPlatformRef.current[platform]
      : connectedMentionAliasesRef.current;
  }

  function textMentionsConnectedAccount(
    text: string,
    platform?: ChatPlatform
  ) {
    return connectedMentionAliases(platform)
      .some(
        (alias) =>
          new RegExp(
            `(^|\\s|[([{])@${escapeRegExp(alias)}(?=$|\\s|[.,!?;:)\\]}>])`,
            "i"
          ).test(text)
      );
  }

  function messageMentionsConnectedAccount(
    message: TwitchChatMessage
  ) {
    const myTwitchUserId =
      twitchUserIdRef.current;
    const myTwitchLogin =
      twitchUserLoginRef.current
        .toLowerCase();

    if (
      message.fragments.some(
        (fragment) =>
          fragment.type === "mention" &&
          (
            Boolean(
              myTwitchUserId &&
              fragment.mention?.user_id ===
                myTwitchUserId
            ) ||
            Boolean(
              myTwitchLogin &&
              fragment.mention?.user_login
                ?.toLowerCase() ===
                myTwitchLogin
            )
          )
      )
    ) {
      return true;
    }

    return textMentionsConnectedAccount(
      message.mentionText ?? message.text,
      message.platform || "twitch"
    );
  }

  function setAndSaveMentionInboxEnabled(
    enabled: boolean
  ) {
    setMentionInboxEnabled(
      enabled
    );
    mentionInboxEnabledRef.current =
      enabled;

    writeSetting(
      MENTION_INBOX_ENABLED_KEY,
      enabled
    );

    if (!enabled) {
      setMentionInboxOpen(false);
    }
  }

  function captureMention(
    tab: ChannelTab,
    message: TwitchChatMessage,
    isOwnMessage = false
  ) {
    const repliesToMe =
      storedMessageRepliesToMe(
        message
      );
    const mentionsMe =
      storedMessageMentionsMe(
        message
      );
    const importantEvent =
      IMPORTANT_INBOX_EVENT_TYPES.has(
        message.eventType || ""
      );
    const highlighted =
      channelOverride(tab, "highlights", true) && storedMessageIsCustomHighlighted(
        message
      );
    const locallyIgnored =
      messageIsLocallyIgnored(
        message
      );
    const tags =
      buildInboxTags({
        mentionsMe,
        repliesToMe,
        isHighlighted:
          highlighted,
        isEvent:
          importantEvent,
      });

    if (
      highlighted &&
      !locallyIgnored &&
      !isOwnMessage
    ) {
      triggerHighlightFeedback(
        message,
        tab.broadcasterId
      );
    }

    if (
      !channelOverride(tab, "notifications", mentionInboxEnabledRef.current) ||
      locallyIgnored ||
      isOwnMessage ||
      message.kind !== "chat" ||
      tags.length === 0
    ) {
      return;
    }

    const platform =
      message.platform ||
      tab.platform ||
      "twitch";
    const id =
      `${platform}:${tab.broadcasterId}:${message.id}`;
    setMentionInboxItems(
      (current) => {
        if (
          current.some(
            (item) =>
              item.id === id
          )
        ) {
          return current;
        }

        const next = [
          ...current,
          {
            id,
            channelId:
              tab.broadcasterId,
            channelLogin:
              tab.login,
            channelDisplayName:
              tab.displayName,
            platform,
            capturedAt:
              Date.now(),
            tags,
            message,
          },
        ].slice(
          -MENTION_INBOX_MAX_ITEMS
        );

        writeSetting(
          MENTION_INBOX_ITEMS_KEY,
          next
        );

        return next;
      }
    );
  }

  function clearMentionInbox() {
    setMentionInboxItems([]);
    setMentionInboxLastReadAt(
      Date.now()
    );
    localStorage.removeItem(
      MENTION_INBOX_ITEMS_KEY
    );
    localStorage.setItem(
      MENTION_INBOX_LAST_READ_KEY,
      String(Date.now())
    );
  }

  function messageMentionsMe(
    event: any,

    fragments:
      TwitchMessageFragment[]
  ) {
    const myUserId =
      twitchUserIdRef.current;

    const myLogin =
      twitchUserLoginRef.current
        .toLowerCase();

    if (
      myUserId &&
      fragments.some(
        (
          fragment
        ) =>
          fragment.type ===
            "mention" &&
          fragment.mention
            ?.user_id ===
            myUserId
      )
    ) {
      return true;
    }

    if (
      myLogin &&
      fragments.some(
        (
          fragment
        ) =>
          fragment.type ===
            "mention" &&
          fragment.mention
            ?.user_login
            ?.toLowerCase() ===
            myLogin
      )
    ) {
      return true;
    }

    const text =
      String(
        event
          ?.message
          ?.text ||
          ""
      );

    return textMentionsConnectedAccount(
      text,
      "twitch"
    );
  }

  function storedMessageMentionsMe(
    message:
      TwitchChatMessage
  ) {
    if (
      isUserIgnoredForHighlights(
        message.platform || "twitch",
        message.userId,
        message.userLogin || message.username
      )
    ) {
      return false;
    }

    return messageMentionsConnectedAccount(
      message
    );
  }

  function storedMessageRepliesToMe(
    message:
      TwitchChatMessage
  ) {
    const reply =
      message.reply;

    if (
      !reply ||
      isUserIgnoredForHighlights(
        message.platform || "twitch",
        message.userId,
        message.userLogin || message.username
      )
    ) {
      return false;
    }

    const parentUserId =
      reply.parentUserId || "";
    const connectedIds = [
      twitchUserIdRef.current,
      kickUserId,
      youtubeChannelId,
    ].filter(Boolean);

    if (
      parentUserId &&
      connectedIds.includes(
        parentUserId
      )
    ) {
      return true;
    }

    const parentNames = [
      reply.parentUserLogin,
      reply.parentUserName,
    ]
      .map((name) =>
        name
          .replace(/^@/, "")
          .trim()
          .toLocaleLowerCase()
      )
      .filter(Boolean);

    return connectedMentionAliases(message.platform || "twitch")
      .some((alias) =>
        parentNames.includes(
          alias.toLocaleLowerCase()
        )
      );
  }

  function storedMessageIsCustomHighlighted(
    message:
      TwitchChatMessage
  ) {
    if (
      isUserIgnoredForHighlights(
        message.platform || "twitch",
        message.userId,
        message.userLogin || message.username
      )
    ) {
      return false;
    }

    return isHighlightedUser(
      message.platform || "twitch",
      message.userId,
      message.userLogin ||
        message.username
    );
  }

  async function loadStoredChannelHistory(
    channelLogin:
      string,
    platform:
      ChatPlatform =
        "twitch"
  ) {
    try {
      const rawMessages =
        await invoke<
          string[]
        >(
          "load_chat_history",
          {
            platform,

            channel:
              channelLogin,

            maxAgeMs:
              chatHistoryRetentionMs(
                chatHistoryRetentionRef.current
              ),
          }
        );

      const maxAgeMs = chatHistoryRetentionMs(
        chatHistoryRetentionRef.current
      );
      const cutoff = maxAgeMs === 0
        ? 0
        : Date.now() - maxAgeMs;

      const parsed:
        TwitchChatMessage[] =
        [];

      const seen =
        new Set<
          string
        >();

      for (
        const raw
        of rawMessages
      ) {
        try {
          const message =
            JSON.parse(
              raw
            ) as TwitchChatMessage;

          if (
            !message ||
            typeof message.id !==
              "string" ||
            message.kind !==
              "chat" ||
            typeof message.timestampMs !==
              "number" ||
            message.timestampMs <
              cutoff ||
            seen.has(
              message.id
            )
          ) {
            continue;
          }

          seen.add(
            message.id
          );

          parsed.push({
            ...message,

            time:
              clockTime(
                message.timestampMs
              ),

            userId:
              message.userId ||
              "",

            userLogin:
              message.userLogin ||
              message.username
                ?.toLowerCase() ||
              "",

            badges:
              Array.isArray(
                message.badges
              )
                ? message.badges
                : [],

            fragments:
              Array.isArray(
                message.fragments
              )
                ? message.fragments
                : [],

            reply:
              message.reply ||
              null,

            platform:
              message.platform ||
              platform,

            avatarUrl:
              message.avatarUrl ||
              "",
          });
        } catch {
          // ødelagt logglinje
        }
      }

      return parsed.sort(
        (
          a,
          b
        ) =>
          a.timestampMs -
          b.timestampMs
      );
    } catch (
      error
    ) {
      console.error(
        `Kunne ikke laste chat for ${channelLogin}:`,
        error
      );

      return [];
    }
  }

  function saveMessageToDisk(
    channelLogin:
      string,

    message:
      TwitchChatMessage,

    platform:
      ChatPlatform =
        "twitch"
  ) {
    const normalizedChannel =
      channelLogin
        .replace(/^[@#]/, "")
        .toLowerCase();
    const liveChannel =
      channelTabsRef.current.find(
        (tab) => {
          if (
            platform ===
            "kick"
          ) {
            const matches =
              String(
                tab.kickBroadcasterUserId ||
                  (tab.platform === "kick"
                    ? tab.broadcasterId.replace(
                        /^kick:/,
                        ""
                      )
                    : "")
              ).toLowerCase() ===
                normalizedChannel ||
              (tab.kickChannelSlug || "")
                .toLowerCase() ===
                normalizedChannel;

            return (
              matches &&
              (tab.platform === "kick"
                ? tab.isLive
                : Boolean(
                    tab.kickIsLive
                  ))
            );
          }

          if (
            platform ===
            "youtube"
          ) {
            const matches =
              (tab.youtubeChannelId || "")
                .toLowerCase() ===
                normalizedChannel ||
              (tab.platform === "youtube" &&
                tab.login.toLowerCase() ===
                  normalizedChannel);

            return (
              matches &&
              (tab.platform === "youtube"
                ? tab.isLive
                : Boolean(
                    tab.youtubeIsLive
                  ))
            );
          }

          return (
            (tab.platform || "twitch") ===
              "twitch" &&
            tab.login.toLowerCase() ===
              normalizedChannel &&
            tab.isLive
          );
        }
      );

    if (!liveChannel) {
      return;
    }

    if (
      !channelOverride(
        liveChannel,
        "saveLiveChat",
        saveLiveChatHistoryEnabledRef.current
      )
    ) {
      return;
    }

    if (
      message.kind !==
      "chat"
    ) {
      return;
    }

    void invoke(
      "save_chat_message",
      {
        platform,

        channel:
          channelLogin,

        timestampMs:
          message.timestampMs,

        payloadJson:
          JSON.stringify(
            message
          ),

        maxAgeMs:
          chatHistoryRetentionMs(
            chatHistoryRetentionRef.current
          ),
      }
    ).catch(
      console.error
    );
  }

  async function refreshLiveStatuses() {
    const accessToken =
      twitchAccessTokenRef.current;

    const tabs =
      channelTabsRef.current;

    if (!accessToken) {
      return;
    }

    if (tabs.length === 0) {
      await syncTwitchChatSubscriptions(
        new Set<string>()
      );
      return;
    }

    try {
      const liveIds =
        new Set<
          string
        >();

      const ids =
        Array.from(
          new Set(
            tabs
              .filter(
                (
                  tab
                ) =>
                  (tab.platform ||
                    "twitch") ===
                    "twitch" &&
                  !tab.broadcasterId.startsWith(
                    "cached:"
                  )
              )
              .map(
                (
                  tab
                ) =>
                  tab.broadcasterId
              )
          )
        );

      for (
        let i =
          0;
        i <
        ids.length;
        i +=
          100
      ) {
        const query =
          ids
            .slice(
              i,
              i +
                100
            )
            .map(
              (
                id
              ) =>
                `user_id=${encodeURIComponent(
                  id
                )}`
            )
            .join(
              "&"
            );

        const response =
          await fetch(
            `https://api.twitch.tv/helix/streams?${query}`,
            {
              headers: {
                Authorization:
                  `Bearer ${accessToken}`,

                "Client-Id":
                  TWITCH_CLIENT_ID,
              },
            }
          );

        if (
          !response.ok
        ) {
          throw new Error(
            await response.text()
          );
        }

        const data =
          (
            await response.json()
          ) as TwitchStreamsResponse;

        for (
          const stream
          of data.data
        ) {
          liveIds.add(
            stream.user_id
          );
        }
      }

      updateTabs(
        (
          tabsNow
        ) =>
          tabsNow.map(
            (
              tab
            ) =>
              (tab.platform ||
                "twitch") !==
                "twitch"
                ? tab
                : {
                    ...tab,

                    isLive:
                      liveIds.has(
                        tab.broadcasterId
                      ),

                    status:
                      liveIds.has(
                        tab.broadcasterId
                      )
                        ? subscribedChannelIds.current.has(
                            tab.broadcasterId
                          )
                          ? "live"
                          : "joining"
                        : "disconnected",

                    error:
                      "",
                  }
          )
      );

      await syncTwitchChatSubscriptions(
        liveIds
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke oppdatere LIVE-status:",
        error
      );
    }
  }

  function addSystemLine(
    text: string,

    broadcasterId?:
      string,

    platform:
      ChatPlatform =
        "twitch"
  ) {
    const timestampMs =
      Date.now();

    const line:
      TwitchChatMessage = {
        id:
          `system-${timestampMs}-${Math.random()}`,

        kind:
          "system",

        timestampMs,

        time:
          clockTime(
            timestampMs
          ),

        userId:
          "",

        userLogin:
          "",

        username:
          "",

        text,

        color:
          "#8b949e",

        badges:
          [],

        fragments:
          [],

        reply:
          null,

        platform,
      };

    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            tab
          ) =>
            (
              broadcasterId &&
              tab.broadcasterId !==
                broadcasterId
            ) ||
            (
              !broadcasterId &&
              (tab.platform ||
                "twitch") !==
                "twitch"
            )
              ? tab
              : {
                  ...tab,

                  messages: [
                    ...tab.messages,
                    line,
                  ],
                }
        )
    );
  }

  function announceConnectionLost() {
    if (
      outageAnnounced.current
    ) {
      return;
    }

    outageAnnounced.current =
      true;

    addSystemLine(
      ui("frakoblet", "disconnected")
    );

    addSystemLine(
      ui("Servertilkoblingen gikk ut på tid, kobler til igjen", "Server connection timed out, reconnecting")
    );
  }

  function announceConnectionRestored() {
    if (
      !outageAnnounced.current
    ) {
      return;
    }

    addSystemLine(
      ui("tilkoblet", "connected")
    );

    outageAnnounced.current =
      false;
  }

  function getSevenTvCosmetics(
    platform: ChatPlatform | undefined,
    platformId: string
  ) {
    if (
      !sevenTvEmotesEnabled ||
      !platformId
    ) {
      return null;
    }

    return (
      sevenTvCosmeticsCacheRef.current[
        sevenTvCosmeticsKey(
          platform,
          platformId
        )
      ]?.cosmetics ||
      null
    );
  }

  function queueSevenTvCosmetics(
    platform: ChatPlatform | undefined,
    platformId: string
  ) {
    if (
      !sevenTvEmotesEnabled ||
      !platformId
    ) {
      return;
    }

    const key =
      sevenTvCosmeticsKey(
        platform,
        platformId
      );
    const cached =
      sevenTvCosmeticsCacheRef.current[
        key
      ];

    if (
      cached &&
      Date.now() -
        cached.fetchedAt <
        SEVENTV_COSMETICS_CACHE_TTL_MS
    ) {
      return;
    }

    if (
      sevenTvCosmeticsLoadingRef.current.has(
        key
      ) ||
      sevenTvCosmeticsQueueRef.current[
        key
      ]
    ) {
      return;
    }

    sevenTvCosmeticsQueueRef.current[
      key
    ] = {
      key,
      platform:
        sevenTvPlatformForChatPlatform(
          platform
        ),
      platformId,
    };

    if (
      sevenTvCosmeticsFlushTimerRef.current ===
      null
    ) {
      sevenTvCosmeticsFlushTimerRef.current =
        window.setTimeout(
          () => {
            sevenTvCosmeticsFlushTimerRef.current =
              null;
            void flushSevenTvCosmeticsQueue();
          },
          120
        );
    }
  }

  async function flushSevenTvCosmeticsQueue() {
    if (
      sevenTvCosmeticsRequestActiveRef.current
    ) {
      return;
    }

    const batch =
      Object.values(
        sevenTvCosmeticsQueueRef.current
      ).slice(
        0,
        20
      );

    if (
      batch.length ===
      0
    ) {
      return;
    }

    for (
      const request
      of batch
    ) {
      delete sevenTvCosmeticsQueueRef.current[
        request.key
      ];
      sevenTvCosmeticsLoadingRef.current.add(
        request.key
      );
    }

    sevenTvCosmeticsRequestActiveRef.current =
      true;
    setSevenTvCosmeticsStatus(
      "loading"
    );

    const variableDefinitions =
      batch
        .map(
          (_, index) =>
            `$platform${index}: Platform!, $platformId${index}: String!`
        )
        .join(
          ", "
        );
    const userSelections =
      batch
        .map(
          (_, index) =>
            `u${index}: userByConnection(platform: $platform${index}, platformId: $platformId${index}) { ...FyFladeSevenTvUserCosmetics }`
        )
        .join(
          "\n"
        );
    const variables:
      Record<string, string> =
      {};

    batch.forEach(
      (
        request,
        index
      ) => {
        variables[
          `platform${index}`
        ] =
          request.platform;
        variables[
          `platformId${index}`
        ] =
          request.platformId;
      }
    );

    const query = `
      query FyFladeSevenTvCosmetics(${variableDefinitions}) {
        users {
          ${userSelections}
        }
      }

      fragment FyFladeSevenTvUserCosmetics on User {
        id
        style {
          activeBadge {
            id
            name
            description
            images {
              url
              scale
              width
              height
              mime
              frameCount
            }
          }
          activePaint {
            id
            name
            data {
              layers {
                id
                opacity
                ty {
                  __typename
                  ... on PaintLayerTypeSingleColor {
                    color { r g b a hex }
                  }
                  ... on PaintLayerTypeLinearGradient {
                    angle
                    repeating
                    stops {
                      at
                      color { r g b a hex }
                    }
                  }
                  ... on PaintLayerTypeRadialGradient {
                    repeating
                    shape
                    stops {
                      at
                      color { r g b a hex }
                    }
                  }
                  ... on PaintLayerTypeImage {
                    images {
                      url
                      scale
                      width
                      height
                      mime
                      frameCount
                    }
                  }
                }
              }
              shadows {
                offsetX
                offsetY
                blur
                color { r g b a hex }
              }
            }
          }
          activeProfilePicture {
            images {
              url
              scale
              width
              height
              mime
              frameCount
            }
          }
        }
      }
    `;

    let payload:
      any =
      null;
    let lastError:
      unknown =
      null;

    try {
      for (
        const endpoint
        of [
          "https://api.7tv.app/v4/gql",
          "https://7tv.io/v4/gql",
        ]
      ) {
        try {
          const response =
            await fetch(
              endpoint,
              {
                method:
                  "POST",
                headers: {
                  Accept:
                    "application/json",
                  "Content-Type":
                    "application/json",
                },
                body:
                  JSON.stringify({
                    query,
                    variables,
                  }),
              }
            );

          if (
            !response.ok
          ) {
            throw new Error(
              `HTTP ${response.status}`
            );
          }

          const candidate =
            await response.json();

          if (
            candidate?.errors?.length &&
            !candidate?.data
          ) {
            throw new Error(
              candidate.errors
                .map(
                  (error: any) =>
                    error?.message ||
                    "7TV GraphQL-feil"
                )
                .join(
                  "; "
                )
            );
          }

          payload =
            candidate;
          break;
        } catch (
          error
        ) {
          lastError =
            error;
        }
      }

      if (
        !payload
      ) {
        throw (
          lastError ||
          new Error(
            "7TV svarte ikke."
          )
        );
      }

      const fetchedAt =
        Date.now();

      batch.forEach(
        (
          request,
          index
        ) => {
          const user =
            payload?.data
              ?.users?.[
                `u${index}`
              ];
          const style =
            user?.style;
          const profileImage =
            bestSevenTvImage(
              style
                ?.activeProfilePicture
                ?.images
            );

          sevenTvCosmeticsCacheRef.current[
            request.key
          ] = {
            cosmetics:
              user
                ? {
                    sevenTvUserId:
                      String(
                        user.id ||
                          ""
                      ),
                    badge:
                      style?.activeBadge ||
                      null,
                    paint:
                      style?.activePaint ||
                      null,
                    profileImageUrl:
                      profileImage?.url
                        ? normalizeExternalUrl(
                            profileImage.url
                          )
                        : "",
                  }
                : null,
            fetchedAt,
          };
        }
      );

      const cosmeticsEntries = Object.entries(sevenTvCosmeticsCacheRef.current);
      if (cosmeticsEntries.length > 1000) {
        cosmeticsEntries
          .sort((left, right) => left[1].fetchedAt - right[1].fetchedAt)
          .slice(0, cosmeticsEntries.length - 750)
          .forEach(([key]) => delete sevenTvCosmeticsCacheRef.current[key]);
      }

      setSevenTvCosmeticsStatus(
        "ready"
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke laste 7TV-navnestiler og badges:",
        error
      );

      const retryAt =
        Date.now() -
        SEVENTV_COSMETICS_CACHE_TTL_MS +
        60 * 1000;

      for (
        const request
        of batch
      ) {
        if (
          !sevenTvCosmeticsCacheRef.current[
            request.key
          ]
        ) {
          sevenTvCosmeticsCacheRef.current[
            request.key
          ] = {
            cosmetics:
              null,
            fetchedAt:
              retryAt,
          };
        }
      }

      setSevenTvCosmeticsStatus(
        "error"
      );
    } finally {
      for (
        const request
        of batch
      ) {
        sevenTvCosmeticsLoadingRef.current.delete(
          request.key
        );
      }

      sevenTvCosmeticsRequestActiveRef.current =
        false;
      setSevenTvCosmeticsVersion(
        (current) =>
          current +
          1
      );

      if (
        Object.keys(
          sevenTvCosmeticsQueueRef.current
        ).length >
        0
      ) {
        sevenTvCosmeticsFlushTimerRef.current =
          window.setTimeout(
            () => {
              sevenTvCosmeticsFlushTimerRef.current =
                null;
              void flushSevenTvCosmeticsQueue();
            },
            80
          );
      }
    }
  }

  async function fetchPublicJson(
    urls: string[],
    allowNotFound = false
  ) {
    let lastError:
      unknown =
      null;

    for (
      const url
      of urls
    ) {
      try {
        const response =
          await window.fetch(
            url,
            {
              headers: {
                Accept:
                  "application/json",
              },
            }
          );

        if (
          response.status ===
            404 &&
          allowNotFound
        ) {
          return null;
        }

        if (
          !response.ok
        ) {
          lastError =
            new Error(
              `HTTP ${response.status}`
            );

          continue;
        }

        return await response.json();
      } catch (
        error
      ) {
        lastError =
          error;
      }
    }

    if (
      allowNotFound &&
      lastError ===
        null
    ) {
      return null;
    }

    throw (
      lastError ||
      new Error(
        "Kunne ikke hente emotes."
      )
    );
  }

  function shouldUseThirdPartyCache(
    key: string
  ) {
    const loadedAt =
      thirdPartyEmoteLoadedAtRef.current[
        key
      ] ||
      0;

    return (
      Date.now() -
        loadedAt <
      THIRD_PARTY_EMOTE_CACHE_TTL_MS
    );
  }

  function bumpThirdPartyEmotes() {
    setThirdPartyEmoteRevision(
      (
        revision
      ) =>
        revision +
        1
    );
  }

  async function runThirdPartyEmoteRequest(
    key: string,
    request:
      () =>
        Promise<void>
  ) {
    const existing =
      thirdPartyEmoteRequestsRef.current[
        key
      ];

    if (
      existing
    ) {
      return existing;
    }

    const promise =
      request()
        .finally(
          () => {
            delete thirdPartyEmoteRequestsRef.current[
              key
            ];
          }
        );

    thirdPartyEmoteRequestsRef.current[
      key
    ] =
      promise;

    return promise;
  }

  function clearSevenTvEventHeartbeatTimer() {
    if (
      sevenTvEventHeartbeatTimerRef.current !==
      null
    ) {
      window.clearTimeout(
        sevenTvEventHeartbeatTimerRef.current
      );
    }

    sevenTvEventHeartbeatTimerRef.current =
      null;
  }

  function clearSevenTvEventReconnectTimer() {
    if (
      sevenTvEventReconnectTimerRef.current !==
      null
    ) {
      window.clearTimeout(
        sevenTvEventReconnectTimerRef.current
      );
    }

    sevenTvEventReconnectTimerRef.current =
      null;
  }

  function armSevenTvEventHeartbeatWatchdog(
    socket: WebSocket,
    heartbeatInterval?: number
  ) {
    if (
      typeof heartbeatInterval ===
        "number" &&
      Number.isFinite(
        heartbeatInterval
      ) &&
      heartbeatInterval > 0
    ) {
      sevenTvEventHeartbeatIntervalRef.current =
        heartbeatInterval;
    }

    clearSevenTvEventHeartbeatTimer();

    sevenTvEventHeartbeatTimerRef.current =
      window.setTimeout(
        () => {
          sevenTvEventHeartbeatTimerRef.current =
            null;

          if (
            sevenTvEventWantedRef.current &&
            sevenTvEventSocketRef.current ===
              socket
          ) {
            try {
              socket.close();
            } catch {
              // reconnect skjer i onclose
            }
          }
        },
        Math.max(
          15000,
          sevenTvEventHeartbeatIntervalRef.current *
            3.5
        )
      );
  }

  function openSevenTvSetIds() {
    const openBroadcasterIds =
      new Set(
        channelTabsRef.current
          .map(
            (tab) =>
              tab.broadcasterId
          )
          .filter(
            (broadcasterId) =>
              broadcasterId &&
              !broadcasterId.startsWith(
                "cached:"
              )
          )
      );

    return Array.from(
      new Set(
        Object.entries(
          sevenTvChannelSetIdsRef.current
        )
          .filter(
            ([broadcasterId, setId]) =>
              openBroadcasterIds.has(
                broadcasterId
              ) &&
              Boolean(setId)
          )
          .map(([, setId]) => setId)
      )
    );
  }

  function subscribeSevenTvEventSet(
    socket: WebSocket,
    setId: string
  ) {
    if (
      !setId ||
      socket.readyState !==
        WebSocket.OPEN ||
      sevenTvEventSubscribedSetIdsRef.current.has(
        setId
      )
    ) {
      return;
    }

    socket.send(
      JSON.stringify({
        op: 35,
        d: {
          type: "emote_set.update",
          condition: {
            object_id: setId,
          },
        },
      })
    );

    sevenTvEventSubscribedSetIdsRef.current.add(
      setId
    );
  }

  function queueSevenTvChannelReload(
    broadcasterId: string
  ) {
    if (!broadcasterId) {
      return;
    }

    const existing =
      sevenTvReloadTimersRef.current[
        broadcasterId
      ];

    if (existing) {
      window.clearTimeout(existing);
    }

    sevenTvReloadTimersRef.current[
      broadcasterId
    ] = window.setTimeout(
      () => {
        delete sevenTvReloadTimersRef.current[
          broadcasterId
        ];

        void loadSevenTvChannelEmotes(
          broadcasterId,
          true
        );
      },
      350
    );
  }

  function stopSevenTvLiveSync() {
    sevenTvEventWantedRef.current = false;
    sevenTvEventGenerationRef.current += 1;

    clearSevenTvEventHeartbeatTimer();
    clearSevenTvEventReconnectTimer();

    sevenTvEventSubscribedSetIdsRef.current.clear();

    for (
      const timer of Object.values(
        sevenTvReloadTimersRef.current
      )
    ) {
      window.clearTimeout(timer);
    }

    sevenTvReloadTimersRef.current = {};

    const socket =
      sevenTvEventSocketRef.current;

    sevenTvEventSocketRef.current = null;

    if (socket) {
      try {
        socket.close();
      } catch {
        // ignore
      }
    }

    setSevenTvLiveSyncStatus("idle");
  }

  function scheduleSevenTvLiveReconnect(
    generation: number,
    minimumDelay = 0
  ) {
    if (
      !sevenTvEventWantedRef.current ||
      generation !==
        sevenTvEventGenerationRef.current ||
      sevenTvEventReconnectTimerRef.current !==
        null
    ) {
      return;
    }

    const delay = Math.max(
      minimumDelay,
      Math.min(
        1000 *
          Math.pow(
            2,
            sevenTvEventReconnectAttemptRef.current
          ),
        30000
      )
    );

    sevenTvEventReconnectAttemptRef.current += 1;
    setSevenTvLiveSyncStatus("connecting");

    sevenTvEventReconnectTimerRef.current =
      window.setTimeout(
        () => {
          sevenTvEventReconnectTimerRef.current =
            null;

          connectSevenTvLiveSocket(generation);
        },
        delay
      );
  }

  function connectSevenTvLiveSocket(
    generation: number
  ) {
    if (
      !sevenTvEventWantedRef.current ||
      generation !==
        sevenTvEventGenerationRef.current
    ) {
      return;
    }

    const setIds = openSevenTvSetIds();

    if (setIds.length === 0) {
      setSevenTvLiveSyncStatus("idle");
      return;
    }

    clearSevenTvEventReconnectTimer();
    setSevenTvLiveSyncStatus("connecting");
    sevenTvEventSubscribedSetIdsRef.current.clear();

    const socket =
      new WebSocket(
        SEVENTV_EVENT_API_URL
      );

    sevenTvEventSocketRef.current = socket;

    socket.onmessage = (event) => {
      if (
        generation !==
          sevenTvEventGenerationRef.current ||
        sevenTvEventSocketRef.current !==
          socket
      ) {
        return;
      }

      try {
        const message = JSON.parse(
          String(event.data)
        );

        const op = Number(message?.op);

        if (op === 1) {
          sevenTvEventReconnectAttemptRef.current = 0;
          setSevenTvLiveSyncStatus("live");

          armSevenTvEventHeartbeatWatchdog(
            socket,
            Number(
              message?.d?.heartbeat_interval
            )
          );

          for (
            const setId of openSevenTvSetIds()
          ) {
            subscribeSevenTvEventSet(
              socket,
              setId
            );
          }

          return;
        }

        if (op === 2) {
          armSevenTvEventHeartbeatWatchdog(
            socket
          );
          return;
        }

        if (
          op === 0 &&
          message?.d?.type ===
            "emote_set.update"
        ) {
          armSevenTvEventHeartbeatWatchdog(
            socket
          );

          const setId = String(
            message?.d?.body?.id || ""
          );

          const broadcasterId =
            sevenTvSetChannelIdsRef.current[
              setId
            ];

          if (broadcasterId) {
            queueSevenTvChannelReload(
              broadcasterId
            );
          }

          return;
        }

        if (op === 4 || op === 7) {
          try {
            socket.close();
          } catch {
            // reconnect skjer i onclose
          }
          return;
        }

        if (op === 6) {
          console.error(
            "7TV EventAPI error:",
            message?.d || message
          );
        }
      } catch (error) {
        console.error(
          "Kunne ikke lese 7TV live-event:",
          error
        );
      }
    };

    socket.onerror = () => {
      if (
        generation ===
          sevenTvEventGenerationRef.current
      ) {
        setSevenTvLiveSyncStatus("error");
      }
    };

    socket.onclose = (event) => {
      if (
        sevenTvEventSocketRef.current ===
        socket
      ) {
        sevenTvEventSocketRef.current = null;
      }

      clearSevenTvEventHeartbeatTimer();
      sevenTvEventSubscribedSetIdsRef.current.clear();

      if (
        !sevenTvEventWantedRef.current ||
        generation !==
          sevenTvEventGenerationRef.current
      ) {
        return;
      }

      setSevenTvLiveSyncStatus("connecting");

      scheduleSevenTvLiveReconnect(
        generation,
        event.code === 4007
          ? 5 * 60 * 1000
          : 0
      );
    };
  }

  function startSevenTvLiveSync() {
    stopSevenTvLiveSync();

    const setIds = openSevenTvSetIds();

    if (setIds.length === 0) {
      return;
    }

    sevenTvEventWantedRef.current = true;
    sevenTvEventReconnectAttemptRef.current = 0;

    const generation =
      sevenTvEventGenerationRef.current;

    connectSevenTvLiveSocket(generation);
  }

  async function loadSevenTvGlobalEmotes(
    force = false
  ) {
    const key =
      "7tv:global";

    if (
      !force &&
      shouldUseThirdPartyCache(
        key
      )
    ) {
      return;
    }

    setSevenTvStatus(
      "loading"
    );

    return runThirdPartyEmoteRequest(
      key,
      async () => {
        try {
          const payload =
            await fetchPublicJson([
              "https://7tv.io/v3/emote-sets/global",
              "https://api.7tv.app/v3/emote-sets/global",
            ]);

          sevenTvGlobalEmotesRef.current =
            sevenTvPayloadToEmotes(
              payload
            );

          thirdPartyEmoteLoadedAtRef.current[
            key
          ] =
            Date.now();

          setSevenTvStatus(
            "ready"
          );

          bumpThirdPartyEmotes();
        } catch (
          error
        ) {
          console.error(
            "Kunne ikke laste globale 7TV-emotes:",
            error
          );

          setSevenTvStatus(
            "error"
          );
        }
      }
    );
  }

  async function loadSevenTvChannelEmotes(
    broadcasterId:
      string,
    force = false
  ) {
    if (
      !broadcasterId ||
      broadcasterId.startsWith(
        "cached:"
      )
    ) {
      return;
    }

    const key =
      `7tv:channel:${broadcasterId}`;

    if (
      !force &&
      shouldUseThirdPartyCache(
        key
      )
    ) {
      return;
    }

    setSevenTvStatus(
      "loading"
    );

    return runThirdPartyEmoteRequest(
      key,
      async () => {
        try {
          const payload =
            await fetchPublicJson(
              [
                `https://7tv.io/v3/users/twitch/${encodeURIComponent(
                  broadcasterId
                )}`,
                `https://api.7tv.app/v3/users/twitch/${encodeURIComponent(
                  broadcasterId
                )}`,
              ],
              true
            );

          const previousMap =
            sevenTvChannelEmotesRef.current[
              broadcasterId
            ] || {};

          const hadPreviousLoad = Boolean(
            thirdPartyEmoteLoadedAtRef.current[
              key
            ]
          );

          const nextMap = payload
            ? sevenTvPayloadToEmotes(
                payload
              )
            : {};

          const now = Date.now();

          if (hadPreviousLoad) {
            let foundNew = false;

            for (
              const [name, emote]
              of Object.entries(nextMap)
            ) {
              const previous =
                previousMap[name];

              if (
                !previous ||
                previous.id !== emote.id
              ) {
                emote.newUntil =
                  now +
                  SEVENTV_NEW_EMOTE_DURATION_MS;
                foundNew = true;
              } else if (
                previous.newUntil &&
                previous.newUntil > now
              ) {
                emote.newUntil =
                  previous.newUntil;
              }
            }

            if (foundNew) {
              window.setTimeout(
                () => bumpThirdPartyEmotes(),
                SEVENTV_NEW_EMOTE_DURATION_MS +
                  1000
              );
            }
          }

          sevenTvChannelEmotesRef.current = {
            ...sevenTvChannelEmotesRef.current,
            [broadcasterId]: nextMap,
          };

          const set =
            payload?.emote_set || payload;

          const setId = String(
            set?.id || ""
          );

          const previousSetId =
            sevenTvChannelSetIdsRef.current[
              broadcasterId
            ];

          if (
            previousSetId &&
            previousSetId !== setId
          ) {
            delete sevenTvSetChannelIdsRef.current[
              previousSetId
            ];
          }

          if (setId) {
            sevenTvChannelSetIdsRef.current = {
              ...sevenTvChannelSetIdsRef.current,
              [broadcasterId]: setId,
            };

            sevenTvSetChannelIdsRef.current = {
              ...sevenTvSetChannelIdsRef.current,
              [setId]: broadcasterId,
            };

            const liveSocket =
              sevenTvEventSocketRef.current;

            if (
              sevenTvEventWantedRef.current &&
              liveSocket?.readyState ===
                WebSocket.OPEN
            ) {
              subscribeSevenTvEventSet(
                liveSocket,
                setId
              );
            }
          } else {
            const {
              [broadcasterId]: _removed,
              ...remainingSetIds
            } =
              sevenTvChannelSetIdsRef.current;

            sevenTvChannelSetIdsRef.current =
              remainingSetIds;
          }

          thirdPartyEmoteLoadedAtRef.current[
            key
          ] = Date.now();

          setSevenTvStatus(
            "ready"
          );

          bumpThirdPartyEmotes();
        } catch (
          error
        ) {
          console.error(
            `Kunne ikke laste 7TV-emotes for ${broadcasterId}:`,
            error
          );

          setSevenTvStatus(
            "error"
          );
        }
      }
    );
  }

