  function twitchPickerImageUrl(
    emote:
      TwitchPickerApiEmote
  ) {
    const format =
      animatedEmotesEnabled &&
      emote.format
        ?.includes(
          "animated"
        )
        ? "animated"
        : "static";

    return (
      "https://static-cdn.jtvnw.net/emoticons/v2/" +
      `${emote.id}/${format}/dark/2.0`
    );
  }

  async function loadTwitchPickerEmotes(
    broadcasterId:
      string,
    force = false
  ) {
    if (
      !twitchAccessTokenRef.current ||
      !broadcasterId ||
      broadcasterId.startsWith(
        "cached:"
      )
    ) {
      return;
    }

    if (
      !force &&
      twitchPickerGlobalLoadedRef.current &&
      twitchPickerLoadedChannelRef.current ===
        broadcasterId
    ) {
      return;
    }

    setTwitchPickerStatus(
      "loading"
    );

    try {
      const headers = {
        Authorization:
          `Bearer ${twitchAccessTokenRef.current}`,

        "Client-Id":
          TWITCH_CLIENT_ID,
      };

      const globalPromise =
        twitchPickerGlobalLoadedRef.current &&
        !force
          ? Promise.resolve(
              null
            )
          : fetch(
              "https://api.twitch.tv/helix/chat/emotes/global",
              {
                headers,
              }
            );

      const channelPromise =
        fetch(
          "https://api.twitch.tv/helix/chat/emotes?broadcaster_id=" +
            encodeURIComponent(
              broadcasterId
            ),
          {
            headers,
          }
        );

      const [
        globalResponse,
        channelResponse,
      ] =
        await Promise.all([
          globalPromise,
          channelPromise,
        ]);

      if (
        globalResponse
      ) {
        if (
          !globalResponse.ok
        ) {
          throw new Error(
            await globalResponse.text()
          );
        }

        const globalData =
          (
            await globalResponse.json()
          ) as TwitchPickerApiResponse;

        setTwitchPickerGlobalEmotes(
          Array.isArray(
            globalData.data
          )
            ? globalData.data
            : []
        );

        twitchPickerGlobalLoadedRef.current =
          true;
      }

      if (
        !channelResponse.ok
      ) {
        throw new Error(
          await channelResponse.text()
        );
      }

      const channelData =
        (
          await channelResponse.json()
        ) as TwitchPickerApiResponse;

      setTwitchPickerChannelEmotes(
        Array.isArray(
          channelData.data
        )
          ? channelData.data
          : []
      );

      twitchPickerLoadedChannelRef.current =
        broadcasterId;

      setTwitchPickerStatus(
        "ready"
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke laste Twitch-emotes til picker:",
        error
      );

      setTwitchPickerStatus(
        "error"
      );
    }
  }

  function saveRecentEmotes(
    emotes:
      PickerEmote[]
  ) {
    const next =
      emotes.slice(
        0,
        30
      );

    setRecentEmotes(
      next
    );

    localStorage.setItem(
      RECENT_EMOTES_KEY,
      JSON.stringify(
        next
      )
    );
  }

  function rememberRecentEmote(
    emote:
      PickerEmote
  ) {
    const key =
      `${emote.provider}:${emote.id}:${emote.name}`;

    saveRecentEmotes([
      emote,
      ...recentEmotes.filter(
        (
          item
        ) =>
          `${item.provider}:${item.id}:${item.name}` !==
          key
      ),
    ]);
  }

  function insertEmoteIntoInput(
    emote:
      PickerEmote
  ) {
    const input =
      chatInputRef.current;

    const selectionStart =
      input?.selectionStart ??
      chatInput.length;

    const selectionEnd =
      input?.selectionEnd ??
      selectionStart;

    const before =
      chatInput.slice(
        0,
        selectionStart
      );

    const after =
      chatInput.slice(
        selectionEnd
      );

    const prefix =
      before &&
      !/\s$/.test(
        before
      )
        ? " "
        : "";

    const suffix =
      after &&
      /^\s/.test(
        after
      )
        ? ""
        : " ";

    const insertion =
      `${prefix}${emote.name}${suffix}`;

    const nextValue =
      before +
      insertion +
      after;

    const nextCursor =
      before.length +
      insertion.length;

    setChatInput(
      nextValue
    );

    setChatCursorPosition(
      nextCursor
    );

    setEmoteAutocompleteIndex(
      0
    );

    setEmoteAutocompleteDismissed(
      false
    );

    rememberRecentEmote(
      emote
    );

    window.requestAnimationFrame(
      () => {
        chatInputRef.current
          ?.focus();

        chatInputRef.current
          ?.setSelectionRange(
            nextCursor,
            nextCursor
          );
      }
    );
  }

  function pickerProviderEnabled(
    provider:
      PickerEmoteProvider
  ) {
    if (
      provider ===
      "twitch"
    ) {
      return twitchEmotesEnabled;
    }

    if (
      provider ===
      "7tv"
    ) {
      return sevenTvEmotesEnabled;
    }

    return bttvEmotesEnabled;
  }

  function thirdPartyPickerEmotes(
    map:
      ThirdPartyEmoteMap,
    scope:
      PickerEmoteScope
  ): PickerEmote[] {
    return Object.values(
      map
    )
      .filter(
        (
          emote
        ) =>
          !emote.animated ||
          animatedEmotesEnabled
      )
      .map(
        (
          emote
        ) => ({
          provider:
            emote.provider,

          id:
            emote.id,

          name:
            emote.name,

          imageUrl:
            emote.imageUrl,

          animated:
            emote.animated,

          scope,

          newUntil:
            emote.newUntil,
        })
      );
  }

  function twitchPickerEmotes(
    emotes:
      TwitchPickerApiEmote[],
    scope:
      PickerEmoteScope
  ): PickerEmote[] {
    return emotes.map(
      (
        emote
      ) => ({
        provider:
          "twitch",

        id:
          emote.id,

        name:
          emote.name,

        imageUrl:
          twitchPickerImageUrl(
            emote
          ),

        animated:
          Boolean(
            emote.format
              ?.includes(
                "animated"
              )
          ),

        scope,
      })
    );
  }

  function filteredPickerEmotes(
    emotes:
      PickerEmote[]
  ) {
    const query =
      emoteSearch
        .trim()
        .toLowerCase();

    return emotes
      .filter(
        (
          emote
        ) =>
          pickerProviderEnabled(
            emote.provider
          ) &&
          (
            animatedEmotesEnabled ||
            !emote.animated ||
            emote.provider ===
              "twitch"
          ) &&
          (
            !query ||
            emote.name
              .toLowerCase()
              .includes(
                query
              )
          )
      )
      .slice(
        0,
        180
      );
  }

  function pickerProviderLabel(
    provider:
      PickerEmoteProvider
  ) {
    if (
      provider ===
      "twitch"
    ) {
      return "Twitch";
    }

    if (
      provider ===
      "7tv"
    ) {
      return "7TV";
    }

    return "BetterTTV";
  }

  function pickerProviderBadge(
    provider:
      PickerEmoteProvider
  ) {
    if (
      provider ===
      "twitch"
    ) {
      return "T";
    }

    if (
      provider ===
      "7tv"
    ) {
      return "7TV";
    }

    return "BTTV";
  }

