  function activePickerEmotesForAutocomplete():
    PickerEmote[] {
    if (
      !activeTab
    ) {
      return [];
    }

    const broadcasterId =
      activeTab.broadcasterId;

    const emotes:
      PickerEmote[] = [];

    if (
      twitchEmotesEnabled
    ) {
      emotes.push(
        ...twitchPickerEmotes(
          twitchPickerChannelEmotes,
          "channel"
        ),

        ...twitchPickerEmotes(
          twitchPickerGlobalEmotes,
          "global"
        )
      );
    }

    if (
      sevenTvEmotesEnabled
    ) {
      emotes.push(
        ...thirdPartyPickerEmotes(
          sevenTvChannelEmotesRef.current[
            broadcasterId
          ] ||
            {},
          "channel"
        ),

        ...thirdPartyPickerEmotes(
          sevenTvGlobalEmotesRef.current,
          "global"
        )
      );
    }

    if (
      bttvEmotesEnabled
    ) {
      emotes.push(
        ...thirdPartyPickerEmotes(
          bttvChannelEmotesRef.current[
            broadcasterId
          ] ||
            {},
          "channel"
        ),

        ...thirdPartyPickerEmotes(
          bttvGlobalEmotesRef.current,
          "global"
        )
      );
    }

    const seen =
      new Set<
        string
      >();

    return emotes.filter(
      (
        emote
      ) => {
        const key =
          `${emote.provider}:${emote.id}:${emote.name}`;

        if (
          seen.has(
            key
          )
        ) {
          return false;
        }

        seen.add(
          key
        );

        return true;
      }
    );
  }

  function getEmoteAutocompleteContext() {
    if (
      !activeTab ||
      showEmotePicker ||
      !connectionOnline ||
      !chatInput
    ) {
      return null;
    }

    const cursor =
      Math.max(
        0,
        Math.min(
          chatCursorPosition,
          chatInput.length
        )
      );

    const beforeCursor =
      chatInput.slice(
        0,
        cursor
      );

    const match =
      /(^|\s)([^\s]*)$/.exec(
        beforeCursor
      );

    if (
      !match
    ) {
      return null;
    }

    const rawToken =
      match[
        2
      ];

    if (
      !rawToken ||
      rawToken.startsWith(
        "@"
      ) ||
      rawToken.startsWith(
        "/"
      )
    ) {
      return null;
    }

    const colonTriggered =
      rawToken.startsWith(
        ":"
      );

    const query =
      (
        colonTriggered
          ? rawToken.slice(
              1
            )
          : rawToken
      )
        .trim()
        .toLowerCase();

    // Keep common ASCII faces such as :D and :P as plain chat text. A
    // one-letter colon query otherwise opens an emote list (often with a
    // code such as D:) over the composer.
    if (
      colonTriggered &&
      query.length < 2
    ) {
      return null;
    }

    if (
      (
        colonTriggered &&
        query.length <
          1
      ) ||
      (
        !colonTriggered &&
        query.length <
          2
      ) ||
      query.includes(
        ":"
      )
    ) {
      return null;
    }

    const tokenStart =
      cursor -
      rawToken.length;

    return {
      start:
        tokenStart,

      end:
        cursor,

      query,

      rawToken,

      colonTriggered,
    };
  }

  function getEmoteAutocompleteResults() {
    const context =
      getEmoteAutocompleteContext();

    if (
      !context
    ) {
      return [];
    }

    const recentRank =
      new Map<
        string,
        number
      >();

    recentEmotes.forEach(
      (
        emote,
        index
      ) => {
        recentRank.set(
          `${emote.provider}:${emote.id}:${emote.name}`,
          index
        );
      }
    );

    const query =
      context.query;

    return activePickerEmotesForAutocomplete()
      .filter(
        (
          emote
        ) =>
          emote.name
            .toLowerCase()
            .includes(
              query
            )
      )
      .sort(
        (
          a,
          b
        ) => {
          const aName =
            a.name.toLowerCase();

          const bName =
            b.name.toLowerCase();

          const aRecent =
            recentRank.get(
              `${a.provider}:${a.id}:${a.name}`
            );

          const bRecent =
            recentRank.get(
              `${b.provider}:${b.id}:${b.name}`
            );

          const score =
            (
              emote:
                PickerEmote,
              name:
                string,
              recent:
                number | undefined
            ) => {
              let value =
                0;

              if (
                name ===
                query
              ) {
                value -=
                  10000;
              } else if (
                name.startsWith(
                  query
                )
              ) {
                value -=
                  2500;
              } else {
                value -=
                  500;
              }

              if (
                emote.scope ===
                "channel"
              ) {
                value -=
                  1700;
              }

              if (
                recent !==
                undefined
              ) {
                value -=
                  Math.max(
                    0,
                    900 -
                      recent *
                        25
                  );
              }

              value +=
                Math.min(
                  80,
                  name.length
                );

              return value;
            };

          const difference =
            score(
              a,
              aName,
              aRecent
            ) -
            score(
              b,
              bName,
              bRecent
            );

          if (
            difference !==
            0
          ) {
            return difference;
          }

          return aName.localeCompare(
            bName
          );
        }
      )
      .slice(
        0,
        8
      );
  }

  function insertAutocompleteEmote(
    emote:
      PickerEmote
  ) {
    const context =
      getEmoteAutocompleteContext();

    if (
      !context
    ) {
      return;
    }

    const before =
      chatInput.slice(
        0,
        context.start
      );

    const after =
      chatInput.slice(
        context.end
      );

    const suffix =
      after &&
      /^\s/.test(
        after
      )
        ? ""
        : " ";

    const insertion =
      `${emote.name}${suffix}`;

    const nextValue =
      before +
      insertion +
      after;

    const nextCursor =
      before.length +
      insertion.length;

    setChatInput(
      nextValue
    );

    setChatCursorPosition(
      nextCursor
    );

    setEmoteAutocompleteIndex(
      0
    );

    setEmoteAutocompleteDismissed(
      true
    );

    rememberRecentEmote(
      emote
    );

    window.requestAnimationFrame(
      () => {
        chatInputRef.current
          ?.focus();

        chatInputRef.current
          ?.setSelectionRange(
            nextCursor,
            nextCursor
          );
      }
    );
  }

