  function getThirdPartyEmote(
    name: string,
    broadcasterId:
      string
  ) {
    if (
      sevenTvEmotesEnabled
    ) {
      const channelEmote =
        sevenTvChannelEmotesRef.current[
          broadcasterId
        ]?.[
          name
        ];

      if (
        channelEmote
      ) {
        return channelEmote;
      }
    }

    if (
      bttvEmotesEnabled
    ) {
      const channelEmote =
        bttvChannelEmotesRef.current[
          broadcasterId
        ]?.[
          name
        ];

      if (
        channelEmote
      ) {
        return channelEmote;
      }
    }

    if (
      sevenTvEmotesEnabled
    ) {
      const globalEmote =
        sevenTvGlobalEmotesRef.current[
          name
        ];

      if (
        globalEmote
      ) {
        return globalEmote;
      }
    }

    if (
      bttvEmotesEnabled
    ) {
      return (
        bttvGlobalEmotesRef.current[
          name
        ] ||
        null
      );
    }

    return null;
  }

  function renderThirdPartyText(
    text: string,
    keyBase: string,
    broadcasterId:
      string
  ) {
    return text
      .split(
        /(\s+)/
      )
      .map(
        (
          part,
          partIndex
        ) => {
          if (
            !part ||
            /^\s+$/.test(
              part
            )
          ) {
            return (
              <span
                key={`${keyBase}-space-${partIndex}`}
                style={{
                  whiteSpace: "pre",
                }}
              >
                {part}
              </span>
            );
          }

          const linkMatch =
            part.match(
              /^((?:https?:\/\/|www\.)[^\s]+?)([.,!?;:)}\]]*)$/i
            );

          if (linkMatch) {
            const linkText =
              linkMatch[1];
            const trailingText =
              linkMatch[2] || "";
            const linkUrl =
              linkText
                .toLowerCase()
                .startsWith("www.")
                ? `https://${linkText}`
                : linkText;

            return (
              <span
                key={`${keyBase}-link-wrap-${partIndex}`}
              >
                <span
                  role="link"
                  tabIndex={0}
                  title={ui("Hold Ctrl og klikk for å åpne lenken", "Hold Ctrl and click to open the link")}
                  onClick={(event) => {
                    event.stopPropagation();

                    if (
                      !event.ctrlKey &&
                      !event.metaKey
                    ) {
                      setTwitchError(
                        ui(
                          "Hold Ctrl og klikk for å åpne lenken.",
                          "Hold Ctrl and click to open the link."
                        )
                      );
                      return;
                    }

                    void openUrl(linkUrl);
                  }}
                  onKeyDown={(event) => {
                    if (
                      event.key === "Enter" &&
                      (event.ctrlKey ||
                        event.metaKey)
                    ) {
                      event.preventDefault();
                      void openUrl(linkUrl);
                    }
                  }}
                  style={{
                    color: "#6db7ff",
                    textDecoration: "underline",
                    textDecorationThickness: "1px",
                    textUnderlineOffset: "2px",
                    cursor: "pointer",
                    overflowWrap: "anywhere",
                  }}
                >
                  {linkText}
                </span>
                {trailingText}
              </span>
            );
          }

          const plainTextEmoticon = new Set([
            ":D",
            ":d",
            ":P",
            ":p",
            ":O",
            ":o",
            ":)",
            ":(",
            ":-D",
            ":-d",
            ":-P",
            ":-p",
            ";)",
            ";(",
          ]).has(part);
          const emote = plainTextEmoticon
            ? null
            : getThirdPartyEmote(
                part,
                broadcasterId
              );

          if (
            !emote ||
            (
              emote.animated &&
              !animatedEmotesEnabled
            )
          ) {
            return (
              <span
                key={`${keyBase}-text-${partIndex}`}
              >
                {part}
              </span>
            );
          }

          return (
            <img
              key={`${keyBase}-${emote.provider}-${emote.id}-${partIndex}`}
              src={
                emote.imageUrl
              }
              alt={
                emote.name
              }
              title={`${emote.name} · ${
                emote.provider ===
                "7tv"
                  ? "7TV"
                  : "BetterTTV"
              }`}
              loading="lazy"
              style={{
                height:
                  Math.max(
                    26,
                    chatFontSize +
                      15
                  ),

                maxWidth:
                  140,

                objectFit:
                  "contain",

                verticalAlign:
                  "middle",

                margin:
                  "-3px 2px",

                filter:
                  "drop-shadow(0 1px 1px rgba(0,0,0,.35))",
              }}
            />
          );
        }
      );
  }

  function getTwitchEmoteUrl(
    emote:
      TwitchEmoteInfo
  ) {
    const format =
      animatedEmotesEnabled &&
      emote.format
        ?.includes(
          "animated"
        )
        ? "animated"
        : "static";

    return (
      "https://static-cdn.jtvnw.net/emoticons/v2/" +
      `${emote.id}/${format}/dark/2.0`
    );
  }

  function badgeSetsToMap(
    sets:
      TwitchBadgeSet[]
  ) {
    const map:
      Record<
        string,
        BadgeLookupItem
      > = {};

    for (
      const set
      of sets
    ) {
      for (
        const version
        of set.versions
      ) {
        map[
          `${set.set_id}:${version.id}`
        ] = {
          imageUrl:
            version.image_url_2x,

          title:
            version.title,
        };
      }
    }

    return map;
  }

  function resolveBadges(
    broadcasterId:
      string,

    badges?:
      TwitchBadgeFromMessage[]
  ):
    ResolvedBadge[] {
    if (
      !badges
    ) {
      return [];
    }

    const map =
      channelBadgeMaps.current[
        broadcasterId
      ] ||
      globalBadgeMap.current;

    return badges.map(
      (
        badge
      ) => {
        const info =
          map[
            `${badge.set_id}:${badge.id}`
          ];

        return {
          setId:
            badge.set_id,

          id:
            badge.id,

          info:
            badge.info,

          imageUrl:
            info
              ?.imageUrl ||
            "",

          title:
            info
              ?.title ||
            badge.set_id,
        };
      }
    );
  }

  async function getLoggedInTwitchUser(
    accessToken:
      string
  ):
    Promise<
      TwitchUser
    > {
    const response =
      await fetch(
        "https://api.twitch.tv/helix/users",
        {
          headers: {
            Authorization:
              `Bearer ${accessToken}`,

            "Client-Id":
              TWITCH_CLIENT_ID,
          },
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        await response.text()
      );
    }

    const data =
      (
        await response.json()
      ) as TwitchUsersResponse;

    if (
      !data.data
        ?.length
    ) {
      throw new Error(
        ui("Twitch returnerte ingen bruker.", "Twitch did not return a user.")
      );
    }

    return data.data[
      0
    ];
  }

  async function getTwitchUserByLogin(
    login:
      string
  ):
    Promise<
      TwitchUser
    > {
    const response =
      await fetch(
        "https://api.twitch.tv/helix/users?login=" +
          encodeURIComponent(
            login
          ),
        {
          headers: {
            Authorization:
              `Bearer ${twitchAccessTokenRef.current}`,

            "Client-Id":
              TWITCH_CLIENT_ID,
          },
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui("Kunne ikke finne Twitch-brukeren.", "Could not find the Twitch user.")
      );
    }

    const data =
      (
        await response.json()
      ) as TwitchUsersResponse;

    if (
      !data.data
        ?.length
    ) {
      throw new Error(
        ui(`Fant ingen Twitch-bruker som heter «${login}».`, `No Twitch user named "${login}" was found.`)
      );
    }

    return data.data[
      0
    ];
  }

