  async function loadGlobalBadges(
    accessToken:
      string
  ) {
    const response =
      await fetch(
        "https://api.twitch.tv/helix/chat/badges/global",
        {
          headers: {
            Authorization:
              `Bearer ${accessToken}`,

            "Client-Id":
              TWITCH_CLIENT_ID,
          },
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui("Kunne ikke hente globale Twitch-merker.", "Could not load global Twitch badges.")
      );
    }

    const data =
      (
        await response.json()
      ) as TwitchBadgeApiResponse;

    globalBadgeMap.current =
      badgeSetsToMap(
        data.data
      );
  }

  async function loadChannelBadges(
    broadcasterId:
      string
  ) {
    const response =
      await fetch(
        "https://api.twitch.tv/helix/chat/badges?broadcaster_id=" +
          encodeURIComponent(
            broadcasterId
          ),
        {
          headers: {
            Authorization:
              `Bearer ${twitchAccessTokenRef.current}`,

            "Client-Id":
              TWITCH_CLIENT_ID,
          },
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui("Kunne ikke hente kanalens merker.", "Could not load the channel badges.")
      );
    }

    const data =
      (
        await response.json()
      ) as TwitchBadgeApiResponse;

    channelBadgeMaps.current[
      broadcasterId
    ] = {
      ...globalBadgeMap.current,

      ...badgeSetsToMap(
        data.data
      ),
    };
  }

