  function clearKeepaliveTimer() {
    if (
      keepaliveTimer.current !==
      null
    ) {
      window.clearTimeout(
        keepaliveTimer.current
      );
    }

    keepaliveTimer.current =
      null;
  }

  function clearReconnectTimer() {
    if (
      reconnectTimer.current !==
      null
    ) {
      window.clearTimeout(
        reconnectTimer.current
      );
    }

    reconnectTimer.current =
      null;
  }

  function armKeepaliveWatchdog(
    socket:
      WebSocket,

    timeoutSeconds?:
      number
  ) {
    if (
      typeof timeoutSeconds ===
        "number" &&
      Number.isFinite(
        timeoutSeconds
      ) &&
      timeoutSeconds >
        0
    ) {
      keepaliveTimeoutMs.current =
        timeoutSeconds *
          1000 +
        1500;
    }

    clearKeepaliveTimer();

    keepaliveTimer.current =
      window.setTimeout(
        () => {
          keepaliveTimer.current =
            null;

          if (
            shouldReconnect.current &&
            twitchSocket.current ===
              socket &&
            hasTrackedTwitchTabs()
          ) {
            beginConnectionLoss(
              socket
            );
          }
        },
        keepaliveTimeoutMs.current
      );
  }

  function markSocketDisconnected() {
    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            tab
          ) =>
            (tab.platform ||
              "twitch") ===
              "twitch" &&
            tab.isLive &&
            (
              tab.status ===
                "live" ||
              tab.status ===
                "joining"
            )
              ? {
                  ...tab,

                  status:
                    "disconnected",

                  error:
                    "",
                }
              : tab
        )
    );
  }

  function markChannelsJoining() {
    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            tab
          ) =>
            (tab.platform ||
              "twitch") ===
                "twitch" &&
            tab.isLive
              ? {
                  ...tab,

                  status:
                    "joining",

                  error:
                    "",
                }
              : tab
        )
    );
  }

  function hasTrackedTwitchTabs() {
    return Boolean(
      twitchAccessTokenRef.current &&
      twitchUserIdRef.current
    ) ||
      channelTabsRef.current.some(
        (tab) =>
          (tab.platform ||
            "twitch") ===
            "twitch" &&
          Boolean(
            tab.broadcasterId
          ) &&
          !tab.broadcasterId.startsWith(
            "cached:"
          )
      );
  }

  function beginConnectionLoss(
    socket?:
      WebSocket
  ) {
    if (
      !shouldReconnect.current ||
      !hasTrackedTwitchTabs()
    ) {
      return;
    }

    setSocketHealthy(
      false
    );

    setReconnectingChat(
      true
    );

    markSocketDisconnected();

    if (
      !initialStartupRef.current
    ) {
      announceConnectionLost();
    }

    clearKeepaliveTimer();

    subscribedChannelIds.current
      .clear();

    twitchSubscriptionIds.current
      .clear();

    twitchSessionId.current =
      "";

    socketConnectPromise.current =
      null;

    const target =
      socket ||
      twitchSocket.current;

    if (
      !socket ||
      twitchSocket.current ===
        socket
    ) {
      twitchSocket.current =
        null;
    }

    try {
      target
        ?.close();
    } catch {
      // ignore
    }

    scheduleSocketReconnect();
  }

  function scheduleSocketReconnect() {
    if (
      !shouldReconnect.current ||
      reconnectTimer.current !==
        null ||
      !hasTrackedTwitchTabs()
    ) {
      return;
    }

    if (!navigator.onLine) {
      setSocketHealthy(
        false
      );
      setReconnectingChat(
        true
      );
      return;
    }

    const delay =
      Math.min(
        1000 *
          Math.pow(
            2,
            reconnectAttempt.current
          ),
        30000
      );

    reconnectAttempt.current +=
      1;

    setSocketHealthy(
      false
    );

    setReconnectingChat(
      true
    );

    reconnectTimer.current =
      window.setTimeout(
        () => {
          reconnectTimer.current =
            null;

          void reconnectAllChannels();
        },
        delay
      );
  }

  async function reconnectAllChannels() {
    if (
      !shouldReconnect.current ||
      reconnectInProgress.current ||
      !hasTrackedTwitchTabs() ||
      !twitchAccessTokenRef.current ||
      !twitchUserIdRef.current
    ) {
      return;
    }

    reconnectInProgress.current =
      true;

    setSocketHealthy(
      false
    );

    setReconnectingChat(
      true
    );

    markChannelsJoining();

    try {
      const sessionId =
        await ensureTwitchSocket();

      try {
        await createTwitchWhisperSubscription(
          sessionId
        );
      } catch (error) {
        console.warn(
          "Twitch whisper subscription:",
          error
        );
      }

      announceConnectionRestored();

      for (
        const tab
        of [
          ...channelTabsRef.current,
        ].filter(
          (item) =>
            (item.platform ||
              "twitch") ===
              "twitch" &&
            Boolean(
              item.broadcasterId
            ) &&
            !item.broadcasterId.startsWith(
              "cached:"
            )
        )
      ) {
        if (
          !shouldReconnect.current
        ) {
          break;
        }

        await createChatSubscription(
          sessionId,
          tab.broadcasterId
        );

        updateTabs(
          (
            tabs
          ) =>
            tabs.map(
              (
                item
              ) =>
                item.broadcasterId ===
                tab.broadcasterId
                  ? {
                      ...item,

                      status:
                        item.isLive
                          ? "live"
                          : "disconnected",

                      error:
                        "",
                    }
                  : item
            )
        );
      }

      reconnectAttempt.current =
        0;

      setSocketHealthy(
        true
      );

      setReconnectingChat(
        false
      );

      setHadChatConnection(
        true
      );

      void refreshLiveStatuses();
    } catch (
      error
    ) {
      console.error(
        "Automatisk Twitch reconnect feilet:",
        error
      );

      markSocketDisconnected();

      scheduleSocketReconnect();
    } finally {
      reconnectInProgress.current =
        false;
    }
  }

  function processChatNotification(
    message: any
  ) {
    const metadataId =
      message
        ?.metadata
        ?.message_id;

    if (
      metadataId
    ) {
      if (
        processedEventIds.current
          .has(
            metadataId
          )
      ) {
        return;
      }

      processedEventIds.current
        .add(
          metadataId
        );

      if (
        processedEventIds.current
          .size >
        1000
      ) {
        const first =
          processedEventIds.current
            .values()
            .next()
            .value;

        if (
          first
        ) {
          processedEventIds.current
            .delete(
              first
            );
        }
      }
    }

    const event =
      message
        ?.payload
        ?.event;

    if (
      !event
    ) {
      return;
    }

    const broadcasterId =
      String(
        event.broadcaster_user_id ||
        ""
      );

    const channelTab =
      channelTabsRef.current
        .find(
          (
            tab
          ) =>
            tab.broadcasterId ===
            broadcasterId
        );

    if (
      !channelTab
    ) {
      return;
    }

    const fragments:
      TwitchMessageFragment[] =
      event.message
        ?.fragments ||
      [
        {
          type:
            "text",

          text:
            event.message
              ?.text ||
            "",
        },
      ];

    const authorUserId =
      String(
        event.chatter_user_id ||
        ""
      );

    const mentionedMe =
      messageMentionsMe(
        event,
        fragments
      ) &&
      !isUserIgnoredForHighlights(
        "twitch",
        authorUserId,
        String(event.chatter_user_login || "")
      );

    const isOwnMessage =
      authorUserId ===
      twitchUserIdRef.current;

    if (
      mentionedMe &&
      !isOwnMessage &&
      !isMentionSoundMuted(
        channelTab.login,
        channelTab.broadcasterId
      )
    ) {
      playMentionSound();
    }

    const parsedTimestamp =
      Date.parse(
        message
          ?.metadata
          ?.message_timestamp ||
          ""
      );

    const timestampMs =
      Number.isFinite(
        parsedTimestamp
      )
        ? parsedTimestamp
        : Date.now();

    const reply:
      TwitchReplyInfo | null =
      event.reply
        ? {
            parentMessageId:
              String(
                event.reply
                  .parent_message_id ||
                  ""
              ),

            parentMessageBody:
              String(
                event.reply
                  .parent_message_body ||
                  ""
              ),

            parentUserId:
              String(
                event.reply
                  .parent_user_id ||
                  ""
              ),

            parentUserName:
              String(
                event.reply
                  .parent_user_name ||
                  ""
              ),

            parentUserLogin:
              String(
                event.reply
                  .parent_user_login ||
                  ""
              ),

            threadMessageId:
              String(
                event.reply
                  .thread_message_id ||
                  ""
              ),

            threadUserId:
              String(
                event.reply
                  .thread_user_id ||
                  ""
              ),

            threadUserName:
              String(
                event.reply
                  .thread_user_name ||
                  ""
              ),

            threadUserLogin:
              String(
                event.reply
                  .thread_user_login ||
                  ""
              ),
          }
        : null;

    const newMessage:
      TwitchChatMessage = {
        id:
          event.message_id ||
          metadataId ||
          `chat-${timestampMs}-${Math.random()}`,

        kind:
          "chat",

        timestampMs,

        time:
          clockTime(
            timestampMs
          ),

        userId:
          authorUserId,

        userLogin:
          String(
            event.chatter_user_login ||
            ""
          ).toLowerCase(),

        username:
          String(
            event.chatter_user_name ||
            event.chatter_user_login ||
            "Ukjent"
          ),

        text:
          event.message
            ?.text ||
          "",

        color:
          event.color ||
          "#b784ff",

        badges:
          resolveBadges(
            broadcasterId,
            event.badges
          ),

        fragments,

        reply,

        platform:
          "twitch",
      };

    let didInsert =
      false;

    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            tab
          ) => {
            if (
              tab.broadcasterId !==
                broadcasterId
            ) {
              return tab;
            }

            const existingIndex =
              findAuthoritativeMessageMatch(
                tab.messages,
                newMessage
              );

            if (
              existingIndex >= 0
            ) {
              if (
                !tab.messages[
                  existingIndex
                ]?.optimistic
              ) {
                return tab;
              }

              didInsert =
                true;

              return {
                ...tab,
                messages:
                  tab.messages.map(
                    (
                      existing,
                      index
                    ) =>
                      index ===
                        existingIndex
                        ? newMessage
                        : existing
                  ),
                hasMention:
                  broadcasterId ===
                    activeChannelIdRef.current
                    ? false
                    : tab.hasMention ||
                      mentionedMe,
              };
            }

            didInsert =
              true;

            return {
              ...tab,

              messages: [
                ...tab.messages,
                newMessage,
              ],

              hasMention:
                broadcasterId ===
                activeChannelIdRef.current
                  ? false
                  : tab.hasMention ||
                    mentionedMe,
            };
          }
        )
    );

    if (
      didInsert
    ) {
      captureMention(
        channelTab,
        newMessage,
        isOwnMessage
      );

      saveMessageToDisk(
        channelTab.login,
        newMessage
      );
    }
  }

  function processTwitchWhisperNotification(
    notification: any
  ) {
    const event =
      notification?.payload?.event;
    const whisperId = String(
      event?.whisper_id ||
      notification?.metadata?.message_id ||
      ""
    );
    const text = String(
      event?.whisper?.text || ""
    );

    if (!whisperId || !text) {
      return;
    }

    const inboxId =
      `twitch:whisper:${whisperId}`;
    const timestampMs = Date.parse(
      notification?.metadata?.message_timestamp || ""
    ) || Date.now();
    const whisperMessage: TwitchChatMessage = {
      id: whisperId,
      kind: "chat",
      timestampMs,
      time: clockTime(timestampMs),
      userId: String(event?.from_user_id || ""),
      userLogin: String(event?.from_user_login || "").toLowerCase(),
      username: String(
        event?.from_user_name ||
        event?.from_user_login ||
        ui("Ukjent", "Unknown")
      ),
      text,
      color: "#b784ff",
      badges: [],
      fragments: [
        {
          type: "text",
          text,
        },
      ],
      platform: "twitch",
      eventType: "privateMessage",
    };

    if (
      messageIsLocallyIgnored(
        whisperMessage
      ) ||
      !mentionInboxEnabledRef.current
    ) {
      return;
    }

    setMentionInboxItems((current) => {
      if (
        current.some(
          (item) => item.id === inboxId
        )
      ) {
        return current;
      }

      const privateMessageItem: MentionInboxItem = {
        id: inboxId,
        channelId: "",
        channelLogin: "",
        channelDisplayName: ui(
          "Privat melding",
          "Private message"
        ),
        platform: "twitch",
        capturedAt: Date.now(),
        tags: ["private-message"],
        message: whisperMessage,
      };
      const next: MentionInboxItem[] = [
        ...current,
        privateMessageItem,
      ].slice(-MENTION_INBOX_MAX_ITEMS);

      writeSetting(
        MENTION_INBOX_ITEMS_KEY,
        next
      );
      return next;
    });

    playMentionSound();
  }

  function attachSocketHandlers(
    socket:
      WebSocket,

    welcomeCallback?:
      (
        sessionId:
          string
      ) =>
        void,

    failureCallback?:
      (
        message:
          string
      ) =>
        void,

    oldSocket?:
      WebSocket,

    serverReconnect =
      false
  ) {
    let receivedWelcome =
      false;

    socket.onmessage =
      (
        event
      ) => {
        try {
          const message =
            JSON.parse(
              event.data
            );

          const type =
            message
              ?.metadata
              ?.message_type;

          if (
            type ===
            "session_welcome"
          ) {
            receivedWelcome =
              true;

            const sessionId =
              message
                .payload
                .session
                .id;

            twitchSessionId.current =
              sessionId;

            twitchSocket.current =
              socket;

            armKeepaliveWatchdog(
              socket,
              message
                ?.payload
                ?.session
                ?.keepalive_timeout_seconds
            );

            setSocketHealthy(
              true
            );

            setHadChatConnection(
              true
            );

            reconnectAttempt.current =
              0;

            if (
              oldSocket &&
              oldSocket !==
                socket
            ) {
              oldSocket.close();
            }

            if (
              serverReconnect
            ) {
              updateTabs(
                (
                  tabs
                ) =>
                  tabs.map(
                    (
                      tab
                    ) => ({
                      ...tab,

                      status:
                        "live",

                      error:
                        "",
                    })
                  )
              );

              if (
                !initialStartupRef.current
              ) {
                announceConnectionRestored();
              }

              setReconnectingChat(
                false
              );

              void refreshLiveStatuses();
            }

            welcomeCallback?.(
              sessionId
            );

            return;
          }

          if (
            type ===
            "notification"
          ) {
            setSocketHealthy(
              true
            );

            armKeepaliveWatchdog(
              socket
            );

            if (
              message
                ?.metadata
                ?.subscription_type ===
              "channel.chat.message"
            ) {
              processChatNotification(
                message
              );
            } else if (
              message
                ?.metadata
                ?.subscription_type ===
              "user.whisper.message"
            ) {
              processTwitchWhisperNotification(
                message
              );
            }

            return;
          }

          if (
            type ===
            "session_keepalive"
          ) {
            setSocketHealthy(
              true
            );

            armKeepaliveWatchdog(
              socket
            );

            return;
          }

          if (
            type ===
            "session_reconnect"
          ) {
            const reconnectUrl =
              message
                ?.payload
                ?.session
                ?.reconnect_url;

            if (
              !reconnectUrl
            ) {
              return;
            }

            setSocketHealthy(
              false
            );

            setReconnectingChat(
              true
            );

            markSocketDisconnected();

            if (
              !initialStartupRef.current
            ) {
              announceConnectionLost();
            }

            clearKeepaliveTimer();

            clearReconnectTimer();

            const replacement =
              new WebSocket(
                reconnectUrl
              );

            twitchSocket.current =
              replacement;

            attachSocketHandlers(
              replacement,
              undefined,
              undefined,
              socket,
              true
            );

            return;
          }
        } catch (
          error
        ) {
          console.error(
            "EventSub error:",
            error
          );
        }
      };

    socket.onerror =
      () => {
        if (
          !receivedWelcome
        ) {
          if (
            twitchSocket.current ===
            socket
          ) {
            twitchSocket.current =
              null;
          }

          try {
            socket.close();
          } catch {
            // ignore
          }

          failureCallback?.(
            "Kunne ikke koble til Twitch EventSub."
          );
        } else if (
          twitchSocket.current ===
            socket &&
          shouldReconnect.current
        ) {
          beginConnectionLoss(
            socket
          );
        }
      };

    socket.onclose =
      () => {
        if (
          twitchSocket.current !==
          socket
        ) {
          return;
        }

        clearKeepaliveTimer();

        twitchSocket.current =
          null;

        twitchSessionId.current =
          "";

        socketConnectPromise.current =
          null;

        subscribedChannelIds.current
          .clear();

        twitchSubscriptionIds.current
          .clear();

        twitchWhisperSubscriptionIdRef.current =
          "";

        setSocketHealthy(
          false
        );

        if (
          shouldReconnect.current &&
          hasTrackedTwitchTabs()
        ) {
          setReconnectingChat(
            true
          );

          markSocketDisconnected();

          if (
            !initialStartupRef.current
          ) {
            announceConnectionLost();
          }

          scheduleSocketReconnect();
        }
      };
  }

  async function ensureTwitchSocket() {
    if (
      twitchSocket.current
        ?.readyState ===
        WebSocket.OPEN &&
      twitchSessionId.current
    ) {
      return twitchSessionId.current;
    }

    if (
      socketConnectPromise.current
    ) {
      return socketConnectPromise.current;
    }

    subscribedChannelIds.current
      .clear();

    twitchSubscriptionIds.current
      .clear();

    setSocketHealthy(
      false
    );

    const promise =
      new Promise<
        string
      >(
        (
          resolve,
          reject
        ) => {
          const socket =
            new WebSocket(
              "wss://eventsub.wss.twitch.tv/ws?keepalive_timeout_seconds=10"
            );

          twitchSocket.current =
            socket;

          const failTimer =
            window.setTimeout(
              () => {
                if (
                  socketConnectPromise.current &&
                  !twitchSessionId.current
                ) {
                  socketConnectPromise.current =
                    null;

                  try {
                    socket.close();
                  } catch {
                    // ignore
                  }

                  reject(
                    new Error(
                      ui("Twitch-tilkoblingen gikk ut på tid.", "Twitch connection timed out.")
                    )
                  );
                }
              },
              15000
            );

          attachSocketHandlers(
            socket,

            (
              sessionId
            ) => {
              window.clearTimeout(
                failTimer
              );

              socketConnectPromise.current =
                null;

              resolve(
                sessionId
              );
            },

            (
              message
            ) => {
              window.clearTimeout(
                failTimer
              );

              socketConnectPromise.current =
                null;

              reject(
                new Error(
                  message
                )
              );
            }
          );
        }
      );

    socketConnectPromise.current =
      promise;

    return promise;
  }

  function closeIdleTwitchSocket() {
    const socket =
      twitchSocket.current;

    clearKeepaliveTimer();
    clearReconnectTimer();

    twitchSocket.current =
      null;

    twitchSessionId.current =
      "";

    socketConnectPromise.current =
      null;

    subscribedChannelIds.current.clear();
    twitchSubscriptionIds.current.clear();
    twitchWhisperSubscriptionIdRef.current = "";

    try {
      socket?.close();
    } catch {
      // Tilkoblingen er allerede lukket.
    }

    setSocketHealthy(
      true
    );

    setReconnectingChat(
      false
    );
  }

  async function deleteTwitchChatSubscription(
    broadcasterId: string
  ) {
    const subscriptionId =
      twitchSubscriptionIds.current.get(
        broadcasterId
      );

    if (
      !subscriptionId
    ) {
      return;
    }

    const response =
      await fetch(
        `https://api.twitch.tv/helix/eventsub/subscriptions?id=${encodeURIComponent(
          subscriptionId
        )}`,
        {
          method:
            "DELETE",
          headers: {
            Authorization:
              `Bearer ${twitchAccessTokenRef.current}`,
            "Client-Id":
              TWITCH_CLIENT_ID,
          },
        }
      );

    if (
      !response.ok &&
      response.status !==
        404
    ) {
      throw new Error(
        ui(`Kunne ikke koble fra offline-chatten (HTTP ${response.status}).`, `Could not disconnect the offline chat (HTTP ${response.status}).`)
      );
    }

    subscribedChannelIds.current.delete(
      broadcasterId
    );

    twitchSubscriptionIds.current.delete(
      broadcasterId
    );
  }

  async function syncTwitchChatSubscriptions(
    liveIds: Set<string>
  ) {
    const savedTwitchIds =
      new Set(
        channelTabsRef.current
          .filter(
            (tab) =>
              (tab.platform ||
                "twitch") ===
                "twitch" &&
              Boolean(
                tab.broadcasterId
              ) &&
              !tab.broadcasterId.startsWith(
                "cached:"
              )
          )
          .map(
            (tab) =>
              tab.broadcasterId
          )
      );

    const wantedTrackedIds =
      savedTwitchIds;

    for (
      const broadcasterId
      of Array.from(
        subscribedChannelIds.current
      )
    ) {
      if (
        wantedTrackedIds.has(
          broadcasterId
        )
      ) {
        continue;
      }

      try {
        await deleteTwitchChatSubscription(
          broadcasterId
        );
      } catch (
        error
      ) {
        console.warn(
          "Kunne ikke koble fra offline Twitch-chat:",
          error
        );
      }
    }

    if (
      wantedTrackedIds.size ===
      0
    ) {
      if (
        twitchAccessTokenRef.current &&
        twitchUserIdRef.current
      ) {
        const sessionId =
          await ensureTwitchSocket();

        try {
          await createTwitchWhisperSubscription(
            sessionId
          );
          setSocketHealthy(true);
          setReconnectingChat(false);
        } catch (error) {
          console.warn(
            "Twitch whisper subscription:",
            error
          );
        }
      } else {
        closeIdleTwitchSocket();
      }

      updateTabs(
        (tabs) =>
          tabs.map(
            (tab) =>
              (tab.platform ||
                "twitch") ===
              "twitch"
                ? {
                    ...tab,
                    status:
                      "disconnected",
                    error:
                      "",
                  }
                : tab
          )
      );

      return;
    }

    const sessionId =
      await ensureTwitchSocket();

    try {
      await createTwitchWhisperSubscription(
        sessionId
      );
    } catch (error) {
      console.warn(
        "Twitch whisper subscription:",
        error
      );
    }

    for (
      const broadcasterId
      of wantedTrackedIds
    ) {
      if (
        subscribedChannelIds.current.has(
          broadcasterId
        )
      ) {
        continue;
      }

      try {
        await createChatSubscription(
          sessionId,
          broadcasterId
        );
      } catch (
        error
      ) {
        const message =
          error instanceof
          Error
            ? error.message
            : ui("Kunne ikke koble til chatten.", "Could not connect to chat.");

        updateTabs(
          (tabs) =>
            tabs.map(
              (tab) =>
                tab.broadcasterId ===
                broadcasterId
                  ? {
                      ...tab,
                      status:
                        "error",
                      error:
                        message,
                    }
                  : tab
            )
        );
      }
    }

    updateTabs(
      (tabs) =>
        tabs.map(
          (tab) =>
            (tab.platform ||
              "twitch") !==
            "twitch"
              ? tab
              : {
                  ...tab,
                  status:
                    liveIds.has(
                      tab.broadcasterId
                    )
                      ? subscribedChannelIds.current.has(
                          tab.broadcasterId
                        )
                        ? "live"
                        : tab.status
                      : subscribedChannelIds.current.has(
                            tab.broadcasterId
                          )
                        ? "disconnected"
                        : tab.status ===
                            "error"
                          ? "error"
                          : "disconnected",
                  error:
                    subscribedChannelIds.current.has(
                      tab.broadcasterId
                    )
                      ? ""
                      : tab.error,
                }
        )
    );

    setSocketHealthy(
      true
    );

    setReconnectingChat(
      false
    );

    if (
      subscribedChannelIds.current.size >
      0
    ) {
      setHadChatConnection(
        true
      );
    }
  }

  async function createChatSubscription(
    sessionId:
      string,

    broadcasterId:
      string
  ) {
    if (
      subscribedChannelIds.current
        .has(
          broadcasterId
        )
    ) {
      return;
    }

    const response =
      await fetch(
        "https://api.twitch.tv/helix/eventsub/subscriptions",
        {
          method:
            "POST",

          headers: {
            Authorization:
              `Bearer ${twitchAccessTokenRef.current}`,

            "Client-Id":
              TWITCH_CLIENT_ID,

            "Content-Type":
              "application/json",
          },

          body:
            JSON.stringify({
              type:
                "channel.chat.message",

              version:
                "1",

              condition: {
                broadcaster_user_id:
                  broadcasterId,

                user_id:
                  twitchUserIdRef.current,
              },

              transport: {
                method:
                  "websocket",

                session_id:
                  sessionId,
              },
            }),
        }
      );

    if (
      !response.ok
    ) {
      throw new Error(
        ui(`Kunne ikke koble til chatten (HTTP ${response.status}).`, `Could not connect to chat (HTTP ${response.status}).`)
      );
    }

    const data =
      (await response.json()) as {
        data?: Array<{
          id?: string;
        }>;
      };

    const subscriptionId =
      data.data?.[0]?.id ||
      "";

    subscribedChannelIds.current
      .add(
        broadcasterId
      );

    if (
      subscriptionId
    ) {
      twitchSubscriptionIds.current.set(
        broadcasterId,
        subscriptionId
      );
    }
  }

  async function createTwitchWhisperSubscription(
    sessionId: string
  ) {
    if (
      twitchWhisperSubscriptionIdRef.current ||
      !twitchUserIdRef.current
    ) {
      return;
    }

    const response = await fetch(
      "https://api.twitch.tv/helix/eventsub/subscriptions",
      {
        method: "POST",
        headers: {
          Authorization:
            `Bearer ${twitchAccessTokenRef.current}`,
          "Client-Id": TWITCH_CLIENT_ID,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          type: "user.whisper.message",
          version: "1",
          condition: {
            user_id:
              twitchUserIdRef.current,
          },
          transport: {
            method: "websocket",
            session_id: sessionId,
          },
        }),
      }
    );

    if (!response.ok) {
      throw new Error(
        ui(
          "Private Twitch-meldinger kunne ikke aktiveres.",
          "Private Twitch messages could not be enabled."
        )
      );
    }

    const data = await response.json() as {
      data?: Array<{ id?: string }>;
    };
    twitchWhisperSubscriptionIdRef.current =
      data.data?.[0]?.id || "active";
  }

  async function joinTwitchChannel(
    rawLogin:
      string,

    persist:
      boolean,

    activate:
      boolean
  ) {
    const login =
      sanitizeChannelName(
        rawLogin
      );

    if (
      !login
    ) {
      throw new Error(
        ui("Skriv inn et kanalnavn.", "Enter a channel name.")
      );
    }

    const user =
      await getTwitchUserByLogin(
        login
      );

    cacheChannel(
      user
    );

    const existingLive =
      channelTabsRef.current
        .find(
          (
            tab
          ) =>
            tab.broadcasterId ===
              user.id &&
            tab.status ===
              "live"
        );

    if (
      existingLive
    ) {
      if (
        persist
      ) {
        rememberChannel(
          user.login
        );
      }

      if (
        activate
      ) {
        activateChannel(
          user.id
        );
      }

      return;
    }

    const placeholder =
      channelTabsRef.current
        .find(
          (
            tab
          ) =>
            tab.login ===
            user.login.toLowerCase()
        );

    const linkedYouTube =
      linkedYouTubeChannelsRef.current
        .find(
          (
            item
          ) =>
            item.twitchLogin ===
            user.login.toLowerCase()
        );

    const linkedKick =
      linkedKickChannelsRef.current
        .find(
          (item) =>
            item.hostPlatform ===
              "twitch" &&
            item.hostKey ===
              user.login.toLowerCase()
        );

    const twitchStoredMessages =
      placeholder
        ?.messages.filter(
          (message) =>
            message.platform !==
              "youtube" &&
            message.platform !==
              "kick"
        ).length
        ? placeholder.messages.filter(
            (message) =>
              message.platform !==
                "youtube" &&
              message.platform !==
                "kick"
          )
        : await loadStoredChannelHistory(
            user.login
          );

    const youtubeStoredMessages =
      linkedYouTube
        ? placeholder
            ?.messages.filter(
              (
                message
              ) =>
                message.platform ===
                "youtube"
            ).length
          ? placeholder.messages.filter(
              (
                message
              ) =>
                message.platform ===
                "youtube"
            )
          : await loadStoredChannelHistory(
              linkedYouTube.channelId,
              "youtube"
            )
        : [];

    const kickStoredMessages =
      linkedKick
        ? placeholder
            ?.messages.filter(
              (message) =>
                message.platform ===
                "kick"
            ).length
          ? placeholder.messages.filter(
              (message) =>
                message.platform ===
                "kick"
            )
          : await loadStoredChannelHistory(
              linkedKick.broadcasterUserId,
              "kick"
            )
        : [];

    const storedMessages =
      [
        ...twitchStoredMessages,
        ...youtubeStoredMessages,
        ...kickStoredMessages,
      ]
        .filter(
          (
            message,
            index,
            all
          ) =>
            all.findIndex(
              (
                candidate
              ) =>
                candidate.id ===
                message.id
            ) ===
            index
        )
        .sort(
          (
            a,
            b
          ) =>
            a.timestampMs -
            b.timestampMs
        );

    const newTab:
      ChannelTab = {
        broadcasterId:
          user.id,

        login:
          user.login.toLowerCase(),

        displayName:
          user.display_name,

        profileImageUrl:
          user.profile_image_url,

        isLive:
          placeholder?.isLive ||
          false,

        canModerate:
          user.id === twitchUserIdRef.current ||
          moderatedChannelIdsRef.current.has(user.id),

        status:
          "joining",

        error:
          "",

        messages:
          storedMessages,

        hasMention:
          placeholder?.hasMention ||
          false,

        platform:
          "twitch",

        youtubeChannelId:
          linkedYouTube?.channelId ||
          placeholder?.youtubeChannelId,

        youtubeUploadsPlaylistId:
          linkedYouTube?.uploadsPlaylistId ||
          placeholder?.youtubeUploadsPlaylistId,

        youtubeVideoId:
          placeholder?.youtubeVideoId,

        youtubeLiveChatId:
          placeholder?.youtubeLiveChatId,

        youtubeIsLive:
          placeholder?.youtubeIsLive ||
          false,

        kickBroadcasterUserId:
          linkedKick?.broadcasterUserId ||
          placeholder?.kickBroadcasterUserId,

        kickChannelSlug:
          linkedKick?.slug ||
          placeholder?.kickChannelSlug,

        kickIsLive:
          placeholder?.kickIsLive ||
          false,
      };

    if (
      placeholder
    ) {
      const wasActive =
        activeChannelIdRef.current ===
          placeholder.broadcasterId;

      updateTabs(
        (
          tabs
        ) =>
          tabs.map(
            (
              tab
            ) =>
              tab.login ===
              user.login.toLowerCase()
                ? newTab
                : tab
          )
      );

      if (
        wasActive ||
        activate
      ) {
        activeChannelIdRef.current =
          user.id;

        setActiveChannelId(
          user.id
        );

        saveActiveChannel(
          user.login
        );
      }
    } else {
      updateTabs(
        (
          tabs
        ) => [
          ...tabs,
          newTab,
        ]
      );

      if (
        activate
      ) {
        activateChannel(
          user.id
        );
      }
    }

    try {
      shouldReconnect.current =
        true;

      await loadChannelBadges(
        user.id
      );

      updateTabs(
        (tabs) =>
          tabs.map(
            (tab) =>
              tab.broadcasterId ===
              user.id
                ? {
                    ...tab,
                    canModerate:
                      user.id === twitchUserIdRef.current ||
                      moderatedChannelIdsRef.current.has(user.id),
                  }
                : tab
          )
      );

      // Under gjenoppretting venter vi til alle lagrede kanaler er lagt inn,
      // slik at én samlet sjekk kan koble til chatten for alle kanalene.
      if (
        persist ||
        activate
      ) {
        await refreshLiveStatuses();
      }

      if (
        persist
      ) {
        rememberChannel(
          user.login
        );
      }
    } catch (
      error
    ) {
      const errorMessage =
        error instanceof
        Error
          ? error.message
          : "Ukjent feil.";

      updateTabs(
        (
          tabs
        ) =>
          tabs.map(
            (
              tab
            ) =>
              tab.broadcasterId ===
              user.id
                ? {
                    ...tab,

                    status:
                      "error",

                    error:
                      errorMessage,
                  }
                : tab
          )
      );

      throw error;
    }
  }

  async function restoreSavedChannels() {
    const preferred =
      localStorage.getItem(
        ACTIVE_CHANNEL_KEY
      );

    for (
      const login
      of savedChannelLoginsRef.current
    ) {
      try {
        await joinTwitchChannel(
          login,
          false,
          false
        );
      } catch (
        error
      ) {
        console.error(
          `Kunne ikke gjenopprette ${login}:`,
          error
        );
      }
    }

    const tab =
      channelTabsRef.current
        .find(
          (
            item
          ) =>
            item.login ===
            preferred
        ) ||
      channelTabsRef.current[
        0
      ];

    if (
      tab
    ) {
      activateChannel(
        tab.broadcasterId
      );
    }

    await refreshLiveStatuses();

    if (
      youtubeConnected
    ) {
      await refreshSavedYouTubeLiveStatuses();
    }

    initialStartupRef.current =
      false;
  }

  async function finishTwitchLogin(
    tokenData:
      TwitchTokenResponse
  ) {
    setTwitchConnectionError("");
    try {
      await saveTwitchRefreshToken(
        tokenData.refresh_token
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke lagre refresh token:",
        safeDiagnosticError(error)
      );
    }

    twitchAccessTokenRef.current =
      tokenData.access_token;

    const user =
      await getLoggedInTwitchUser(
        tokenData.access_token
      );

    twitchUserIdRef.current =
      user.id;

    twitchUserLoginRef.current =
      user.login;

    setTwitchUserName(
      user.display_name
    );

    setTwitchProfileImage(
      user.profile_image_url
    );

    await loadModeratedChannels(
      tokenData.access_token,
      user.id
    );

    await loadGlobalBadges(
      tokenData.access_token
    );

    shouldReconnect.current =
      true;

    setHasSavedTwitchSession(
      true
    );

    setTwitchConnected(
      true
    );

    setConnectingTwitch(
      false
    );

    setTwitchLogin(
      null
    );

    setTwitchError(
      ""
    );

    await restoreSavedChannels();
  }

  async function restoreTwitchLogin() {
    setTwitchConnectionError("");
    try {
      const refreshToken =
        await invoke<
          string | null
        >(
          "load_twitch_refresh_token"
        );

      if (
        !refreshToken
      ) {
        setHasSavedTwitchSession(
          false
        );

        return;
      }

      setHasSavedTwitchSession(
        true
      );

      setConnectingTwitch(
        true
      );

      const body =
        new URLSearchParams({
          client_id:
            TWITCH_CLIENT_ID,

          grant_type:
            "refresh_token",

          refresh_token:
            refreshToken,
        });

      const response =
        await fetch(
          "https://id.twitch.tv/oauth2/token",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },

            body:
              body.toString(),
          }
        );

      if (
        !response.ok
      ) {
        if (
          response.status ===
            400 ||
          response.status ===
            401
        ) {
          setHasSavedTwitchSession(
            false
          );

          setConnectingTwitch(
            false
          );

          setTwitchError(
            ui("Twitch-innloggingen er utløpt. Åpne Kontoer og logg inn med Twitch igjen.", "Twitch sign-in has expired. Open Accounts and sign in with Twitch again.")
          );

          setTwitchConnectionError(
            ui("Twitch-innloggingen er utløpt.", "Twitch sign-in has expired.")
          );

          return;
        }

        throw new Error(
          ui("Kunne ikke fornye Twitch-innloggingen.", "Could not renew the Twitch sign-in.")
        );
      }

      await finishTwitchLogin(
        (
          await response.json()
        ) as TwitchTokenResponse
      );
    } catch (
      error
    ) {
      setConnectingTwitch(
        false
      );

      setTwitchError(
        error instanceof
        Error
          ? error.message
          : ui("Kunne ikke gjenopprette Twitch-innloggingen.", "Could not restore the Twitch sign-in.")
      );

      setTwitchConnectionError(
        error instanceof Error
          ? error.message
          : ui("Kunne ikke gjenopprette Twitch-innloggingen.", "Could not restore the Twitch sign-in.")
      );
    } finally {
      setRestoringSession(
        false
      );

      if (
        !twitchAccessTokenRef.current
      ) {
        initialStartupRef.current =
          false;
      }
    }
  }

  async function waitForTwitchLogin(
    deviceCode:
      string,

    interval:
      number,

    expiresIn:
      number
  ) {
    const startedAt =
      Date.now();

    while (
      Date.now() -
        startedAt <
      expiresIn *
        1000
    ) {
      await new Promise(
        (
          resolve
        ) =>
          setTimeout(
            resolve,
            interval *
              1000
          )
      );

      const body =
        new URLSearchParams({
          client_id:
            TWITCH_CLIENT_ID,

          scopes:
            TWITCH_SCOPES,

          device_code:
            deviceCode,

          grant_type:
            "urn:ietf:params:oauth:grant-type:device_code",
        });

      const response =
        await fetch(
          "https://id.twitch.tv/oauth2/token",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },

            body:
              body.toString(),
          }
        );

      if (
        response.ok
      ) {
        await finishTwitchLogin(
          (
            await response.json()
          ) as TwitchTokenResponse
        );

        return;
      }

      const errorData =
        await response.json();

      if (
        errorData.message ===
        "authorization_pending"
      ) {
        continue;
      }

      throw new Error(
        ui("Twitch-innloggingen mislyktes.", "Twitch sign-in failed.")
      );
    }

    throw new Error(
      ui("Twitch-koden gikk ut på tid.", "The Twitch code timed out.")
    );
  }

  async function connectTwitch() {
    setTwitchConnectionError("");
    primeMentionSound();

    initialStartupRef.current =
      false;

    setRestoringSession(
      false
    );

    setConnectingTwitch(
      true
    );

    setTwitchConnected(
      false
    );

    setTwitchError(
      ""
    );

    if (
      channelTabsRef.current.length ===
      0
    ) {
      preloadSavedChannelTabs();
    }

    setReplyingTo(
      null
    );

    setUserCard(
      null
    );

    setProfileMenuOpen(
      false
    );

    setShowSettings(
      false
    );

    setShowEmotePicker(
      false
    );

    activeChannelIdRef.current =
      "";

    setActiveChannelId(
      ""
    );

    twitchAccessTokenRef.current =
      "";

    twitchUserIdRef.current =
      "";

    twitchUserLoginRef.current =
      "";

    moderatedChannelIdsRef.current =
      new Set();

    globalBadgeMap.current =
      {};

    channelBadgeMaps.current =
      {};

    subscribedChannelIds.current
      .clear();

    twitchSubscriptionIds.current
      .clear();

    processedEventIds.current
      .clear();

    shouldReconnect.current =
      false;

    outageAnnounced.current =
      false;

    setSocketHealthy(
      false
    );

    setHadChatConnection(
      false
    );

    setReconnectingChat(
      false
    );

    clearKeepaliveTimer();

    clearReconnectTimer();

    socketConnectPromise.current =
      null;

    twitchSocket.current
      ?.close();

    twitchSocket.current =
      null;

    twitchSessionId.current =
      "";

    try {
      const body =
        new URLSearchParams({
          client_id:
            TWITCH_CLIENT_ID,

          scopes:
            TWITCH_SCOPES,
        });

      const response =
        await fetch(
          "https://id.twitch.tv/oauth2/device",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },

            body:
              body.toString(),
          }
        );

      if (
        !response.ok
      ) {
        throw new Error(
          ui("Kunne ikke starte Twitch-innloggingen.", "Could not start Twitch sign-in.")
        );
      }

      const data =
        (
          await response.json()
        ) as TwitchDeviceResponse;

      setTwitchLogin(
        data
      );

      await openUrl(
        data.verification_uri
      );

      await waitForTwitchLogin(
        data.device_code,
        data.interval,
        data.expires_in
      );
    } catch (
      error
    ) {
      setConnectingTwitch(
        false
      );

      if (
        error instanceof
        Error
      ) {
        setTwitchError(
          error.message
        );
      }

      setTwitchConnectionError(
        error instanceof Error
          ? error.message
          : ui("Twitch-innloggingen mislyktes.", "Twitch sign-in failed.")
      );
    }
  }

  async function disconnectTwitch() {
    setTwitchConnectionError("");
    shouldReconnect.current =
      false;

    clearKeepaliveTimer();

    clearReconnectTimer();

    setReplyingTo(
      null
    );

    setUserCard(
      null
    );

    setProfileMenuOpen(
      false
    );

    setShowSettings(
      false
    );

    setShowEmotePicker(
      false
    );

    setHasSavedTwitchSession(
      false
    );

    const accessToken =
      twitchAccessTokenRef.current;

    if (
      accessToken
    ) {
      try {
        const body =
          new URLSearchParams({
            client_id:
              TWITCH_CLIENT_ID,

            token:
              accessToken,
          });

        await fetch(
          "https://id.twitch.tv/oauth2/revoke",
          {
            method:
              "POST",

            headers: {
              "Content-Type":
                "application/x-www-form-urlencoded",
            },

            body:
              body.toString(),
          }
        );
      } catch {
        // lokal logout
      }
    }

    await deleteSavedTwitchLogin()
      .catch(
        () =>
          undefined
      );

    twitchSocket.current
      ?.close();

    twitchSocket.current =
      null;

    twitchSessionId.current =
      "";

    socketConnectPromise.current =
      null;

    subscribedChannelIds.current
      .clear();

    twitchSubscriptionIds.current
      .clear();

    moderatedChannelIdsRef.current =
      new Set();

    twitchAccessTokenRef.current =
      "";

    twitchUserIdRef.current =
      "";

    twitchUserLoginRef.current =
      "";

    activeChannelIdRef.current =
      "";

    outageAnnounced.current =
      false;

    replaceTabs(
      []
    );

    setActiveChannelId(
      ""
    );

    setTwitchConnected(
      false
    );

    setConnectingTwitch(
      false
    );

    setTwitchLogin(
      null
    );

    setTwitchUserName(
      ""
    );

    setTwitchProfileImage(
      ""
    );

    setSocketHealthy(
      false
    );

    setHadChatConnection(
      false
    );

    setReconnectingChat(
      false
    );
  }

  function openLinkKickToTab(
    tab: ChannelTab
  ) {
    setPlatformMenu(
      null
    );
    setTabContextMenu(
      null
    );

    if (
      tab.platform ===
      "kick"
    ) {
      return;
    }

    setLinkKickTargetId(
      tab.broadcasterId
    );
    setLinkKickInput(
      ""
    );
    setLinkKickError(
      ""
    );
    setShowLinkKickToTab(
      true
    );
  }

  async function linkKickToTab() {
    const target =
      channelTabsRef.current.find(
        (tab) =>
          tab.broadcasterId ===
          linkKickTargetId
      );

    if (
      !target ||
      target.platform ===
        "kick"
    ) {
      setLinkKickError(
        ui("Fant ikke fanen Kick skal kobles til.", "Could not find the tab to connect Kick to.")
      );
      return;
    }

    if (
      !kickConnected
    ) {
      setLinkKickError(
        ui("Koble til Kick fra Kontoer først.", "Connect Kick from Accounts first.")
      );
      return;
    }

    if (
      !kickPublicWebhookReady
    ) {
      setLinkKickError(
        ui("FyFlade sin Kick-tjeneste er ikke klar. Vent litt og prøv igjen.", "FyFlade's Kick service is not ready. Wait a moment and try again.")
      );
      return;
    }

    if (
      !kickWebhookConfigured
    ) {
      setLinkKickError(
        ui("FyFlade sin Kick-chat er ikke ferdig konfigurert ennå.", "FyFlade's Kick chat is not fully configured yet.")
      );
      return;
    }

    if (
      !linkKickInput.trim()
    ) {
      setLinkKickError(
        ui("Skriv inn Kick-kanalnavn eller kick.com/kanalnavn.", "Enter a Kick channel name or kick.com/channel-name.")
      );
      return;
    }

    setLinkingKickChannel(
      true
    );
    setLinkKickError(
      ""
    );

    try {
      const {
        channel,
        isLive,
      } =
        await resolveKickChannel(
          linkKickInput
        );

      const standalone =
        channelTabsRef.current.find(
          (tab) =>
            tab.platform ===
              "kick" &&
            tab.kickBroadcasterUserId ===
              channel.broadcasterUserId
        );

      const storedKick =
        await loadStoredChannelHistory(
          channel.broadcasterUserId,
          "kick"
        );

      const extraMessages = [
        ...storedKick,
        ...(standalone?.messages ||
          []),
      ];

      if (
        target.kickBroadcasterUserId &&
        target.kickBroadcasterUserId !==
          channel.broadcasterUserId
      ) {
        forgetLinkedKickChannelForTab(
          target
        );
      }

      rememberLinkedKickChannel(
        target,
        channel
      );
      forgetKickChannel(
        channel.broadcasterUserId
      );

      updateTabs(
        (tabs) =>
          tabs
            .filter(
              (tab) =>
                !standalone ||
                tab.broadcasterId !==
                  standalone.broadcasterId
            )
            .map(
              (tab) => {
                if (
                  tab.broadcasterId !==
                  target.broadcasterId
                ) {
                  return tab;
                }

                const merged = [
                  ...tab.messages.filter(
                    (message) =>
                      message.platform !==
                      "kick"
                  ),
                  ...extraMessages,
                ]
                  .filter(
                    (
                      message,
                      index,
                      all
                    ) =>
                      all.findIndex(
                        (candidate) =>
                          candidate.id ===
                          message.id
                      ) ===
                      index
                  )
                  .sort(
                    (a, b) =>
                      a.timestampMs -
                      b.timestampMs
                  );

                return {
                  ...tab,
                  kickBroadcasterUserId:
                    channel.broadcasterUserId,
                  kickChannelSlug:
                    channel.slug,
                  kickIsLive:
                    isLive,
                  messages:
                    merged,
                };
              }
            )
      );

      await ensureKickEventSubscriptions(
        channel.broadcasterUserId
      );

      setShowLinkKickToTab(
        false
      );
      setLinkKickInput(
        ""
      );
      setLinkKickTargetId(
        ""
      );
    } catch (
      error
    ) {
      setLinkKickError(
        error instanceof
        Error
          ? error.message
          : ui("Kunne ikke koble Kick-kanalen til fanen.", "Could not connect the Kick channel to the tab.")
      );
    } finally {
      setLinkingKickChannel(
        false
      );
    }
  }

  function unlinkKickFromTab(
    tab: ChannelTab
  ) {
    setPlatformMenu(
      null
    );
    setTabContextMenu(
      null
    );

    forgetLinkedKickChannelForTab(
      tab
    );

    updateTabs(
      (tabs) =>
        tabs.map(
          (item) =>
            item.broadcasterId ===
            tab.broadcasterId
              ? {
                  ...item,
                  kickBroadcasterUserId:
                    undefined,
                  kickChannelSlug:
                    undefined,
                  kickIsLive:
                    false,
                  messages:
                    item.messages.filter(
                      (message) =>
                        message.platform !==
                        "kick"
                    ),
                }
              : item
        )
    );
  }

  async function openKickTabChannel(
    tab: ChannelTab
  ) {
    const slug =
      tab.kickChannelSlug ||
      (tab.platform ===
      "kick"
        ? tab.login
        : "");

    if (
      !slug
    ) {
      return;
    }

    try {
      await openUrl(
        `https://kick.com/${encodeURIComponent(
          slug
        )}`
      );
    } catch (
      error
    ) {
      console.error(
        "Kunne ikke åpne Kick-kanalen:",
        error
      );
    }
  }

  async function mergeStandaloneYouTubeIntoTwitch(
    youtubeTab: ChannelTab,
    twitchTab: ChannelTab
  ) {
    const youtubeChannelId =
      youtubeTab.youtubeChannelId ||
      youtubeTab.login;

    if (
      !youtubeChannelId ||
      (twitchTab.platform ||
        "twitch") !==
        "twitch"
    ) {
      throw new Error(
        ui(
          "Kan ikke slå sammen disse kanalene.",
          "These channels cannot be merged."
        )
      );
    }

    const channel:
      SavedYouTubeChannel = {
      channelId:
        youtubeChannelId,
      name:
        youtubeTab.displayName,
      avatarUrl:
        youtubeTab.profileImageUrl,
      uploadsPlaylistId:
        youtubeTab.youtubeUploadsPlaylistId ||
        "",
    };
    const wasActive =
      activeChannelIdRef.current ===
      youtubeTab.broadcasterId;

    stopYouTubeChatPoll(
      youtubeTab.broadcasterId
    );
    rememberLinkedYouTubeChannel(
      twitchTab.login,
      channel
    );
    forgetYouTubeChannel(
      youtubeChannelId
    );

    updateTabs(
      (tabs) =>
        tabs
          .filter(
            (tab) =>
              tab.broadcasterId !==
              youtubeTab.broadcasterId
          )
          .map(
            (tab) => {
              if (
                tab.broadcasterId !==
                twitchTab.broadcasterId
              ) {
                return tab;
              }

              const merged = [
                ...tab.messages,
                ...youtubeTab.messages.filter(
                  (message) =>
                    message.platform ===
                    "youtube"
                ),
              ]
                .filter(
                  (
                    message,
                    index,
                    all
                  ) =>
                    all.findIndex(
                      (candidate) =>
                        candidate.id ===
                        message.id
                    ) === index
                )
                .sort(
                  (a, b) =>
                    a.timestampMs -
                    b.timestampMs
                );

              return {
                ...tab,
                youtubeChannelId,
                youtubeUploadsPlaylistId:
                  youtubeTab.youtubeUploadsPlaylistId,
                youtubeVideoId:
                  youtubeTab.youtubeVideoId,
                youtubeLiveChatId:
                  youtubeTab.youtubeLiveChatId,
                youtubeIsLive:
                  youtubeTab.youtubeIsLive ||
                  youtubeTab.isLive,
                messages:
                  merged,
              };
            }
          )
    );

    if (
      youtubeTab.youtubeLiveChatId &&
      (
        youtubeTab.youtubeIsLive ||
        youtubeTab.isLive
      )
    ) {
      startYouTubeChatPoll(
        twitchTab.broadcasterId,
        youtubeTab.youtubeLiveChatId
      );
    }

    if (wasActive) {
      activateChannel(
        twitchTab.broadcasterId
      );
    }
  }

  async function mergeStandaloneKickIntoTwitch(
    kickTab: ChannelTab,
    user: TwitchUser
  ) {
    const kickId =
      kickTab.kickBroadcasterUserId ||
      kickTab.broadcasterId.replace(
        /^kick:/,
        ""
      );

    if (!kickId) {
      throw new Error(
        ui("Kick-fanen mangler strømmer-ID.", "The Kick tab is missing a broadcaster ID.")
      );
    }

    const kickChannel:
      SavedKickChannel = {
      broadcasterUserId:
        kickId,
      slug:
        kickTab.kickChannelSlug ||
        kickTab.login,
      name:
        kickTab.displayName,
      avatarUrl:
        kickTab.profileImageUrl,
    };

    const wasActive =
      activeChannelIdRef.current ===
      kickTab.broadcasterId;

    let twitchTab =
      channelTabsRef.current.find(
        (tab) =>
          (tab.platform ||
            "twitch") ===
            "twitch" &&
          (
            tab.broadcasterId ===
              user.id ||
            tab.login ===
              user.login.toLowerCase()
          )
      );

    if (!twitchTab) {
      await joinTwitchChannel(
        user.login,
        true,
        false
      );

      twitchTab =
        channelTabsRef.current.find(
          (tab) =>
            tab.broadcasterId ===
            user.id
        );
    } else {
      rememberChannel(
        user.login
      );
    }

    if (!twitchTab) {
      throw new Error(
        ui("Kunne ikke opprette Twitch-fanen.", "Could not create the Twitch tab.")
      );
    }

    rememberLinkedKickChannel(
      twitchTab,
      kickChannel
    );
    forgetKickChannel(
      kickId
    );

    const kickMessages =
      kickTab.messages.filter(
        (message) =>
          message.platform ===
          "kick"
      );

    updateTabs(
      (tabs) =>
        tabs
          .filter(
            (tab) =>
              tab.broadcasterId !==
              kickTab.broadcasterId
          )
          .map(
            (tab) => {
              if (
                tab.broadcasterId !==
                twitchTab!.broadcasterId
              ) {
                return tab;
              }

              const merged = [
                ...tab.messages.filter(
                  (message) =>
                    message.platform !==
                    "kick"
                ),
                ...kickMessages,
              ]
                .filter(
                  (
                    message,
                    index,
                    all
                  ) =>
                    all.findIndex(
                      (candidate) =>
                        candidate.id ===
                        message.id
                    ) ===
                    index
                )
                .sort(
                  (a, b) =>
                    a.timestampMs -
                    b.timestampMs
                );

              return {
                ...tab,
                kickBroadcasterUserId:
                  kickId,
                kickChannelSlug:
                  kickChannel.slug,
                kickIsLive:
                  kickTab.kickIsLive ||
                  kickTab.isLive,
                messages:
                  merged,
              };
            }
          )
    );

    if (wasActive) {
      activateChannel(
        twitchTab.broadcasterId
      );
    }

    await ensureKickEventSubscriptions(
      kickId
    );
  }

  async function mergeStandaloneKickIntoYouTube(
    kickTab: ChannelTab,
    channel: SavedYouTubeChannel,
    live:
      | {
          videoId: string;
          liveChatId: string;
        }
      | null
      | undefined
  ) {
    const kickId =
      kickTab.kickBroadcasterUserId ||
      kickTab.broadcasterId.replace(
        /^kick:/,
        ""
      );

    if (!kickId) {
      throw new Error(
        ui("Kick-fanen mangler strømmer-ID.", "The Kick tab is missing a broadcaster ID.")
      );
    }

    const kickChannel:
      SavedKickChannel = {
      broadcasterUserId:
        kickId,
      slug:
        kickTab.kickChannelSlug ||
        kickTab.login,
      name:
        kickTab.displayName,
      avatarUrl:
        kickTab.profileImageUrl,
    };

    const wasActive =
      activeChannelIdRef.current ===
      kickTab.broadcasterId;

    const youtubeTabId =
      `youtube-channel:${channel.channelId}`;

    let youtubeTab =
      channelTabsRef.current.find(
        (tab) =>
          tab.platform ===
            "youtube" &&
          tab.youtubeChannelId ===
            channel.channelId
      );

    const kickMessages =
      kickTab.messages.filter(
        (message) =>
          message.platform ===
          "kick"
      );

    rememberYouTubeChannel(
      channel
    );
    forgetKickChannel(
      kickId
    );

    if (!youtubeTab) {
      const youtubeMessages =
        await loadStoredChannelHistory(
          channel.channelId,
          "youtube"
        );

      const merged = [
        ...youtubeMessages,
        ...kickMessages,
      ]
        .filter(
          (
            message,
            index,
            all
          ) =>
            all.findIndex(
              (candidate) =>
                candidate.id ===
                message.id
            ) ===
            index
        )
        .sort(
          (a, b) =>
            a.timestampMs -
            b.timestampMs
        );

      const created:
        ChannelTab = {
        broadcasterId:
          youtubeTabId,
        login:
          channel.channelId,
        displayName:
          channel.name,
        profileImageUrl:
          channel.avatarUrl,
        isLive:
          Boolean(
            live
          ),
        canModerate:
          false,
        status:
          live
            ? "joining"
            : "disconnected",
        error:
          "",
        messages:
          merged,
        hasMention:
          false,
        platform:
          "youtube",
        youtubeChannelId:
          channel.channelId,
        youtubeUploadsPlaylistId:
          channel.uploadsPlaylistId,
        youtubeVideoId:
          live?.videoId,
        youtubeLiveChatId:
          live?.liveChatId,
        youtubeIsLive:
          Boolean(
            live
          ),
        kickBroadcasterUserId:
          kickId,
        kickChannelSlug:
          kickChannel.slug,
        kickIsLive:
          kickTab.kickIsLive ||
          kickTab.isLive,
      };

      updateTabs(
        (tabs) => [
          ...tabs.filter(
            (tab) =>
              tab.broadcasterId !==
              kickTab.broadcasterId
          ),
          created,
        ]
      );

      youtubeTab =
        created;
    } else {
      const youtubeTabIdExisting =
        youtubeTab.broadcasterId;

      updateTabs(
        (tabs) =>
          tabs
            .filter(
              (tab) =>
                tab.broadcasterId !==
                kickTab.broadcasterId
            )
            .map(
              (tab) => {
                if (
                  tab.broadcasterId !==
                  youtubeTabIdExisting
                ) {
                  return tab;
                }

                const merged = [
                  ...tab.messages.filter(
                    (message) =>
                      message.platform !==
                      "kick"
                  ),
                  ...kickMessages,
                ]
                  .filter(
                    (
                      message,
                      index,
                      all
                    ) =>
                      all.findIndex(
                        (candidate) =>
                          candidate.id ===
                          message.id
                      ) ===
                      index
                  )
                  .sort(
                    (a, b) =>
                      a.timestampMs -
                      b.timestampMs
                  );

                return {
                  ...tab,
                  displayName:
                    channel.name,
                  profileImageUrl:
                    channel.avatarUrl,
                  youtubeUploadsPlaylistId:
                    channel.uploadsPlaylistId,
                  youtubeVideoId:
                    live?.videoId,
                  youtubeLiveChatId:
                    live?.liveChatId,
                  youtubeIsLive:
                    Boolean(
                      live
                    ),
                  isLive:
                    Boolean(
                      live
                    ),
                  kickBroadcasterUserId:
                    kickId,
                  kickChannelSlug:
                    kickChannel.slug,
                  kickIsLive:
                    kickTab.kickIsLive ||
                    kickTab.isLive,
                  messages:
                    merged,
                };
              }
            )
      );

      youtubeTab = {
        ...youtubeTab,
        kickBroadcasterUserId:
          kickId,
        kickChannelSlug:
          kickChannel.slug,
      };
    }

    rememberLinkedKickChannel(
      youtubeTab,
      kickChannel
    );

    if (
      live
    ) {
      startYouTubeChatPoll(
        youtubeTab.broadcasterId,
        live.liveChatId
      );
    }

    if (wasActive) {
      activateChannel(
        youtubeTab.broadcasterId
      );
    }

    await ensureKickEventSubscriptions(
      kickId
    );
  }

  function openLinkYouTubeToTwitch(
    tab:
      ChannelTab
  ) {
    setTabContextMenu(
      null
    );

    setLinkYoutubeTargetId(
      tab.broadcasterId
    );

    setLinkYoutubeInput(
      ""
    );

    setLinkYoutubeError(
      ""
    );

    setShowLinkYoutubeToTab(
      true
    );
  }

  async function linkYouTubeToTwitchTab() {
    const target =
      channelTabsRef.current
        .find(
          (
            tab
          ) =>
            tab.broadcasterId ===
            linkYoutubeTargetId
        );

    if (
      !target ||
      target.platform ===
        "youtube"
    ) {
      setLinkYoutubeError(
        ui("Fant ikke fanen YouTube skal kobles til.", "Could not find the tab to connect YouTube to.")
      );
      return;
    }

    if (
      !youtubeConnected
    ) {
      setLinkYoutubeError(
        ui("Koble til YouTube fra Kontoer først.", "Connect YouTube from Accounts first.")
      );
      return;
    }

    if (
      !linkYoutubeInput.trim()
    ) {
      setLinkYoutubeError(
        ui("Lim inn @handle, YouTube-kanal-URL, kanal-ID eller video-/direktesendings-URL.", "Paste an @handle, YouTube channel URL, channel ID or video/live URL.")
      );
      return;
    }

    setLinkingYoutube(
      true
    );
    setLinkYoutubeError(
      ""
    );

    try {
      const {
        channel,
        live,
      } =
        await resolveYouTubeChannelInput(
          linkYoutubeInput
        );

      if (
        target.platform ===
        "kick"
      ) {
        await mergeStandaloneKickIntoYouTube(
          target,
          channel,
          live
        );

        setShowLinkYoutubeToTab(
          false
        );
        setLinkYoutubeInput(
          ""
        );
        setLinkYoutubeTargetId(
          ""
        );
        return;
      }

      // Hvis YouTube-kanalen allerede ligger som egen fane,
      // flyttes historikken inn i Twitch-fanen og den separate fanen fjernes.
      const standalone =
        channelTabsRef.current
          .find(
            (
              tab
            ) =>
              tab.platform ===
                "youtube" &&
              tab.youtubeChannelId ===
                channel.channelId
          );

      if (
        standalone
      ) {
        stopYouTubeChatPoll(
          standalone.broadcasterId
        );
      }

      if (
        target.youtubeChannelId &&
        target.youtubeChannelId !==
          channel.channelId
      ) {
        stopYouTubeChatPoll(
          target.broadcasterId
        );
      }

      const storedYouTube =
        await loadStoredChannelHistory(
          channel.channelId,
          "youtube"
        );

      const extraMessages = [
        ...storedYouTube,
        ...(standalone?.messages ||
          []),
      ];

      rememberLinkedYouTubeChannel(
        target.login,
        channel
      );

      // Ikke behold den samme YouTube-kanalen som separat lagret fane.
      forgetYouTubeChannel(
        channel.channelId
      );

      updateTabs(
        (
          tabs
        ) =>
          tabs
            .filter(
              (
                tab
              ) =>
                !standalone ||
                tab.broadcasterId !==
                  standalone.broadcasterId
            )
            .map(
              (
                tab
              ) => {
                if (
                  tab.broadcasterId !==
                  target.broadcasterId
                ) {
                  return tab;
                }

                const merged = [
                  ...tab.messages,
                  ...extraMessages,
                ]
                  .filter(
                    (
                      message,
                      index,
                      all
                    ) =>
                      all.findIndex(
                        (
                          candidate
                        ) =>
                          candidate.id ===
                          message.id
                      ) ===
                      index
                  )
                  .sort(
                    (
                      a,
                      b
                    ) =>
                      a.timestampMs -
                      b.timestampMs
                  );

                return {
                  ...tab,
                  youtubeChannelId:
                    channel.channelId,
                  youtubeUploadsPlaylistId:
                    channel.uploadsPlaylistId,
                  youtubeVideoId:
                    live?.videoId,
                  youtubeLiveChatId:
                    live?.liveChatId,
                  youtubeIsLive:
                    Boolean(
                      live
                    ),
                  messages:
                    merged,
                };
              }
            )
      );

      if (
        live
      ) {
        startYouTubeChatPoll(
          target.broadcasterId,
          live.liveChatId
        );
      }

      setShowLinkYoutubeToTab(
        false
      );
      setLinkYoutubeInput(
        ""
      );
      setLinkYoutubeTargetId(
        ""
      );
    } catch (
      error
    ) {
      setLinkYoutubeError(
        error instanceof
        Error
          ? error.message
          : ui("Kunne ikke koble YouTube-kanalen til Twitch-fanen.", "Could not connect the YouTube channel to the Twitch tab.")
      );
    } finally {
      setLinkingYoutube(
        false
      );
    }
  }

  function unlinkYouTubeFromTwitchTab(
    tab:
      ChannelTab
  ) {
    setTabContextMenu(
      null
    );

    stopYouTubeChatPoll(
      tab.broadcasterId
    );

    forgetLinkedYouTubeChannel(
      tab.login
    );

    updateTabs(
      (
        tabs
      ) =>
        tabs.map(
          (
            item
          ) =>
            item.broadcasterId ===
            tab.broadcasterId
              ? {
                  ...item,
                  youtubeChannelId:
                    undefined,
                  youtubeUploadsPlaylistId:
                    undefined,
                  youtubeVideoId:
                    undefined,
                  youtubeLiveChatId:
                    undefined,
                  youtubeIsLive:
                    false,
                  messages:
                    item.messages.filter(
                      (
                        message
                      ) =>
                        message.platform !==
                        "youtube"
                    ),
                }
              : item
        )
    );
  }

